    fn validation_fee_policy_registry(
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<Option<ValidationFeePolicyRegistryV1>, Error> {
        let Some(custom) = state_transaction
            .world
            .parameters()
            .custom()
            .get(&ValidationFeePolicyRegistryV1::parameter_id())
        else {
            return Ok(None);
        };
        let registry =
            ValidationFeePolicyRegistryV1::from_custom_parameter(custom).ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee policy registry is malformed".into(),
                )
            })?;
        registry.validate().map_err(|error| {
            InstructionExecutionError::InvariantViolation(
                format!("validation-fee policy registry is invalid: {error}").into(),
            )
        })?;
        Ok(Some(registry))
    }

    fn validate_validation_fee_policy_proposal(
        policy: &ValidationFeePolicyV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<Option<ValidationFeePolicyRegistryV1>, Error> {
        if let Some(reason) = policy.policy_invariant_error() {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    format!("invalid validation-fee policy: {reason}").into(),
                ),
            ));
        }
        if policy.charging_mode
            == iroha_data_model::validation_fee::ValidationFeeChargingMode::PerQualifyingTransferInstruction
            && policy.treasury_payout_binding.is_none()
        {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "enabled validation-fee policy requires the exact first-release payout binding"
                        .into(),
                ),
            ));
        }
        if policy.chain_id != state_transaction.chain_id {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "validation-fee policy targets a different chain".into(),
                ),
            ));
        }
        let Some(genesis_hash) = state_transaction
            .block_hashes()
            .first()
            .map(|hash| *hash.as_ref())
        else {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee policy cannot be genesis-bound before genesis is committed".into(),
            ));
        };
        if policy.genesis_hash != genesis_hash {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "validation-fee policy genesis hash mismatch".into(),
                ),
            ));
        }
        if policy.ds_asset_id == state_transaction.gov.voting_asset_id {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "validation-fee asset must differ from the governance voting asset".into(),
                ),
            ));
        }
        let asset_definition = state_transaction
            .world
            .asset_definition(&policy.ds_asset_id)
            .map_err(Error::from)?;
        if asset_definition.spec().scale() != Some(u32::from(policy.ds_scale)) {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "validation-fee asset numeric scale differs from policy".into(),
                ),
            ));
        }
        state_transaction
            .world
            .account(&policy.treasury_account_id)
            .map_err(Error::from)?;

        if let Some(binding) = policy.treasury_payout_binding.as_ref() {
            if binding.treasury_account_id != policy.treasury_account_id
                || binding.sbd_asset_id != policy.ds_asset_id
                || binding.contract_address.subject_id() != policy.treasury_account_id
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "validation-fee treasury payout binding differs from policy".into(),
                    ),
                ));
            }
        }

        let registry = validation_fee_policy_registry(state_transaction)?;
        match registry
            .as_ref()
            .and_then(ValidationFeePolicyRegistryV1::head)
        {
            None => {
                if policy.policy_version != 1 || policy.previous_policy_hash.is_some() {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "initial validation-fee policy must be version 1 without a predecessor"
                                .into(),
                        ),
                    ));
                }
            }
            Some(head) => {
                let expected_version =
                    head.policy.policy_version.checked_add(1).ok_or_else(|| {
                        InstructionExecutionError::InvariantViolation(
                            "validation-fee policy version overflow".into(),
                        )
                    })?;
                if policy.policy_version != expected_version
                    || policy.previous_policy_hash != Some(head.policy_hash)
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee policy predecessor is stale or non-contiguous".into(),
                        ),
                    ));
                }
                if policy.effective_from_height < head.policy.effective_from_height {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee policy effective height cannot move backwards".into(),
                        ),
                    ));
                }
            }
        }
        Ok(registry)
    }

    fn validation_fee_plain_electorate_rules(
        kind: &ProposalKind,
    ) -> Option<&ValidationFeePlainElectorateRulesV1> {
        match kind {
            ProposalKind::ValidationFeePolicy(payload) => Some(&payload.plain_electorate_rules),
            ProposalKind::ValidationFeePayoutLifecycle(payload) => {
                Some(&payload.plain_electorate_rules)
            }
            ProposalKind::DeployContract(_)
            | ProposalKind::RuntimeUpgrade(_)
            | ProposalKind::SccpRouteGovernance(_) => None,
        }
    }

    fn validate_validation_fee_plain_electorate_rules(
        rules: &ValidationFeePlainElectorateRulesV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        if let Some(reason) = rules.invariant_error() {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    format!("invalid validation-fee PLAIN electorate rules: {reason}").into(),
                ),
            ));
        }
        let gov = &state_transaction.gov;
        if !gov.plain_voting_enabled
            || rules.voting_asset_id != gov.voting_asset_id
            || rules.voting_asset_id != gov.citizenship_asset_id
            || rules.bond_escrow_account != gov.bond_escrow_account
            || rules.slash_receiver_account != gov.slash_receiver_account
            || rules.ballot_amount != gov.min_bond_amount
            || rules.ballot_duration_blocks != gov.window_span
            || rules.citizenship_amount != gov.citizenship_bond_amount
            || rules.max_members != VALIDATION_FEE_PLAIN_MAX_MEMBERS_V1
            || rules.conviction_step_blocks != gov.conviction_step_blocks
            || rules.max_conviction != gov.max_conviction
            || rules.min_turnout != gov.min_turnout
            || rules.approval_threshold_numerator != gov.approval_threshold_q_num
            || rules.approval_threshold_denominator != gov.approval_threshold_q_den
        {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "validation-fee PLAIN electorate rules differ from active governance policy"
                        .into(),
                ),
            ));
        }
        Ok(())
    }

    impl Execute for gov::ProposeValidationFeePolicy {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if resolve_governance_approval_mode(state_transaction)
                != GovernanceApprovalMode::ParliamentSortitionJit
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "validation-fee policy proposals require Parliament JIT sortition".into(),
                ));
            }
            let required_bond = &state_transaction.gov.citizenship_bond_amount;
            let bonded_citizen = state_transaction
                .world
                .citizens
                .get(authority)
                .is_some_and(|record| &record.amount >= required_bond);
            if !bonded_citizen {
                return Err(InstructionExecutionError::InvariantViolation(
                    "only a currently bonded citizen may propose a validation-fee policy".into(),
                ));
            }
            validate_validation_fee_plain_electorate_rules(
                &self.plain_electorate_rules,
                state_transaction,
            )?;
            let _ = validate_validation_fee_policy_proposal(&self.policy, state_transaction)?;
            match (
                self.policy.treasury_payout_binding.as_ref(),
                self.payout_lifecycle_proposal_id,
            ) {
                (Some(_), Some(id)) if id != [0; 32] => {}
                (None, None) => {}
                (Some(_), _) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee payout policy must identify a non-zero payout lifecycle proposal"
                                .into(),
                        ),
                    ));
                }
                (None, Some(_)) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee policy without a payout binding cannot identify a payout lifecycle"
                                .into(),
                        ),
                    ));
                }
            }

            let payload = ValidationFeePolicyProposal {
                policy: self.policy.clone(),
                payout_lifecycle_proposal_id: self.payout_lifecycle_proposal_id,
                plain_electorate_rules: self.plain_electorate_rules.clone(),
            };
            // Resolve the selector against protected governance state at proposal
            // time as well as enactment time. The proposal carries no caller-made
            // authorization evidence.
            let _ = enacted_validation_fee_payout_lifecycle(&payload, state_transaction)?;
            let kind = ProposalKind::ValidationFeePolicy(payload.clone());
            let id = kind.fingerprint();
            let rid = hex::encode(id);
            let desired_mode = match self.mode {
                None | Some(gov::VotingMode::Plain) => {
                    crate::state::GovernanceReferendumMode::Plain
                }
                Some(gov::VotingMode::Zk) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee governance supports plain referendum voting only"
                                .into(),
                        ),
                    ));
                }
            };
            let now = state_transaction._curr_block.height().get();
            let minimum_start = now.saturating_add(state_transaction.gov.min_enactment_delay);
            let (start, end) = if let Some(window) = self.referendum_window {
                if window.upper < window.lower || window.lower < minimum_start {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee referendum window is invalid or starts too early"
                                .into(),
                        ),
                    ));
                }
                (window.lower, window.upper)
            } else {
                let end = minimum_start
                    .saturating_add(state_transaction.gov.window_span.max(1).saturating_sub(1));
                (minimum_start, end)
            };
            let referendum_span = end
                .checked_sub(start)
                .and_then(|distance| distance.checked_add(1))
                .ok_or_else(|| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee referendum window overflows".into(),
                        ),
                    )
                })?;
            if referendum_span != self.plain_electorate_rules.ballot_duration_blocks {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "validation-fee referendum window differs from its bound PLAIN electorate rules"
                            .into(),
                    ),
                ));
            }
            if self.policy.effective_from_height < start {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "validation-fee policy cannot become effective before its referendum window"
                            .into(),
                    ),
                ));
            }
            if self
                .policy
                .expires_after_height
                .is_some_and(|expiry| end >= expiry)
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "validation-fee referendum must close before policy expiry".into(),
                    ),
                ));
            }

            if let Some(existing) = state_transaction.world.governance_proposals.get(&id) {
                if existing.as_validation_fee_policy() != Some(&payload) {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "governance proposal id collision".into(),
                    ));
                }
                let referendum = state_transaction
                    .world
                    .governance_referenda
                    .get(&rid)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvariantViolation(
                            "existing validation-fee proposal has no referendum".into(),
                        )
                    })?;
                if referendum.h_start != start
                    || referendum.h_end != end
                    || referendum.mode != desired_mode
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "existing referendum parameters mismatch".into(),
                    ));
                }
                return Ok(());
            }

            let referendum = crate::state::GovernanceReferendumRecord {
                h_start: start,
                h_end: end,
                status: crate::state::GovernanceReferendumStatus::Proposed,
                mode: desired_mode,
            };
            state_transaction
                .world
                .governance_referenda
                .insert(rid, referendum);
            let pipeline = crate::state::GovernancePipeline::seeded(
                now,
                Some(&referendum),
                &state_transaction.gov,
            );
            let parliament_snapshot =
                Some(derive_jit_parliament_snapshot(id, now, state_transaction)?);
            state_transaction.world.governance_proposals.insert(
                id,
                crate::state::GovernanceProposalRecord {
                    proposer: authority.clone(),
                    kind,
                    created_height: now,
                    status: crate::state::GovernanceProposalStatus::Proposed,
                    pipeline,
                    parliament_snapshot,
                    finalization_evidence: None,
                    enacted_at_height: None,
                },
            );
            state_transaction
                .world
                .emit_events(Some(GovernanceEvent::ProposalSubmitted(
                    iroha_data_model::events::data::governance::GovernanceProposalSubmitted {
                        id,
                        proposer: authority.clone(),
                        contract_address: None,
                    },
                )));
            Ok(())
        }
    }

    impl Execute for gov::ProposeValidationFeePayoutLifecycle {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if resolve_governance_approval_mode(state_transaction)
                != GovernanceApprovalMode::ParliamentSortitionJit
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "validation-fee payout lifecycle proposals require Parliament JIT sortition"
                        .into(),
                ));
            }
            let required_bond = &state_transaction.gov.citizenship_bond_amount;
            let bonded_citizen = state_transaction
                .world
                .citizens
                .get(authority)
                .is_some_and(|record| &record.amount >= required_bond);
            if !bonded_citizen {
                return Err(InstructionExecutionError::InvariantViolation(
                    "only a currently bonded citizen may propose a validation-fee payout lifecycle"
                        .into(),
                ));
            }
            validate_validation_fee_plain_electorate_rules(
                &self.plain_electorate_rules,
                state_transaction,
            )?;
            if let Some(reason) = self.payout_binding.invariant_error() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        format!("invalid validation-fee payout lifecycle: {reason}").into(),
                    ),
                ));
            }
            let derived_lifecycle_seal = self.payout_binding.lifecycle_seal().map_err(|_| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    "failed to derive validation-fee payout lifecycle seal".into(),
                ))
            })?;
            if derived_lifecycle_seal == [0; 32] {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "validation-fee payout lifecycle binding derived an invalid zero seal"
                            .into(),
                    ),
                ));
            }
            let sbd_definition = state_transaction
                .world
                .asset_definition(&self.payout_binding.sbd_asset_id)
                .map_err(Error::from)?;
            if sbd_definition.spec().scale()
                != Some(u32::from(
                    iroha_data_model::validation_fee::VALIDATION_FEE_DS_SCALE,
                ))
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "validation-fee payout lifecycle SBD asset scale must be 2".into(),
                    ),
                ));
            }
            let xor_definition = state_transaction
                .world
                .asset_definition(&self.payout_binding.xor_asset_id)
                .map_err(Error::from)?;
            if xor_definition
                .spec()
                .check(self.payout_binding.min_xor_out.as_numeric())
                .is_err()
                || xor_definition
                    .spec()
                    .check(self.payout_binding.max_xor_out.as_numeric())
                    .is_err()
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "validation-fee payout lifecycle XOR bounds violate the asset specification"
                            .into(),
                    ),
                ));
            }
            for account_id in core::iter::once(&self.payout_binding.treasury_account_id)
                .chain(core::iter::once(&self.payout_binding.pool_vault_account_id))
                .chain(
                    self.payout_binding
                        .recipients
                        .iter()
                        .map(|recipient| &recipient.account_id),
                )
            {
                state_transaction
                    .world
                    .account(account_id)
                    .map_err(Error::from)?;
            }

            let payload = ValidationFeePayoutLifecycleProposal {
                payout_binding: self.payout_binding.clone(),
                plain_electorate_rules: self.plain_electorate_rules.clone(),
            };
            let kind = ProposalKind::ValidationFeePayoutLifecycle(payload.clone());
            let id = kind.fingerprint();
            let rid = hex::encode(id);
            let desired_mode = match self.mode {
                None | Some(gov::VotingMode::Plain) => {
                    crate::state::GovernanceReferendumMode::Plain
                }
                Some(gov::VotingMode::Zk) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee governance supports plain referendum voting only"
                                .into(),
                        ),
                    ));
                }
            };
            let now = state_transaction._curr_block.height().get();
            let minimum_start = now.saturating_add(state_transaction.gov.min_enactment_delay);
            let (start, end) = if let Some(window) = self.referendum_window {
                if window.upper < window.lower || window.lower < minimum_start {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee payout lifecycle referendum window is invalid or starts too early"
                                .into(),
                        ),
                    ));
                }
                (window.lower, window.upper)
            } else {
                let end = minimum_start
                    .saturating_add(state_transaction.gov.window_span.max(1).saturating_sub(1));
                (minimum_start, end)
            };
            let referendum_span = end
                .checked_sub(start)
                .and_then(|distance| distance.checked_add(1))
                .ok_or_else(|| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "validation-fee payout lifecycle referendum window overflows".into(),
                        ),
                    )
                })?;
            if referendum_span != self.plain_electorate_rules.ballot_duration_blocks {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "validation-fee payout lifecycle referendum window differs from its bound PLAIN electorate rules"
                            .into(),
                    ),
                ));
            }

            if let Some(existing) = state_transaction.world.governance_proposals.get(&id) {
                if existing.as_validation_fee_payout_lifecycle() != Some(&payload) {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "governance proposal id collision".into(),
                    ));
                }
                let referendum = state_transaction
                    .world
                    .governance_referenda
                    .get(&rid)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvariantViolation(
                            "existing validation-fee payout lifecycle has no referendum".into(),
                        )
                    })?;
                if referendum.h_start != start
                    || referendum.h_end != end
                    || referendum.mode != desired_mode
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "existing referendum parameters mismatch".into(),
                    ));
                }
                return Ok(());
            }

            let referendum = crate::state::GovernanceReferendumRecord {
                h_start: start,
                h_end: end,
                status: crate::state::GovernanceReferendumStatus::Proposed,
                mode: desired_mode,
            };
            state_transaction
                .world
                .governance_referenda
                .insert(rid, referendum);
            let pipeline = crate::state::GovernancePipeline::seeded(
                now,
                Some(&referendum),
                &state_transaction.gov,
            );
            let parliament_snapshot =
                Some(derive_jit_parliament_snapshot(id, now, state_transaction)?);
            state_transaction.world.governance_proposals.insert(
                id,
                crate::state::GovernanceProposalRecord {
                    proposer: authority.clone(),
                    kind,
                    created_height: now,
                    status: crate::state::GovernanceProposalStatus::Proposed,
                    pipeline,
                    parliament_snapshot,
                    finalization_evidence: None,
                    enacted_at_height: None,
                },
            );
            state_transaction
                .world
                .emit_events(Some(GovernanceEvent::ProposalSubmitted(
                    iroha_data_model::events::data::governance::GovernanceProposalSubmitted {
                        id,
                        proposer: authority.clone(),
                        contract_address: None,
                    },
                )));
            Ok(())
        }
    }

    fn parse_hex32_hint(raw: &str) -> Option<[u8; 32]> {
        let trimmed = raw.trim();
        let without_scheme = if let Some((scheme, rest)) = trimmed.split_once(':') {
            if scheme.is_empty() || scheme.eq_ignore_ascii_case("blake2b32") {
                rest
            } else {
                return None;
            }
        } else {
            trimmed
        };
        let body = without_scheme.trim();
        let body = body
            .strip_prefix("0x")
            .or_else(|| body.strip_prefix("0X"))
            .unwrap_or(body)
            .trim();
        if body.len() != 64 || !body.as_bytes().iter().all(u8::is_ascii_hexdigit) {
            return None;
        }
        let mut out = [0u8; 32];
        hex::decode_to_slice(body, &mut out).ok()?;
        Some(out)
    }

    impl Execute for gov::CastZkBallot {
        #[allow(clippy::too_many_lines)]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let parse_ballot_amount = |value: &norito::json::Value| -> Option<u128> {
                if let Some(n) = value.as_u64() {
                    return Some(u128::from(n));
                }
                value.as_str().and_then(|s| s.trim().parse::<u128>().ok())
            };

            let parse_duration_blocks = |value: &norito::json::Value| -> Option<u64> {
                value
                    .as_u64()
                    .or_else(|| value.as_str().and_then(|s| s.trim().parse::<u64>().ok()))
            };
            let parse_ballot_direction = |value: &norito::json::Value| -> Option<u8> {
                if let Some(n) = value.as_u64() {
                    return u8::try_from(n).ok().filter(|v| *v <= 2);
                }
                let raw = value.as_str()?.trim();
                if raw.eq_ignore_ascii_case("aye") {
                    return Some(0);
                }
                if raw.eq_ignore_ascii_case("nay") {
                    return Some(1);
                }
                if raw.eq_ignore_ascii_case("abstain") {
                    return Some(2);
                }
                raw.parse::<u8>().ok().filter(|v| *v <= 2)
            };

            if !has_permission(
                &state_transaction.world,
                authority,
                "CanSubmitGovernanceBallot",
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanSubmitGovernanceBallot".into(),
                ));
            }
            ensure_citizen_for_ballot(authority, &self.election_id, state_transaction)?;
            let id = self.election_id.clone();
            // Validate ballot proof inputs and enforce governance policy before recording state.

            // 1) Decode proof bytes from base64 (reject empty/invalid)
            let proof_bytes =
                match base64::engine::general_purpose::STANDARD.decode(self.proof_b64.as_bytes()) {
                    Ok(v) if !v.is_empty() => v,
                    _ => {
                        // Non-consensus visibility
                        state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "invalid or empty proof".into(),
                            },
                        ),
                    ));
                        return Err(InstructionExecutionError::InvariantViolation(
                            "invalid or empty proof".into(),
                        ));
                    }
                };

            state_transaction.register_confidential_proof(proof_bytes.len())?;
            let max_proof = state_transaction.zk.preverify_max_bytes;
            if max_proof > 0 && proof_bytes.len() > max_proof {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "proof exceeds configured max bytes".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "proof exceeds configured max bytes".into(),
                    ),
                ));
            }

            let public_inputs = if self.public_inputs_json.trim().is_empty() {
                None
            } else {
                let value = if let Ok(value) =
                    norito::json::from_str::<norito::json::Value>(self.public_inputs_json.as_str())
                {
                    value
                } else {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "public inputs must be valid JSON".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "public inputs must be valid JSON".into(),
                    ));
                };
                if !value.is_object() {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "public inputs must be a JSON object".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "public inputs must be a JSON object".into(),
                    ));
                }
                Some(value)
            };
            let mut lock_owner: Option<iroha_data_model::account::AccountId> = None;
            let mut lock_amount: Option<u128> = None;
            let mut lock_duration: Option<u64> = None;
            let mut lock_direction: Option<u8> = None;
            let mut root_hint_opt: Option<[u8; 32]> = None;
            let mut nullifier_hint: Option<[u8; 32]> = None;
            if let Some(val) = public_inputs.as_ref() {
                if val.get("durationBlocks").is_some() {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "public inputs must use duration_blocks".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "public inputs must use duration_blocks".into(),
                    ));
                }
                if val.get("root_hint_hex").is_some()
                    || val.get("rootHintHex").is_some()
                    || val.get("rootHint").is_some()
                {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "public inputs must use root_hint".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "public inputs must use root_hint".into(),
                    ));
                }
                if let Some(root_val) = val.get("root_hint") {
                    if !matches!(root_val, norito::json::Value::Null) {
                        let rh_str = root_val.as_str().ok_or_else(|| {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "root_hint must be 32-byte hex".into(),
                                    },
                                ),
                            ));
                            InstructionExecutionError::InvariantViolation(
                                "root_hint must be 32-byte hex".into(),
                            )
                        })?;
                        if let Some(parsed) = parse_hex32_hint(rh_str) {
                            root_hint_opt = Some(parsed);
                        } else {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "root_hint must be 32-byte hex".into(),
                                    },
                                ),
                            ));
                            return Err(InstructionExecutionError::InvariantViolation(
                                "root_hint must be 32-byte hex".into(),
                            ));
                        }
                    }
                }
                if val.get("nullifier_hex").is_some() || val.get("nullifierHex").is_some() {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "public inputs must use nullifier".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "public inputs must use nullifier".into(),
                    ));
                }
                if let Some(null_val) = val.get("nullifier") {
                    if !matches!(null_val, norito::json::Value::Null) {
                        let hex_str = null_val.as_str().ok_or_else(|| {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "nullifier must be 32-byte hex".into(),
                                    },
                                ),
                            ));
                            InstructionExecutionError::InvariantViolation(
                                "nullifier must be 32-byte hex".into(),
                            )
                        })?;
                        if let Some(parsed) = parse_hex32_hint(hex_str) {
                            nullifier_hint = Some(parsed);
                        } else {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "nullifier must be 32-byte hex".into(),
                                    },
                                ),
                            ));
                            return Err(InstructionExecutionError::InvariantViolation(
                                "nullifier must be 32-byte hex".into(),
                            ));
                        }
                    }
                }
            }

            if let Some(val) = public_inputs.as_ref() {
                if let Some(owner_val) = val.get("owner") {
                    if !matches!(owner_val, norito::json::Value::Null) {
                        let owner_str_raw = owner_val.as_str().ok_or_else(|| {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "owner must be a canonical I105 account id".into(),
                                },
                            ),
                        ));
                        InstructionExecutionError::InvariantViolation(
                            "owner must be a canonical I105 account id".into(),
                        )
                    })?;
                        let owner_str = owner_str_raw.trim();
                        if owner_str != owner_str_raw || owner_str.is_empty() {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "owner must use canonical I105 account id form".into(),
                                    },
                                ),
                            ));
                            return Err(InstructionExecutionError::InvariantViolation(
                                "owner must use canonical I105 account id form".into(),
                            ));
                        }

                        let owner_parsed = iroha_data_model::account::AccountId::parse_encoded(
                            owner_str,
                        )
                        .map(iroha_data_model::account::ParsedAccountId::into_account_id)
                        .map_err(|_| {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "owner must be a canonical I105 account id".into(),
                                    },
                                ),
                            ));
                            InstructionExecutionError::InvariantViolation(
                                "owner must be a canonical I105 account id".into(),
                            )
                        })?;
                        if owner_parsed.to_string() != owner_str {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "owner must use canonical I105 account id form".into(),
                                    },
                                ),
                            ));
                            return Err(InstructionExecutionError::InvariantViolation(
                                "owner must use canonical I105 account id form".into(),
                            ));
                        }
                        if lock_owner.is_none() {
                            lock_owner = Some(owner_parsed);
                        }
                    }
                }
                if let Some(amount_val) = val.get("amount") {
                    if !matches!(amount_val, norito::json::Value::Null) {
                        if let Some(parsed) = parse_ballot_amount(amount_val) {
                            lock_amount = Some(parsed);
                        } else {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "amount must be u128".into(),
                                    },
                                ),
                            ));
                            return Err(InstructionExecutionError::InvariantViolation(
                                "amount must be u128".into(),
                            ));
                        }
                    }
                }
                if let Some(duration_val) = val.get("duration_blocks") {
                    if !matches!(duration_val, norito::json::Value::Null) {
                        if let Some(parsed) = parse_duration_blocks(duration_val) {
                            lock_duration = Some(parsed);
                        } else {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "duration_blocks must be u64".into(),
                                    },
                                ),
                            ));
                            return Err(InstructionExecutionError::InvariantViolation(
                                "duration_blocks must be u64".into(),
                            ));
                        }
                    }
                }
                if let Some(direction_val) = val.get("direction") {
                    if !matches!(direction_val, norito::json::Value::Null) {
                        if let Some(parsed) = parse_ballot_direction(direction_val) {
                            lock_direction = Some(parsed);
                        } else {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: self.election_id.clone(),
                                        reason: "direction must be Aye, Nay, or Abstain".into(),
                                    },
                                ),
                            ));
                            return Err(InstructionExecutionError::InvariantViolation(
                                "direction must be Aye, Nay, or Abstain".into(),
                            ));
                        }
                    }
                }
            }

            let mut st = state_transaction
                .world
                .elections
                .get(&self.election_id)
                .cloned()
                .ok_or_else(|| {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "unknown election id".into(),
                            },
                        ),
                    ));
                    InstructionExecutionError::InvariantViolation("unknown election id".into())
                })?;
            if st.finalized {
                return Err(InstructionExecutionError::InvariantViolation(
                    "election already finalized".into(),
                ));
            }
            let domain_tag = if st.domain_tag.is_empty() {
                DEFAULT_NULLIFIER_DOMAIN_TAG.to_string()
            } else {
                st.domain_tag.clone()
            };

            // Early referendum existence/window checks (Zk)
            {
                let rid = self.election_id.clone();
                let now_h = state_transaction._curr_block.height().get();
                let Some(rr) = state_transaction
                    .world
                    .governance_referenda
                    .get(&rid)
                    .copied()
                else {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: rid,
                                reason: "referendum not found".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "referendum not found".into(),
                    ));
                };
                if rr.mode != crate::state::GovernanceReferendumMode::Zk {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: rid,
                                reason: "mode mismatch (expected Zk)".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "referendum mode mismatch: expected Zk".into(),
                    ));
                }
                if now_h < rr.h_start || now_h > rr.h_end {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: rid.clone(),
                                reason: "referendum not active (outside window)".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "referendum not active".into(),
                    ));
                }
                if matches!(rr.status, crate::state::GovernanceReferendumStatus::Closed) {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: rid,
                                reason: "referendum already closed".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "referendum closed".into(),
                    ));
                }
            }
            let lock_hint_present =
                lock_owner.is_some() || lock_amount.is_some() || lock_duration.is_some();
            if lock_hint_present {
                if lock_owner.is_none() || lock_amount.is_none() || lock_duration.is_none() {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "lock hints must include owner, amount, duration_blocks"
                                    .into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "lock hints must include owner, amount, duration_blocks".into(),
                    ));
                }
            } else if !state_transaction.gov.min_bond_amount.is_zero() {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "lock hints required for governance bond".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "lock hints required for governance bond".into(),
                ));
            }

            // 3) Verify the proof against the resolved VK (ZK1/H2* envelope dispatch)
            let vk_id = st
                .vk_ballot
                .clone()
                .or_else(|| {
                    state_transaction.gov.vk_ballot.as_ref().map(|v| {
                        iroha_data_model::proof::VerifyingKeyId::new(
                            v.backend.clone(),
                            v.name.clone(),
                        )
                    })
                })
                .ok_or_else(|| {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "verifying key not configured".into(),
                            },
                        ),
                    ));
                    InstructionExecutionError::InvariantViolation(
                        "verifying key not configured".into(),
                    )
                })?;
            let Some(vk_rec) = state_transaction.world.verifying_keys.get(&vk_id).cloned() else {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "verifying key not found".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "verifying key not found".into(),
                ));
            };
            if vk_rec.status != iroha_data_model::confidential::ConfidentialStatus::Active {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "verifying key is not Active".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "verifying key is not Active".into(),
                ));
            }
            if let Some(expected) = st.vk_ballot_commitment {
                if vk_rec.commitment != expected {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "verifying key commitment mismatch".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "verifying key commitment mismatch".into(),
                    ));
                }
            }
            let Some(vk_box) = vk_rec.key.clone() else {
                return Err(InstructionExecutionError::InvariantViolation(
                    "verifying key bytes not available inline".into(),
                ));
            };
            let computed_commitment = hash_vk(&vk_box);
            if computed_commitment != vk_rec.commitment {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "verifying key commitment mismatch".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "verifying key commitment mismatch".into(),
                ));
            }
            let backend = vk_id.backend.as_str();
            if vk_box.backend.as_str() != backend {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "verifying key backend mismatch".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "verifying key backend mismatch".into(),
                ));
            }
            if let Err(err) = ensure_voting_circuit_role(
                "ballot",
                backend,
                &vk_rec.circuit_id,
                VOTING_BALLOT_CIRCUIT_ID,
            ) {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "ballot verifying key circuit mismatch".into(),
                        },
                    ),
                ));
                return Err(err);
            }
            if crate::zk::is_stark_fri_v1_backend(backend) && !state_transaction.zk.stark.enabled {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "stark verification is disabled in node configuration".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "stark verification is disabled in node configuration".into(),
                ));
            }
            if let Err(err) = enforce_vk_max_proof_bytes("ballot", &vk_rec, proof_bytes.len()) {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "proof exceeds verifying key max_proof_bytes".into(),
                        },
                    ),
                ));
                return Err(err);
            }
            let proof_box =
                iroha_data_model::proof::ProofBox::new(vk_id.backend.clone(), proof_bytes.clone());
            let verify_report = crate::zk::verify_backend_with_timing_checked(
                backend,
                &proof_box,
                Some(&vk_box),
                &state_transaction.zk,
            );
            if !verify_report.ok {
                let _ = governance_slash_percent(
                    &self.election_id,
                    authority,
                    state_transaction.gov.slash_invalid_proof_bps,
                    GovernanceSlashReason::Misconduct,
                    "invalid_proof",
                    state_transaction,
                )?;
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "invalid proof".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "invalid proof".into(),
                ));
            }
            let proof_verified = true;
            let inputs = match extract_vote_public_inputs(backend, &proof_bytes) {
                Ok(inputs) => inputs,
                Err(err) => {
                    let _ = governance_slash_percent(
                        &self.election_id,
                        authority,
                        state_transaction.gov.slash_invalid_proof_bps,
                        GovernanceSlashReason::Misconduct,
                        "invalid_proof_inputs",
                        state_transaction,
                    )?;
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "invalid proof inputs".into(),
                            },
                        ),
                    ));
                    return Err(err);
                }
            };
            if let Err(err) =
                validate_open_verify_envelope_metadata("ballot", backend, &inputs.envelope, &vk_rec)
            {
                let _ = governance_slash_percent(
                    &self.election_id,
                    authority,
                    state_transaction.gov.slash_invalid_proof_bps,
                    GovernanceSlashReason::Misconduct,
                    "invalid_proof_inputs",
                    state_transaction,
                )?;
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "invalid proof inputs".into(),
                        },
                    ),
                ));
                return Err(err);
            }
            let (commit_bytes, root_bytes) = match ballot_inputs_from_columns(&inputs.columns) {
                Ok(v) => v,
                Err(err) => {
                    let _ = governance_slash_percent(
                        &self.election_id,
                        authority,
                        state_transaction.gov.slash_invalid_proof_bps,
                        GovernanceSlashReason::Misconduct,
                        "invalid_proof_inputs",
                        state_transaction,
                    )?;
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "invalid proof inputs".into(),
                            },
                        ),
                    ));
                    return Err(err);
                }
            };
            if let Some(root_hint) = root_hint_opt {
                if root_hint != root_bytes {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "root_hint does not match proof".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "root_hint does not match proof".into(),
                    ));
                }
            }
            if root_bytes != st.eligible_root {
                let _ = governance_slash_percent(
                    &self.election_id,
                    authority,
                    state_transaction.gov.slash_ineligible_proof_bps,
                    GovernanceSlashReason::IneligibleProof,
                    "ineligible_proof",
                    state_transaction,
                )?;
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "stale or unknown eligibility root".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "stale or unknown eligibility root".into(),
                ));
            }
            let nullifier = derive_ballot_nullifier(
                &domain_tag,
                &state_transaction.chain_id,
                &self.election_id,
                &commit_bytes,
            );
            if let Some(hint) = nullifier_hint {
                if hint != nullifier {
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                            iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                referendum_id: self.election_id.clone(),
                                reason: "nullifier does not match proof".into(),
                            },
                        ),
                    ));
                    return Err(InstructionExecutionError::InvariantViolation(
                        "nullifier does not match proof".into(),
                    ));
                }
            }

            // 4) Ensure a referendum record exists and open it if needed; enforce Zk mode
            {
                let rid = self.election_id.clone();
                let Some(mut rr) = state_transaction
                    .world
                    .governance_referenda
                    .get(&rid)
                    .copied()
                else {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "referendum not found".into(),
                    ));
                };
                if !matches!(rr.status, crate::state::GovernanceReferendumStatus::Open) {
                    rr.status = crate::state::GovernanceReferendumStatus::Open;
                    state_transaction
                        .world
                        .governance_referenda
                        .insert(rid.clone(), rr);
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::governance::GovernanceEvent::ReferendumOpened(
                            iroha_data_model::events::data::governance::GovernanceReferendumOpened {
                                id: rid.clone(),
                                h_start: rr.h_start,
                                h_end: rr.h_end,
                            },
                        ),
                    ));
                }
            }
            // 5) Enforce eligibility and nullifier uniqueness on the existing election state
            if st.finalized {
                return Err(InstructionExecutionError::InvariantViolation(
                    "election already finalized".into(),
                ));
            }
            // Resolve verifying key id: prefer election's vk_ballot, else config default
            if let Some(vk_id) = st.vk_ballot.clone().or_else(|| {
                state_transaction.gov.vk_ballot.as_ref().map(|v| {
                    iroha_data_model::proof::VerifyingKeyId::new(v.backend.clone(), v.name.clone())
                })
            }) {
                if state_transaction.world.verifying_keys.get(&vk_id).is_none() {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "verifying key not found".into(),
                    ));
                }
            }
            if !st.ballot_nullifiers.insert(nullifier) {
                let _ = governance_slash_percent(
                    &self.election_id,
                    authority,
                    state_transaction.gov.slash_double_vote_bps,
                    GovernanceSlashReason::DoubleVote,
                    "double_vote",
                    state_transaction,
                )?;
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: self.election_id.clone(),
                            reason: "duplicate ballot nullifier".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "duplicate ballot nullifier".into(),
                ));
            }

            if proof_verified {
                if let (Some(owner), Some(amount), Some(duration_blocks)) =
                    (lock_owner.clone(), lock_amount, lock_duration)
                {
                    // The proof circuit commits to a fixed-width integer witness. Keep that
                    // circuit contract and cross the public economic boundary explicitly.
                    let amount = Quantity::from(amount);
                    let direction = lock_direction.unwrap_or(2);
                    if owner != *authority {
                        state_transaction.world.emit_events(Some(
                            iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                    referendum_id: self.election_id.clone(),
                                    reason: "owner must equal authority".into(),
                                },
                            ),
                        ));
                        return Err(InstructionExecutionError::InvariantViolation(
                            "owner must equal authority".into(),
                        ));
                    }
                    if !state_transaction.gov.min_bond_amount.is_zero()
                        && amount < state_transaction.gov.min_bond_amount
                    {
                        state_transaction.world.emit_events(Some(
                            iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                    referendum_id: self.election_id.clone(),
                                    reason: "bond amount below minimum".into(),
                                },
                            ),
                        ));
                        return Err(InstructionExecutionError::InvariantViolation(
                            "bond amount below minimum".into(),
                        ));
                    }
                    if duration_blocks < state_transaction.gov.conviction_step_blocks {
                        state_transaction.world.emit_events(Some(
                            iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                    referendum_id: self.election_id.clone(),
                                    reason: "lock shorter than minimum".into(),
                                },
                            ),
                        ));
                        return Err(InstructionExecutionError::InvariantViolation(
                            "lock duration shorter than minimum".into(),
                        ));
                    }
                    let rid = self.election_id.clone();
                    let now_h = state_transaction._curr_block.height().get();
                    let new_expiry = now_h.saturating_add(duration_blocks);
                    let mut locks = state_transaction
                        .world
                        .governance_locks
                        .get(&rid)
                        .cloned()
                        .unwrap_or_default();
                    if let Some(prev) = locks.locks.get(&owner) {
                        if !prev.slashed.is_zero() {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: rid,
                                        reason:
                                            "re-vote requires prior restitution of the existing slash"
                                                .into(),
                                    },
                                ),
                            ));
                            return Err(InstructionExecutionError::InvariantViolation(
                                "re-vote requires prior restitution of the existing slash".into(),
                            ));
                        }
                        if amount < prev.amount || new_expiry < prev.expiry_height {
                            state_transaction.world.emit_events(Some(
                                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                                        referendum_id: rid,
                                        reason:
                                            "re-vote cannot reduce existing lock (amount/expiry)".into(),
                                    },
                                ),
                            ));
                            return Err(InstructionExecutionError::InvariantViolation(
                                "re-vote cannot reduce existing lock".into(),
                            ));
                        }
                    }
                    let custody = locks
                        .locks
                        .get(&owner)
                        .and_then(|record| record.custody.clone())
                        .unwrap_or_else(|| governance_lock_custody(&state_transaction.gov));
                    let minimum_bond = state_transaction.gov.min_bond_amount.clone();
                    lock_voting_bond(
                        &amount,
                        locks.locks.get(&owner).map(|rec| &rec.amount),
                        &minimum_bond,
                        &custody,
                        &owner,
                        &self.election_id,
                        state_transaction,
                    )?;
                    let existed = locks.locks.contains_key(&owner);
                    let slashed = locks
                        .locks
                        .get(&owner)
                        .map_or_else(Quantity::zero, |record| record.slashed.clone());
                    let rec = crate::state::GovernanceLockRecord {
                        owner: owner.clone(),
                        amount,
                        slashed,
                        expiry_height: new_expiry,
                        direction,
                        duration_blocks,
                        custody: Some(custody),
                    };
                    locks.locks.insert(owner.clone(), rec.clone());
                    state_transaction
                        .world
                        .governance_locks
                        .insert(rid.clone(), locks);
                    if existed {
                        state_transaction.world.emit_events(Some(
                            iroha_data_model::events::data::governance::GovernanceEvent::LockExtended(
                                iroha_data_model::events::data::governance::GovernanceLockExtended {
                                    referendum_id: rid,
                                    owner: rec.owner,
                                    amount: rec.amount,
                                    expiry_height: rec.expiry_height,
                                },
                            ),
                        ));
                    } else {
                        state_transaction.world.emit_events(Some(
                            iroha_data_model::events::data::governance::GovernanceEvent::LockCreated(
                                iroha_data_model::events::data::governance::GovernanceLockCreated {
                                    referendum_id: rid,
                                    owner: rec.owner,
                                    amount: rec.amount,
                                    expiry_height: rec.expiry_height,
                                },
                            ),
                        ));
                    }
                }
            }
            // Record commitment bytes and enforce cap
            st.ciphertexts.push(commit_bytes.to_vec());
            let cap = state_transaction.zk.ballot_history_cap.max(1);
            if st.ciphertexts.len() > cap {
                let surplus = st.ciphertexts.len() - cap;
                st.ciphertexts.drain(0..surplus);
            }
            state_transaction.world.elections.remove(id.clone());
            state_transaction.world.elections.insert(id, st);
            // Emit a governance ballot accepted event (mode = Zk, weight not revealed)
            let rid_ev = self.election_id.clone();
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotAccepted(
                    iroha_data_model::events::data::governance::GovernanceBallotAccepted {
                        referendum_id: rid_ev,
                        mode: iroha_data_model::events::data::governance::GovernanceBallotMode::Zk,
                        weight: None,
                    },
                ),
            ));
            Ok(())
        }
    }

    fn validation_fee_proposal_for_referendum(
        referendum_id: &str,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<Option<crate::state::GovernanceProposalRecord>, Error> {
        if referendum_id.len() != 64
            || !referendum_id
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        {
            return Ok(None);
        }
        let Some(bytes) = hex::decode(referendum_id).ok() else {
            return Ok(None);
        };
        let Some(proposal_id) = <[u8; 32]>::try_from(bytes).ok() else {
            return Ok(None);
        };
        let Some(proposal) = state_transaction
            .world
            .governance_proposals
            .get(&proposal_id)
            .cloned()
        else {
            return Ok(None);
        };
        if validation_fee_plain_electorate_rules(&proposal.kind).is_none() {
            return Ok(None);
        }
        if proposal.kind.fingerprint() != proposal_id {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee proposal storage key differs from its exact typed fingerprint"
                    .into(),
            )
            .into());
        }
        Ok(Some(proposal))
    }

    fn retained_validation_fee_plain_electorate_snapshot<'a>(
        proposal_id: [u8; 32],
        proposal: &crate::state::GovernanceProposalRecord,
        referendum: crate::state::GovernanceReferendumRecord,
        approvals: &'a crate::state::GovernanceStageApprovals,
        rules: &ValidationFeePlainElectorateRulesV1,
    ) -> Result<&'a ValidationFeePlainElectorateSnapshotV1, Error> {
        let snapshot = approvals
            .validation_fee_plain_electorate_snapshot
            .as_ref()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee proposal has no frozen PLAIN electorate snapshot".into(),
                )
            })?;
        if let Some(reason) = snapshot.context_error(proposal_id, &proposal.proposer, rules) {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("invalid validation-fee PLAIN electorate snapshot: {reason}").into(),
            ));
        }
        if snapshot.captured_at_height != referendum.h_start
            || approvals.approval_gate_height != Some(snapshot.approval_gate_height)
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee PLAIN electorate snapshot anchors differ from retained governance state"
                    .into(),
            ));
        }
        Ok(snapshot)
    }

    fn ensure_validation_fee_plain_ballot_preconditions(
        ballot: &gov::CastPlainBallot,
        authority: &AccountId,
        proposal: &crate::state::GovernanceProposalRecord,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<ValidationFeePlainElectorateRulesV1, Error> {
        let rules = validation_fee_plain_electorate_rules(&proposal.kind).ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                "validation-fee proposal is missing its PLAIN electorate rules".into(),
            )
        })?;
        if let Some(reason) = rules.invariant_error() {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "validation-fee proposal retained invalid PLAIN electorate rules: {reason}"
                )
                .into(),
            ));
        }
        if ballot.amount != rules.ballot_amount
            || ballot.duration_blocks != rules.ballot_duration_blocks
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee ballot amount or duration differs from its immutable proposal rules"
                    .into(),
            ));
        }
        if ballot.direction > 2 {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee ballot direction must be Aye, Nay, or Abstain".into(),
            ));
        }
        if state_transaction
            .world
            .governance_locks
            .get(&ballot.referendum_id)
            .is_some_and(|locks| locks.locks.contains_key(authority))
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee referendum accepts one effective ballot per account".into(),
            ));
        }
        let referendum = state_transaction
            .world
            .governance_referenda
            .get(&ballot.referendum_id)
            .copied()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee proposal has no retained referendum".into(),
                )
            })?;
        let approvals = state_transaction
            .world
            .governance_stage_approvals
            .get(&ballot.referendum_id)
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee proposal has no retained Parliament approval gate".into(),
                )
            })?;
        let proposal_id = proposal.kind.fingerprint();
        let electorate = retained_validation_fee_plain_electorate_snapshot(
            proposal_id,
            proposal,
            referendum,
            approvals,
            rules,
        )?;
        if !electorate.contains(authority) {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee ballot owner is not in the frozen PLAIN electorate".into(),
            ));
        }
        Ok(rules.clone())
    }

    fn ensure_plain_ballot_preconditions(
        ballot: &gov::CastPlainBallot,
        authority: &AccountId,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<Option<ValidationFeePlainElectorateRulesV1>, Error> {
        if ballot.owner != *authority {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                        referendum_id: ballot.referendum_id.clone(),
                        reason: "owner must equal authority".into(),
                    },
                ),
            ));
            return Err(InstructionExecutionError::InvariantViolation(
                "owner must equal authority".into(),
            ));
        }
        if let Some(proposal) =
            validation_fee_proposal_for_referendum(&ballot.referendum_id, state_transaction)?
        {
            return ensure_validation_fee_plain_ballot_preconditions(
                ballot,
                authority,
                &proposal,
                state_transaction,
            )
            .map(Some);
        }
        ensure_citizen_for_ballot(authority, &ballot.referendum_id, state_transaction)?;
        if !state_transaction.gov.min_bond_amount.is_zero()
            && ballot.amount < state_transaction.gov.min_bond_amount
        {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                        referendum_id: ballot.referendum_id.clone(),
                        reason: "bond amount below minimum".into(),
                    },
                ),
            ));
            return Err(InstructionExecutionError::InvariantViolation(
                "bond amount below minimum".into(),
            ));
        }
        quantity_to_voting_units(&ballot.amount)?;
        if !state_transaction.gov.plain_voting_enabled {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                        referendum_id: ballot.referendum_id.clone(),
                        reason: "mode disabled".into(),
                    },
                ),
            ));
            return Err(InstructionExecutionError::InvariantViolation(
                "plain voting mode disabled by policy".into(),
            ));
        }
        if ballot.duration_blocks < state_transaction.gov.conviction_step_blocks {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                        referendum_id: ballot.referendum_id.clone(),
                        reason: "lock shorter than minimum".into(),
                    },
                ),
            ));
            return Err(InstructionExecutionError::InvariantViolation(
                "lock duration shorter than minimum".into(),
            ));
        }
        Ok(None)
    }

    fn ensure_plain_referendum_open(
        ballot: &gov::CastPlainBallot,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<crate::state::GovernanceReferendumRecord, Error> {
        let rid = ballot.referendum_id.clone();
        let now_h = state_transaction._curr_block.height().get();
        let Some(mut rr) = state_transaction
            .world
            .governance_referenda
            .get(&rid)
            .copied()
        else {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                        referendum_id: rid,
                        reason: "referendum not found".into(),
                    },
                ),
            ));
            return Err(InstructionExecutionError::InvariantViolation(
                "referendum not found".into(),
            ));
        };

        if rr.mode != crate::state::GovernanceReferendumMode::Plain {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                        referendum_id: rid,
                        reason: "mode mismatch (expected Plain)".into(),
                    },
                ),
            ));
            return Err(InstructionExecutionError::InvariantViolation(
                "referendum mode mismatch: expected Plain".into(),
            ));
        }

        if now_h < rr.h_start || now_h > rr.h_end {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                        referendum_id: rid.clone(),
                        reason: "referendum not active (outside window)".into(),
                    },
                ),
            ));
            return Err(InstructionExecutionError::InvariantViolation(
                "referendum not active".into(),
            ));
        }

        if matches!(rr.status, crate::state::GovernanceReferendumStatus::Closed) {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                        referendum_id: rid,
                        reason: "referendum already closed".into(),
                    },
                ),
            ));
            return Err(InstructionExecutionError::InvariantViolation(
                "referendum closed".into(),
            ));
        }

        let proposal = hex::decode(rid.trim_start_matches("0x"))
            .ok()
            .and_then(|bytes| {
                if bytes.len() != 32 {
                    return None;
                }
                let mut proposal_id = [0_u8; 32];
                proposal_id.copy_from_slice(&bytes);
                state_transaction
                    .world
                    .governance_proposals
                    .get(&proposal_id)
                    .cloned()
            });
        if let Some(proposal) = proposal {
            let term_blocks = state_transaction.gov.parliament_term_blocks.max(1);
            let fallback_epoch = now_h.saturating_sub(1).saturating_div(term_blocks);
            let approval_epoch = proposal.approval_epoch(fallback_epoch);
            let approvals = state_transaction
                .world
                .governance_stage_approvals
                .get(&ballot.referendum_id)
                .cloned()
                .unwrap_or_default();
            if !parliament_approval_gate_met(&proposal.kind, &approvals, approval_epoch)
                || required_parliament_bodies(&proposal.kind)
                    .iter()
                    .copied()
                    .any(|body| approvals.rejection_quorum_met(body, approval_epoch))
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "proposal-backed referendum has no exact Parliament approval gate".into(),
                ));
            }
            if !matches!(rr.status, crate::state::GovernanceReferendumStatus::Open) {
                rr.status = crate::state::GovernanceReferendumStatus::Open;
                state_transaction
                    .world
                    .governance_referenda
                    .insert(ballot.referendum_id.clone(), rr);
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::ReferendumOpened(
                        iroha_data_model::events::data::governance::GovernanceReferendumOpened {
                            id: ballot.referendum_id.clone(),
                            h_start: rr.h_start,
                            h_end: rr.h_end,
                        },
                    ),
                ));
            }
        } else if !matches!(rr.status, crate::state::GovernanceReferendumStatus::Open) {
            rr.status = crate::state::GovernanceReferendumStatus::Open;
            state_transaction
                .world
                .governance_referenda
                .insert(ballot.referendum_id.clone(), rr);
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::ReferendumOpened(
                    iroha_data_model::events::data::governance::GovernanceReferendumOpened {
                        id: ballot.referendum_id.clone(),
                        h_start: rr.h_start,
                        h_end: rr.h_end,
                    },
                ),
            ));
        }
        Ok(rr)
    }

    fn ensure_plain_ballot_lock_covers_window(
        ballot: &gov::CastPlainBallot,
        referendum: crate::state::GovernanceReferendumRecord,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let expiry_height = state_transaction
            ._curr_block
            .height()
            .get()
            .checked_add(ballot.duration_blocks)
            .ok_or_else(|| Error::from(MathError::Overflow))?;
        if expiry_height < referendum.h_end {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                    iroha_data_model::events::data::governance::GovernanceBallotRejected {
                        referendum_id: ballot.referendum_id.clone(),
                        reason: "ballot lock expires before the referendum end height".into(),
                    },
                ),
            ));
            return Err(InstructionExecutionError::InvariantViolation(
                "ballot lock must remain active through the referendum end height".into(),
            ));
        }
        Ok(())
    }

    fn apply_plain_ballot_lock(
        ballot: &gov::CastPlainBallot,
        authority: &AccountId,
        weight: u128,
        validation_fee_rules: Option<&ValidationFeePlainElectorateRulesV1>,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let rid = ballot.referendum_id.clone();
        let mut locks = state_transaction
            .world
            .governance_locks
            .get(&rid)
            .cloned()
            .unwrap_or_default();
        let now_h = state_transaction._curr_block.height().get();
        let new_expiry = now_h.saturating_add(ballot.duration_blocks);

        if let Some(prev) = locks.locks.get(authority) {
            if prev.direction != ballot.direction {
                let _ = governance_slash_percent(
                    &rid,
                    authority,
                    state_transaction.gov.slash_double_vote_bps,
                    GovernanceSlashReason::DoubleVote,
                    "double_vote",
                    state_transaction,
                )?;
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: rid.clone(),
                            reason: "re-vote cannot change direction".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "re-vote cannot change direction".into(),
                ));
            }
            if !prev.slashed.is_zero() {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: rid.clone(),
                            reason: "re-vote requires prior restitution of the existing slash"
                                .into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "re-vote requires prior restitution of the existing slash".into(),
                ));
            }
            if ballot.amount < prev.amount || new_expiry < prev.expiry_height {
                state_transaction.world.emit_events(Some(
                    iroha_data_model::events::data::governance::GovernanceEvent::BallotRejected(
                        iroha_data_model::events::data::governance::GovernanceBallotRejected {
                            referendum_id: rid.clone(),
                            reason: "re-vote cannot reduce existing lock (amount/expiry)".into(),
                        },
                    ),
                ));
                return Err(InstructionExecutionError::InvariantViolation(
                    "re-vote cannot reduce existing lock".into(),
                ));
            }
        }
        let custody = locks
            .locks
            .get(authority)
            .and_then(|record| record.custody.clone())
            .unwrap_or_else(|| {
                validation_fee_rules.map_or_else(
                    || governance_lock_custody(&state_transaction.gov),
                    validation_fee_lock_custody,
                )
            });
        if let Some(rules) = validation_fee_rules
            && custody != validation_fee_lock_custody(rules)
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee governance lock custody differs from its immutable proposal rules"
                    .into(),
            ));
        }
        let minimum_bond = validation_fee_rules.map_or_else(
            || state_transaction.gov.min_bond_amount.clone(),
            |rules| rules.ballot_amount.clone(),
        );
        lock_voting_bond(
            &ballot.amount,
            locks.locks.get(authority).map(|rec| &rec.amount),
            &minimum_bond,
            &custody,
            authority,
            &ballot.referendum_id,
            state_transaction,
        )?;

        let existed = locks.locks.contains_key(authority);
        let slashed = locks
            .locks
            .get(authority)
            .map_or_else(Quantity::zero, |record| record.slashed.clone());
        let expiry_height = locks.locks.get(authority).map_or(new_expiry, |prev| {
            core::cmp::max(prev.expiry_height, new_expiry)
        });
        let rec = crate::state::GovernanceLockRecord {
            owner: ballot.owner.clone(),
            amount: ballot.amount.clone(),
            slashed,
            expiry_height,
            direction: ballot.direction,
            duration_blocks: ballot.duration_blocks,
            custody: Some(custody),
        };
        locks.locks.insert(authority.clone(), rec.clone());
        state_transaction
            .world
            .governance_locks
            .insert(rid.clone(), locks);

        record_plain_ballot_events(&rec, existed, &rid, weight, state_transaction);
        Ok(())
    }

    fn record_plain_ballot_events(
        rec: &crate::state::GovernanceLockRecord,
        existed: bool,
        referendum_id: &str,
        weight: u128,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) {
        let event = if existed {
            iroha_data_model::events::data::governance::GovernanceEvent::LockExtended(
                iroha_data_model::events::data::governance::GovernanceLockExtended {
                    referendum_id: referendum_id.to_owned(),
                    owner: rec.owner.clone(),
                    amount: rec.amount.clone(),
                    expiry_height: rec.expiry_height,
                },
            )
        } else {
            iroha_data_model::events::data::governance::GovernanceEvent::LockCreated(
                iroha_data_model::events::data::governance::GovernanceLockCreated {
                    referendum_id: referendum_id.to_owned(),
                    owner: rec.owner.clone(),
                    amount: rec.amount.clone(),
                    expiry_height: rec.expiry_height,
                },
            )
        };
        state_transaction.world.emit_events(Some(event));
        state_transaction.world.emit_events(Some(
            iroha_data_model::events::data::governance::GovernanceEvent::BallotAccepted(
                iroha_data_model::events::data::governance::GovernanceBallotAccepted {
                    referendum_id: referendum_id.to_owned(),
                    mode: iroha_data_model::events::data::governance::GovernanceBallotMode::Plain,
                    weight: Some(weight),
                },
            ),
        ));
    }

    impl Execute for gov::CastPlainBallot {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let validation_fee_rules =
                ensure_plain_ballot_preconditions(&self, authority, state_transaction)?;
            let (conviction_step_blocks, max_conviction) = validation_fee_rules
                .as_ref()
                .map(|rules| (rules.conviction_step_blocks, rules.max_conviction))
                .unwrap_or((
                    state_transaction.gov.conviction_step_blocks,
                    state_transaction.gov.max_conviction,
                ));
            // Validate all economic arithmetic before opening the referendum,
            // sweeping locks, moving the bond, or emitting acceptance events.
            let weight = plain_ballot_weight(
                &self.amount,
                self.duration_blocks,
                conviction_step_blocks,
                max_conviction,
            )?;
            let referendum = ensure_plain_referendum_open(&self, state_transaction)?;
            ensure_plain_ballot_lock_covers_window(&self, referendum, state_transaction)?;
            apply_plain_ballot_lock(
                &self,
                authority,
                weight,
                validation_fee_rules.as_ref(),
                state_transaction,
            )?;
            Ok(())
        }
    }

    impl Execute for gov::SlashGovernanceLock {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if self.amount.is_zero() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract("slash amount must be > 0".into()),
                ));
            }
            if !has_permission(
                &state_transaction.world,
                authority,
                "CanSlashGovernanceLock",
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanSlashGovernanceLock".into(),
                ));
            }
            governance_slash_absolute(
                &self.referendum_id,
                &self.owner,
                self.amount.clone(),
                GovernanceSlashReason::Manual,
                &self.reason,
                state_transaction,
            )?;
            Ok(())
        }
    }

    impl Execute for gov::RestituteGovernanceLock {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if !has_permission(
                &state_transaction.world,
                authority,
                "CanRestituteGovernanceLock",
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanRestituteGovernanceLock".into(),
                ));
            }
            governance_restitute_lock(
                &self.referendum_id,
                &self.owner,
                self.amount.clone(),
                GovernanceSlashReason::Restitution,
                &self.reason,
                state_transaction,
            )?;
            Ok(())
        }
    }

    fn load_proposal(
        state_transaction: &StateTransaction<'_, '_>,
        pid: [u8; 32],
        pid_hex: &str,
    ) -> Result<(crate::state::GovernanceProposalRecord, bool), Error> {
        let Some(prop) = state_transaction
            .world
            .governance_proposals
            .get(&pid)
            .cloned()
        else {
            return Err(
                iroha_data_model::query::error::FindError::Permission(Box::new(Permission::new(
                    "GovernanceProposalMissing".into(),
                    iroha_primitives::json::Json::from(pid_hex),
                )))
                .into(),
            );
        };

        let already_terminal = matches!(
            prop.status,
            crate::state::GovernanceProposalStatus::Enacted
                | crate::state::GovernanceProposalStatus::Superseded
        );
        if !already_terminal
            && !matches!(
                prop.status,
                crate::state::GovernanceProposalStatus::Approved
            )
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "proposal must be approved before enactment".into(),
            ));
        }
        if !already_terminal
            && !prop
                .finalization_evidence
                .is_some_and(|evidence| evidence.approved)
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "proposal has no approved finalization evidence".into(),
            ));
        }

        Ok((prop, already_terminal))
    }

    fn validate_referendum_enactment_binding(
        instruction: &gov::EnactReferendum,
        proposal: &crate::state::GovernanceProposalRecord,
        state_transaction: &StateTransaction<'_, '_>,
        pid_hex: &str,
    ) -> Result<(), Error> {
        let expected_preimage_hash = proposal.kind.fingerprint();
        if instruction.preimage_hash != expected_preimage_hash {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "enactment preimage_hash does not match the stored governance proposal".into(),
                ),
            ));
        }

        let Some(referendum) = state_transaction
            .world
            .governance_referenda
            .get(pid_hex)
            .copied()
        else {
            return Err(InstructionExecutionError::InvariantViolation(
                "governance referendum is missing for enactment".into(),
            ));
        };
        let expected_window = AtWindow {
            lower: referendum.h_start,
            upper: referendum.h_end,
        };
        if instruction.at_window != expected_window {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "enactment at_window does not match the stored referendum window".into(),
                ),
            ));
        }

        if referendum.status != crate::state::GovernanceReferendumStatus::Closed {
            return Err(InstructionExecutionError::InvariantViolation(
                "governance enactment requires a closed referendum".into(),
            ));
        }
        let finalized_at_height = proposal
            .finalization_evidence
            .as_ref()
            .map(|evidence| evidence.finalized_at_height)
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "governance enactment requires finalized referendum evidence".into(),
                )
            })?;
        let current_height = state_transaction._curr_block.height().get();
        if current_height <= finalized_at_height {
            return Err(InstructionExecutionError::InvariantViolation(
                "governance enactment must occur after referendum finalization".into(),
            ));
        }

        Ok(())
    }

    fn parse_hex32(input: &str, what: &str) -> Result<[u8; 32], Error> {
        let bytes = hex::decode(input.trim_start_matches("0x")).map_err(|_| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                format!("invalid {what} hex"),
            ))
        })?;
        if bytes.len() != 32 {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(format!("{what} must be 32 bytes")),
            ));
        }
        let mut out = [0u8; 32];
        out.copy_from_slice(&bytes);
        Ok(out)
    }

    fn extract_hashes(payload: &DeployContractProposal) -> Result<([u8; 32], [u8; 32]), Error> {
        if payload.abi_version != AbiVersion::new(1) {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    format!(
                        "unsupported governance contract abi_version {}; expected 1",
                        payload.abi_version.get()
                    )
                    .into(),
                ),
            ));
        }
        let code_hash = parse_hex32(&payload.code_hash_hex.to_hex(), "code_hash")?;
        let abi_hash = parse_hex32(&payload.abi_hash_hex.to_hex(), "abi_hash")?;
        Ok((code_hash, abi_hash))
    }

    fn upsert_manifest(
        state_transaction: &mut StateTransaction<'_, '_>,
        key: iroha_crypto::Hash,
        abi_hash: [u8; 32],
        provenance: Option<&ManifestProvenance>,
    ) -> Result<bool, Error> {
        let code_bytes = state_transaction
            .world
            .contract_code
            .get(&key)
            .ok_or_else(|| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    "verified contract bytecode must be registered before governance enactment"
                        .into(),
                ))
            })?;
        let verified = ivm::verify_contract_artifact(code_bytes).map_err(|error| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                format!("stored governance contract bytecode is invalid: {error}").into(),
            ))
        })?;
        crate::smartcontracts::ivm::validate_cycle_ceiling(
            &verified.metadata,
            state_transaction.pipeline.ivm_max_cycles_upper_bound,
        )
        .map_err(|error| invalid_smart_contract_parameter(error.to_string()))?;
        if verified.code_hash != key {
            return Err(InstructionExecutionError::InvariantViolation(
                "stored governance contract bytecode hash mismatch".into(),
            ));
        }
        let verified_abi_hash: [u8; 32] = verified.abi_hash.into();
        if verified_abi_hash != abi_hash {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "governance proposal abi_hash does not match the verified contract artifact"
                        .into(),
                ),
            ));
        }

        if let Some(existing) = state_transaction.world.contract_manifests.get(&key) {
            if existing.signature_payload() != verified.manifest.signature_payload() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "existing manifest does not match the verified contract artifact".into(),
                ));
            }
            ensure_manifest_signature(existing)?;
            Ok(false)
        } else {
            let provenance = provenance.ok_or_else(|| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    "manifest_provenance for the exact verified manifest is required for governance contract deployment"
                        .into(),
                ))
            })?;
            let mut manifest = verified.manifest;
            manifest.provenance = Some(provenance.clone());
            ensure_manifest_signature(&manifest)?;
            state_transaction
                .world
                .contract_manifests
                .insert(key, manifest);
            Ok(true)
        }
    }

    fn mark_proposal_enacted(state_transaction: &mut StateTransaction<'_, '_>, pid: [u8; 32]) {
        if let Some(mut rec) = state_transaction
            .world
            .governance_proposals
            .get(&pid)
            .cloned()
        {
            rec.status = crate::state::GovernanceProposalStatus::Enacted;
            rec.enacted_at_height = Some(state_transaction._curr_block.height().get());
            state_transaction
                .world
                .governance_proposals
                .insert(pid, rec);
        }
    }

    fn mark_proposal_superseded(state_transaction: &mut StateTransaction<'_, '_>, pid: [u8; 32]) {
        if let Some(mut record) = state_transaction
            .world
            .governance_proposals
            .get(&pid)
            .cloned()
        {
            record.status = crate::state::GovernanceProposalStatus::Superseded;
            state_transaction
                .world
                .governance_proposals
                .insert(pid, record);
        }
    }

    fn validation_fee_parliament_authorization(
        proposal_id: [u8; 32],
        proposal: &crate::state::GovernanceProposalRecord,
        enacted_at_height: u64,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<ValidationFeeParliamentAuthorizationV1, Error> {
        let proposal_fingerprint = proposal.kind.fingerprint();
        if proposal_id != proposal_fingerprint {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee proposal id differs from its exact typed fingerprint".into(),
            ));
        }
        let evidence = proposal.finalization_evidence.as_ref().ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                "validation-fee proposal has no finalization evidence".into(),
            )
        })?;
        if evidence.proposal_id != proposal_id
            || evidence.referendum_id != proposal_id
            || !evidence.approved
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee proposal finalization evidence is not an exact approval".into(),
            ));
        }
        let snapshot = proposal.parliament_snapshot.as_ref().ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                "validation-fee proposal has no parliament snapshot".into(),
            )
        })?;
        if compute_parliament_roster_root(&snapshot.bodies)? != snapshot.roster_root {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee proposal parliament roster commitment mismatch".into(),
            ));
        }
        let referendum_id = hex::encode(proposal_id);
        let referendum = state_transaction
            .world
            .governance_referenda
            .get(&referendum_id)
            .copied()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee proposal has no retained referendum".into(),
                )
            })?;
        let rules = validation_fee_plain_electorate_rules(&proposal.kind).ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                "validation-fee proposal is missing its retained PLAIN electorate rules".into(),
            )
        })?;
        if evidence.mode != gov::VotingMode::Plain
            || evidence.finalized_at_height != referendum.h_end
            || evidence.min_turnout != rules.min_turnout
            || evidence.approval_threshold_numerator != rules.approval_threshold_numerator
            || evidence.approval_threshold_denominator != rules.approval_threshold_denominator
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee finalization evidence differs from its retained PLAIN electorate rules"
                    .into(),
            ));
        }
        let approvals = state_transaction
            .world
            .governance_stage_approvals
            .get(&referendum_id)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee proposal has no parliament approval record".into(),
                )
            })?;
        if !parliament_approval_gate_met(&proposal.kind, &approvals, snapshot.selection_epoch)
            || required_parliament_bodies(&proposal.kind)
                .iter()
                .copied()
                .any(|body| approvals.rejection_quorum_met(body, snapshot.selection_epoch))
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee proposal does not retain seven-body Parliament approval".into(),
            ));
        }
        if approvals.approval_gate_height.is_none() {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee proposal does not retain its Parliament approval gate height"
                    .into(),
            ));
        }
        let electorate = retained_validation_fee_plain_electorate_snapshot(
            proposal_id,
            proposal,
            referendum,
            &approvals,
            rules,
        )?;

        let authorization = ValidationFeeParliamentAuthorizationV1 {
            proposal_id,
            proposal_fingerprint,
            proposal_time_roster_root: snapshot.roster_root,
            plain_electorate_snapshot_root: electorate.roster_root,
            plain_electorate_snapshot_member_count: electorate.member_count,
            plain_electorate_snapshot_captured_at_height: electorate.captured_at_height,
            plain_electorate_snapshot_approval_gate_height: electorate.approval_gate_height,
            referendum_window: ValidationFeeGovernanceWindowV1 {
                lower: referendum.h_start,
                upper: referendum.h_end,
            },
            finalization: ValidationFeeFinalizationEvidenceV1 {
                referendum_id: evidence.referendum_id,
                finalized_at_height: evidence.finalized_at_height,
                mode: match evidence.mode {
                    gov::VotingMode::Zk => ValidationFeeGovernanceVotingModeV1::Zk,
                    gov::VotingMode::Plain => ValidationFeeGovernanceVotingModeV1::Plain,
                },
                approve: evidence.approve,
                reject: evidence.reject,
                abstain: evidence.abstain,
                min_turnout: evidence.min_turnout,
                approval_threshold_numerator: evidence.approval_threshold_numerator,
                approval_threshold_denominator: evidence.approval_threshold_denominator,
                approved: evidence.approved,
            },
            enacted_at_height,
        };
        if let Some(reason) = authorization.invariant_error() {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("invalid validation-fee Parliament authorization: {reason}").into(),
            ));
        }
        Ok(authorization)
    }

    fn enacted_validation_fee_payout_lifecycle(
        payload: &ValidationFeePolicyProposal,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<Option<ValidationFeePayoutLifecycleReferenceV1>, Error> {
        let Some(payout_binding) = payload.policy.treasury_payout_binding.as_ref() else {
            if payload.payout_lifecycle_proposal_id.is_some() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "validation-fee policy without a payout binding references a lifecycle".into(),
                ));
            }
            return Ok(None);
        };
        let lifecycle_id = payload.payout_lifecycle_proposal_id.ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                "validation-fee payout policy has no lifecycle proposal id".into(),
            )
        })?;
        let lifecycle = state_transaction
            .world
            .governance_proposals
            .get(&lifecycle_id)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee payout lifecycle proposal not found".into(),
                )
            })?;
        if lifecycle.status != crate::state::GovernanceProposalStatus::Enacted {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle must be enacted before policy enactment".into(),
            ));
        }
        let lifecycle_enacted_at_height = lifecycle.enacted_at_height.ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle has no enactment height".into(),
            )
        })?;
        let lifecycle_payload =
            lifecycle
                .as_validation_fee_payout_lifecycle()
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "referenced proposal is not a validation-fee payout lifecycle".into(),
                    )
                })?;
        if &lifecycle_payload.payout_binding != payout_binding {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle does not authorize the exact policy binding"
                    .into(),
            ));
        }
        if lifecycle_payload.plain_electorate_rules != payload.plain_electorate_rules {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee policy and payout lifecycle bind different PLAIN electorate rules"
                    .into(),
            ));
        }
        validate_validation_fee_payout_lifecycle_runtime(payout_binding, state_transaction)?;
        let derived_lifecycle_seal =
            lifecycle_payload
                .payout_binding
                .lifecycle_seal()
                .map_err(|_| {
                    InstructionExecutionError::InvariantViolation(
                        "failed to derive validation-fee payout lifecycle seal".into(),
                    )
                })?;
        if derived_lifecycle_seal == [0; 32] {
            return Err(InstructionExecutionError::InvariantViolation(
                "enacted validation-fee payout lifecycle derives an invalid zero seal".into(),
            ));
        }
        let parliament_authorization = validation_fee_parliament_authorization(
            lifecycle_id,
            &lifecycle,
            lifecycle_enacted_at_height,
            state_transaction,
        )?;
        Ok(Some(ValidationFeePayoutLifecycleReferenceV1 {
            lifecycle_seal: derived_lifecycle_seal,
            parliament_authorization,
            plain_electorate_rules: lifecycle_payload.plain_electorate_rules.clone(),
        }))
    }

    fn enact_validation_fee_policy(
        proposal_id: [u8; 32],
        proposal: &crate::state::GovernanceProposalRecord,
        payload: &ValidationFeePolicyProposal,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<bool, Error> {
        let mut registry = validation_fee_policy_registry(state_transaction)?.unwrap_or(
            ValidationFeePolicyRegistryV1 {
                registered_policies: Vec::new(),
            },
        );
        let predecessor_is_current = match registry.head() {
            None => {
                payload.policy.policy_version == 1 && payload.policy.previous_policy_hash.is_none()
            }
            Some(head) => {
                head.policy
                    .policy_version
                    .checked_add(1)
                    .is_some_and(|version| version == payload.policy.policy_version)
                    && payload.policy.previous_policy_hash == Some(head.policy_hash)
            }
        };
        if !predecessor_is_current {
            mark_proposal_superseded(state_transaction, proposal_id);
            return Ok(false);
        }

        let _ = validate_validation_fee_policy_proposal(&payload.policy, state_transaction)?;
        let enacted_at_height = state_transaction._curr_block.height().get();
        ensure_validation_fee_policy_activation_delay(
            payload.policy.effective_from_height,
            enacted_at_height,
        )?;
        let parliament_authorization = validation_fee_parliament_authorization(
            proposal_id,
            proposal,
            enacted_at_height,
            state_transaction,
        )?;
        let payout_lifecycle = enacted_validation_fee_payout_lifecycle(payload, state_transaction)?;
        let entry = ValidationFeePolicyRegistryEntryV1::from_enactment(
            payload.policy.clone(),
            payload.plain_electorate_rules.clone(),
            parliament_authorization,
            payout_lifecycle,
        )
        .map_err(|_| {
            InstructionExecutionError::InvariantViolation(
                "failed to hash enacted validation-fee policy".into(),
            )
        })?;
        registry.registered_policies.push(entry);
        registry.validate().map_err(|error| {
            InstructionExecutionError::InvariantViolation(
                format!("enacted validation-fee registry is invalid: {error}").into(),
            )
        })?;

        let next = registry.into_custom_parameter();
        let previous = {
            let parameters = state_transaction.world.parameters.get_mut();
            let previous = parameters.custom().get(next.id()).cloned();
            parameters.set_parameter(Parameter::Custom(next.clone()));
            previous
        };
        state_transaction
            .world
            .emit_events(Some(ConfigurationEvent::Changed(ParameterChanged {
                old_value: Parameter::Custom(previous.unwrap_or_else(|| next.clone())),
                new_value: Parameter::Custom(next),
            })));
        Ok(true)
    }

    fn ensure_validation_fee_policy_activation_delay(
        effective_from_height: u64,
        enacted_at_height: u64,
    ) -> Result<u64, Error> {
        let minimum_effective_height = enacted_at_height
            .checked_add(
                iroha_data_model::validation_fee::VALIDATION_FEE_POLICY_ACTIVATION_DELAY_BLOCKS,
            )
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee activation delay overflows the block-height domain".into(),
                )
            })?;
        if effective_from_height != minimum_effective_height {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    format!(
                        "validation-fee policy effective height must equal {minimum_effective_height}"
                    )
                    .into(),
                ),
            ));
        }
        Ok(minimum_effective_height)
    }

    fn ensure_contract_subject_binding(
        state_transaction: &mut StateTransaction<'_, '_>,
        contract_address: &iroha_data_model::smart_contract::ContractAddress,
    ) -> Result<AccountId, Error> {
        let contract_subject = match state_transaction
            .world
            .contract_subject_bindings
            .get(contract_address)
        {
            Some(binding) => {
                binding.validate_for(contract_address).map_err(|message| {
                    InstructionExecutionError::InvariantViolation(message.into())
                })?;
                binding.subject.clone()
            }
            None => {
                let binding =
                    crate::smartcontracts::code::ContractSubjectBinding::new(contract_address);
                let subject = binding.subject.clone();
                state_transaction
                    .world
                    .contract_subject_bindings
                    .insert(contract_address.clone(), binding);
                subject
            }
        };
        match state_transaction
            .world
            .contract_subject_addresses
            .get(&contract_subject)
        {
            Some(existing) if existing != contract_address => {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "contract subject `{contract_subject}` is already bound to `{existing}`"
                    )
                    .into(),
                ));
            }
            Some(_) => {}
            None => {
                state_transaction
                    .world
                    .contract_subject_addresses
                    .insert(contract_subject.clone(), contract_address.clone());
            }
        }
        Ok(contract_subject)
    }

    fn bind_contract_instance(
        authority: &AccountId,
        state_transaction: &mut StateTransaction<'_, '_>,
        payload: &DeployContractProposal,
        key: iroha_crypto::Hash,
    ) -> Result<bool, Error> {
        let contract_address = payload.contract_address.clone();
        let contract_subject =
            ensure_contract_subject_binding(state_transaction, &contract_address)?;
        let manifest = state_transaction
            .world
            .contract_manifests
            .get(&key)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    "exact verified manifest must be registered before governance binding".into(),
                ))
            })?;
        let code_bytes = verify_registered_contract_artifact_for_manifest(
            &state_transaction.world,
            &key,
            &manifest,
        )?;
        let declares_hajimari = manifest.entrypoints.as_ref().is_some_and(|entrypoints| {
            entrypoints.iter().any(|entrypoint| {
                entrypoint.kind
                    == iroha_data_model::smart_contract::manifest::EntryPointKind::Hajimari
            })
        });
        if let Some(existing) = state_transaction
            .world
            .contract_instances
            .get(&contract_address)
        {
            if *existing != key {
                return Err(InstructionExecutionError::InvariantViolation(
                    "contract instance already bound to a different code hash".into(),
                ));
            }
            return Ok(false);
        }
        let pending_lifecycle = declares_hajimari
            .then(|| {
                crate::smartcontracts::code::new_pending_contract_lifecycle(
                    state_transaction,
                    &contract_address,
                    None,
                    key,
                    iroha_data_model::smart_contract::manifest::EntryPointKind::Hajimari,
                )
            })
            .transpose()
            .map_err(|error| {
                InstructionExecutionError::InvariantViolation(error.to_owned().into())
            })?;
        register_manifest_triggers(
            authority,
            state_transaction,
            &contract_address,
            &contract_subject,
            &code_bytes,
            &manifest,
        )?;
        state_transaction
            .world
            .contract_instances
            .insert(contract_address.clone(), key);
        crate::smartcontracts::code::set_pending_contract_lifecycle(
            state_transaction,
            &contract_address,
            pending_lifecycle,
        );
        Ok(true)
    }

    #[cfg(feature = "telemetry")]
    fn record_enactment_telemetry(
        state_transaction: &mut StateTransaction<'_, '_>,
        payload: &DeployContractProposal,
        code_hash: [u8; 32],
        abi_hash: [u8; 32],
        manifest_inserted: bool,
        instance_bound_new: bool,
    ) {
        if manifest_inserted {
            state_transaction
                .telemetry
                .record_manifest_activation(None, "manifest_inserted");
        }
        if instance_bound_new {
            let activated_at_ms_u128 = state_transaction._curr_block.creation_time().as_millis();
            let activated_at_ms = u64::try_from(activated_at_ms_u128).unwrap_or(u64::MAX);
            let activation = GovernanceManifestActivation {
                contract_address: payload.contract_address.to_string(),
                code_hash_hex: hex::encode(code_hash),
                abi_hash_hex: Some(hex::encode(abi_hash)),
                height: state_transaction._curr_block.height().get(),
                activated_at_ms,
            };
            state_transaction
                .telemetry
                .record_manifest_activation(Some(activation), "instance_bound");
        }
    }

    fn close_referendum_if_open(state_transaction: &mut StateTransaction<'_, '_>, pid_hex: &str) {
        if let Some(mut ref_rec) = state_transaction
            .world
            .governance_referenda
            .get(pid_hex)
            .copied()
        {
            if ref_rec.status != crate::state::GovernanceReferendumStatus::Closed {
                ref_rec.status = crate::state::GovernanceReferendumStatus::Closed;
                state_transaction
                    .world
                    .governance_referenda
                    .insert(pid_hex.to_owned(), ref_rec);
            }
        }
    }

    fn enact_runtime_upgrade_proposal(
        state_transaction: &mut StateTransaction<'_, '_>,
        payload: &RuntimeUpgradeProposal,
        proposer: &AccountId,
    ) -> Result<(), Error> {
        let now_h = state_transaction._curr_block.height().get();
        if now_h > payload.manifest.start_height {
            return Err(InstructionExecutionError::InvariantViolation(
                "runtime upgrade start_height already passed before enactment".into(),
            ));
        }

        let id = payload.manifest.id();
        if let Some(existing) = state_transaction.world.runtime_upgrades.get(&id) {
            if existing.manifest != payload.manifest {
                return Err(InstructionExecutionError::InvariantViolation(
                    "runtime upgrade id collision".into(),
                ));
            }
            if matches!(
                existing.status,
                iroha_data_model::runtime::RuntimeUpgradeStatus::Canceled
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "runtime upgrade already canceled".into(),
                ));
            }
            return Ok(());
        }

        validate_runtime_upgrade_provenance(&payload.manifest, state_transaction)?;
        ensure_runtime_upgrade_abi_version(&payload.manifest, state_transaction)?;
        validate_runtime_upgrade_surface(&payload.manifest, state_transaction)?;
        ensure_runtime_upgrade_no_overlap(&payload.manifest, state_transaction)?;

        let mut status = iroha_data_model::runtime::RuntimeUpgradeStatus::Proposed;
        if now_h == payload.manifest.start_height {
            status = iroha_data_model::runtime::RuntimeUpgradeStatus::ActivatedAt(now_h);
        }
        state_transaction.world.runtime_upgrades.insert(
            id,
            iroha_data_model::runtime::RuntimeUpgradeRecord {
                manifest: payload.manifest.clone(),
                status,
                proposer: proposer.clone(),
                created_height: now_h,
            },
        );
        state_transaction.world.emit_events(Some(
            iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeEvent::Proposed(
                iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeProposed {
                    id,
                    abi_version: payload.manifest.abi_version,
                    start_height: payload.manifest.start_height,
                    end_height: payload.manifest.end_height,
                },
            ),
        ));
        #[cfg(feature = "telemetry")]
        {
            state_transaction
                .telemetry
                .inc_runtime_upgrade_event("proposed");
        }
        if matches!(
            status,
            iroha_data_model::runtime::RuntimeUpgradeStatus::ActivatedAt(_)
        ) {
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeEvent::Activated(
                    iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeActivated {
                        id,
                        abi_version: payload.manifest.abi_version,
                        at_height: now_h,
                    },
                ),
            ));
            #[cfg(feature = "telemetry")]
            {
                state_transaction
                    .telemetry
                    .inc_runtime_upgrade_event("activated");
            }
        }
        Ok(())
    }

    fn process_council_members(
        members: &[AccountId],
        epoch: u64,
        required_bond: &Quantity,
        citizen_cfg: &iroha_config::parameters::actual::CitizenServiceDiscipline,
        current_height: u64,
        world: &mut WorldTransaction<'_, '_>,
        updated_citizens: &mut BTreeMap<AccountId, crate::state::CitizenshipRecord>,
    ) -> Result<(), Error> {
        for account_id in members {
            let Some(mut record) = world.citizens.get(account_id).cloned() else {
                return Err(InstructionExecutionError::InvariantViolation(
                    "council members must be registered citizens".into(),
                ));
            };
            if &record.amount < required_bond {
                return Err(InstructionExecutionError::InvariantViolation(
                    "council members must meet the citizenship bond floor for the role".into(),
                ));
            }
            assign_citizen_seat(&mut record, epoch, current_height, citizen_cfg)?;
            updated_citizens.insert(account_id.clone(), record);
        }
        Ok(())
    }

    fn process_council_alternates(
        alternates: &[AccountId],
        epoch: u64,
        required_bond: &Quantity,
        current_height: u64,
        world: &mut WorldTransaction<'_, '_>,
        updated_citizens: &mut BTreeMap<AccountId, crate::state::CitizenshipRecord>,
    ) -> Result<(), Error> {
        for account_id in alternates {
            let Some(mut record) = world.citizens.get(account_id).cloned() else {
                return Err(InstructionExecutionError::InvariantViolation(
                    "council alternates must be registered citizens".into(),
                ));
            };
            if &record.amount < required_bond {
                return Err(InstructionExecutionError::InvariantViolation(
                    "council alternates must meet the citizenship bond floor for the role".into(),
                ));
            }
            ensure_citizen_available(&mut record, epoch, current_height)?;
            updated_citizens.entry(account_id.clone()).or_insert(record);
        }
        Ok(())
    }

    fn ensure_unique_council_roster(
        members: &[AccountId],
        alternates: &[AccountId],
    ) -> Result<(), Error> {
        let mut members_seen = BTreeSet::new();
        for member in members {
            if !members_seen.insert(member) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "council roster contains duplicate member".into(),
                ));
            }
        }
        let mut alternates_seen = BTreeSet::new();
        for alternate in alternates {
            if members_seen.contains(alternate) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "council roster account cannot be both member and alternate".into(),
                ));
            }
            if !alternates_seen.insert(alternate) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "council roster contains duplicate alternate".into(),
                ));
            }
        }
        Ok(())
    }

    fn permission_targets_trigger(permission: &Permission, trigger_id: &TriggerId) -> bool {
        iroha_executor_data_model::permission::trigger::CanUnregisterTrigger::try_from(permission)
            .is_ok_and(|token| &token.trigger == trigger_id)
            || iroha_executor_data_model::permission::trigger::CanModifyTrigger::try_from(
                permission,
            )
            .is_ok_and(|token| &token.trigger == trigger_id)
            || iroha_executor_data_model::permission::trigger::CanExecuteTrigger::try_from(
                permission,
            )
            .is_ok_and(|token| &token.trigger == trigger_id)
            || iroha_executor_data_model::permission::trigger::CanModifyTriggerMetadata::try_from(
                permission,
            )
            .is_ok_and(|token| &token.trigger == trigger_id)
    }

    fn require_sole_direct_validation_fee_runtime_permission_holder(
        state_transaction: &StateTransaction<'_, '_>,
        permission: &Permission,
        required_holder: &AccountId,
        selector_label: &str,
    ) -> Result<(), Error> {
        let direct_holders = state_transaction
            .world
            .account_permissions
            .iter()
            .filter_map(|(account_id, permissions)| {
                permissions
                    .iter()
                    .any(|candidate| candidate == permission)
                    .then_some(account_id)
            })
            .collect::<Vec<_>>();
        if direct_holders.len() != 1 || direct_holders[0] != required_holder {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "validation-fee payout lifecycle requires the bound subject to be the sole direct holder of {selector_label}"
                )
                .into(),
            ));
        }
        if state_transaction
            .world
            .roles
            .iter()
            .any(|(_, role)| role.permissions().any(|candidate| candidate == permission))
        {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "validation-fee payout lifecycle forbids role ownership of {selector_label}"
                )
                .into(),
            ));
        }
        Ok(())
    }

    fn validation_fee_payout_effect_permission(
        binding: &iroha_data_model::validation_fee::ValidationFeeTreasuryPayoutBindingV1,
    ) -> Permission {
        iroha_executor_data_model::permission::asset::CanTransferAsset {
            asset: AssetId::new(
                binding.sbd_asset_id.clone(),
                binding.treasury_account_id.clone(),
            ),
        }
        .into()
    }

    fn require_absent_validation_fee_runtime_permission(
        state_transaction: &StateTransaction<'_, '_>,
        permission: &Permission,
        permission_label: &str,
    ) -> Result<(), Error> {
        if state_transaction
            .world
            .account_permissions
            .iter()
            .any(|(_, permissions)| permissions.iter().any(|candidate| candidate == permission))
        {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "validation-fee payout lifecycle requires {permission_label} to be absent before enactment"
                )
                .into(),
            ));
        }
        if state_transaction
            .world
            .roles
            .iter()
            .any(|(_, role)| role.permissions().any(|candidate| candidate == permission))
        {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "validation-fee payout lifecycle forbids role ownership of {permission_label}"
                )
                .into(),
            ));
        }
        Ok(())
    }

    fn install_derived_validation_fee_runtime_permissions_with_validation<F>(
        permissions: Vec<(Permission, AccountId, &'static str)>,
        state_transaction: &mut StateTransaction<'_, '_>,
        validate_installed: F,
    ) -> Result<(), Error>
    where
        F: FnOnce(&StateTransaction<'_, '_>) -> Result<(), Error>,
    {
        for (permission, _, permission_label) in &permissions {
            require_absent_validation_fee_runtime_permission(
                state_transaction,
                permission,
                permission_label,
            )?;
        }
        for (permission, required_holder, _) in &permissions {
            state_transaction
                .world
                .add_account_permission(required_holder, permission.clone());
        }
        if let Err(error) = validate_installed(state_transaction) {
            for (permission, required_holder, _) in &permissions {
                state_transaction
                    .world
                    .remove_account_permission(required_holder, permission);
                state_transaction.invalidate_permission_cache_for_account(required_holder);
            }
            return Err(error);
        }

        for (permission, required_holder, _) in permissions {
            state_transaction
                .world
                .emit_events(Some(AccountEvent::PermissionAdded(
                    AccountPermissionChanged {
                        account: required_holder.clone(),
                        permission,
                    },
                )));
            state_transaction.invalidate_permission_cache_for_account(&required_holder);
        }
        Ok(())
    }

    fn install_derived_validation_fee_runtime_permissions(
        binding: &iroha_data_model::validation_fee::ValidationFeeTreasuryPayoutBindingV1,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        state_transaction
            .world
            .account(&binding.treasury_account_id)
            .map_err(|_| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee payout lifecycle wrapper subject account does not exist".into(),
                )
            })?;
        state_transaction
            .world
            .account(&binding.pool_vault_account_id)
            .map_err(|_| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee payout lifecycle pool subject account does not exist".into(),
                )
            })?;
        let pool_contract_address = state_transaction
            .world
            .contract_subject_addresses
            .get(&binding.pool_vault_account_id)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee payout lifecycle pool vault must be an active contract subject"
                        .into(),
                )
            })?;
        let permissions = validation_fee_runtime_permissions(binding, &pool_contract_address);
        install_derived_validation_fee_runtime_permissions_with_validation(
            permissions,
            state_transaction,
            |state_transaction| {
                validate_validation_fee_payout_lifecycle_runtime(binding, state_transaction)
            },
        )?;
        Ok(())
    }

    fn validation_fee_runtime_permissions(
        binding: &iroha_data_model::validation_fee::ValidationFeeTreasuryPayoutBindingV1,
        pool_contract_address: &iroha_data_model::smart_contract::ContractAddress,
    ) -> Vec<(Permission, AccountId, &'static str)> {
        vec![
            (
                iroha_executor_data_model::permission::smart_contract::CanInvokeContractEntrypoint {
                    contract: binding.contract_address.clone(),
                    entrypoint: binding.entrypoint.to_string(),
                }
                .into(),
                binding.treasury_account_id.clone(),
                "the wrapper payout selector",
            ),
            (
                iroha_executor_data_model::permission::smart_contract::CanInvokeContractEntrypoint {
                    contract: pool_contract_address.clone(),
                    entrypoint: crate::validation_fee::VALIDATION_FEE_POOL_SWAP_ENTRYPOINT.to_owned(),
                }
                .into(),
                binding.treasury_account_id.clone(),
                "the pool swap selector",
            ),
            (
                validation_fee_payout_effect_permission(binding),
                binding.pool_vault_account_id.clone(),
                "the wrapper SBD asset transfer effect",
            ),
        ]
    }

    fn validate_validation_fee_payout_lifecycle_runtime(
        binding: &iroha_data_model::validation_fee::ValidationFeeTreasuryPayoutBindingV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        validate_validation_fee_payout_lifecycle_runtime_with_effect(
            binding,
            state_transaction,
            true,
        )
    }

    fn validate_validation_fee_payout_lifecycle_runtime_before_effect_install(
        binding: &iroha_data_model::validation_fee::ValidationFeeTreasuryPayoutBindingV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        validate_validation_fee_payout_lifecycle_runtime_with_effect(
            binding,
            state_transaction,
            false,
        )
    }

    fn validate_validation_fee_payout_lifecycle_runtime_with_effect(
        binding: &iroha_data_model::validation_fee::ValidationFeeTreasuryPayoutBindingV1,
        state_transaction: &StateTransaction<'_, '_>,
        require_derived_permissions: bool,
    ) -> Result<(), Error> {
        let record = fetch_bound_contract_record(state_transaction, &binding.contract_address)
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee payout lifecycle requires an active immutable contract".into(),
                )
            })?;
        if record.contract_address != binding.contract_address
            || record.contract_subject != binding.treasury_account_id
            || binding.contract_address.subject_id() != binding.treasury_account_id
            || <[u8; 32]>::from(sha2::Sha256::digest(&record.code_bytes)) != binding.code_hash
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle contract code or subject differs from its typed binding"
                    .into(),
            ));
        }
        let entrypoints = record.manifest.entrypoints.as_ref().ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle contract has no manifest entrypoints".into(),
            )
        })?;
        let matching_entrypoints = entrypoints
            .iter()
            .filter(|entrypoint| entrypoint.name == binding.entrypoint.as_ref())
            .collect::<Vec<_>>();
        if matching_entrypoints.len() != 1
            || matching_entrypoints[0].kind
                != iroha_data_model::smart_contract::manifest::EntryPointKind::Kotoage
            || !matching_entrypoints[0].params.is_empty()
            || matching_entrypoints[0].argument_schema.is_some()
            || matching_entrypoints[0].permission.as_deref()
                != Some(crate::validation_fee::VALIDATION_FEE_PAYOUT_WRAPPER_ENTRYPOINT_PERMISSION)
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle requires one argument-free autonomous entrypoint protected by exact contract-selector authorization"
                    .into(),
            ));
        }
        if entrypoints.iter().any(|entrypoint| {
            entrypoint.kind == iroha_data_model::smart_contract::manifest::EntryPointKind::Kaizen
        }) {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle contract must not expose kaizen/改善".into(),
            ));
        }
        let active_code_hash = state_transaction
            .world
            .contract_instances
            .get(&binding.contract_address)
            .copied()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee payout lifecycle contract is not active".into(),
                )
            })?;
        let invocation_matches =
            |invocation: &iroha_data_model::transaction::executable::ContractInvocation| {
                invocation.contract_address == binding.contract_address
                    && invocation.expected_code_hash == active_code_hash
                    && invocation.entrypoint == binding.entrypoint.as_ref()
                    && invocation.arguments.is_none()
            };
        let matching_triggers = state_transaction
            .world
            .triggers
            .time_triggers()
            .iter()
            .filter(|(_, action)| {
                match action.executable() {
                    ExecutableRef::ContractCall(invocation) => invocation_matches(invocation),
                    ExecutableRef::Batch(items) => items.iter().any(|item| {
                        matches!(
                            item,
                            iroha_data_model::transaction::executable::ExecutableBatchItem::ContractCall(
                                invocation
                            ) if invocation_matches(invocation)
                        )
                    }),
                    ExecutableRef::Ivm(_) | ExecutableRef::Instructions(_) => false,
                }
            })
            .collect::<Vec<_>>();
        if matching_triggers.len() != 1 {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle requires exactly one scheduled Time trigger"
                    .into(),
            ));
        }
        let (trigger_id, action) = matching_triggers[0];
        if action.authority() != &binding.treasury_account_id
            || !matches!(action.executable(), ExecutableRef::ContractCall(invocation) if invocation_matches(invocation))
            || action.repeats != iroha_data_model::trigger::action::Repeats::Indefinitely
            || action.retry_policy.is_some()
            || !trigger_is_enabled(&action.metadata)
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle trigger must be enabled, indefinite, and retry-free"
                    .into(),
            ));
        }
        let account_permission_exists =
            state_transaction
                .world
                .account_permissions
                .iter()
                .any(|(_, permissions)| {
                    permissions
                        .iter()
                        .any(|permission| permission_targets_trigger(permission, trigger_id))
                });
        let role_permission_exists = state_transaction.world.roles.iter().any(|(_, role)| {
            role.permissions
                .iter()
                .any(|permission| permission_targets_trigger(permission, trigger_id))
        });
        if account_permission_exists || role_permission_exists {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle trigger permissions must not be delegated".into(),
            ));
        }

        let pool_contract_address = state_transaction
            .world
            .contract_subject_addresses
            .get(&binding.pool_vault_account_id)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee payout lifecycle pool vault must be an active contract subject"
                        .into(),
                )
            })?;
        let pool_record = fetch_bound_contract_record(state_transaction, &pool_contract_address)
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "validation-fee payout lifecycle requires an active pool contract".into(),
                )
            })?;
        if pool_record.contract_subject != binding.pool_vault_account_id
            || pool_contract_address.subject_id() != binding.pool_vault_account_id
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle pool contract subject differs from the bound vault"
                    .into(),
            ));
        }
        let pool_entrypoints = pool_record.manifest.entrypoints.as_ref().ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle pool contract has no manifest entrypoints".into(),
            )
        })?;
        let matching_pool_entrypoints = pool_entrypoints
            .iter()
            .filter(|entrypoint| {
                entrypoint.name == crate::validation_fee::VALIDATION_FEE_POOL_SWAP_ENTRYPOINT
            })
            .collect::<Vec<_>>();
        if matching_pool_entrypoints.len() != 1
            || matching_pool_entrypoints[0].kind
                != iroha_data_model::smart_contract::manifest::EntryPointKind::Kotoage
            || matching_pool_entrypoints[0].permission.as_deref()
                != Some(crate::validation_fee::VALIDATION_FEE_PAYOUT_WRAPPER_ENTRYPOINT_PERMISSION)
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "validation-fee payout lifecycle requires one exact protected public pool swap selector"
                    .into(),
            ));
        }

        for (permission, required_holder, permission_label) in
            validation_fee_runtime_permissions(binding, &pool_contract_address)
        {
            if require_derived_permissions {
                require_sole_direct_validation_fee_runtime_permission_holder(
                    state_transaction,
                    &permission,
                    &required_holder,
                    permission_label,
                )?;
            } else {
                require_absent_validation_fee_runtime_permission(
                    state_transaction,
                    &permission,
                    permission_label,
                )?;
            }
        }
        Ok(())
    }

    impl Execute for gov::EnactReferendum {
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let pid = self.referendum_id;
            let pid_hex = hex::encode(pid);
            let (proposal, already_terminal) = load_proposal(state_transaction, pid, &pid_hex)?;
            validate_referendum_enactment_binding(&self, &proposal, state_transaction, &pid_hex)?;
            if already_terminal {
                // Enactment is idempotent. Replaying an already-enacted referendum must not
                // re-run its payload against newer state (for example, resurrecting a removed
                // SCCP route or overwriting a subsequent governance update).
                return Ok(());
            }
            match &proposal.kind {
                ProposalKind::DeployContract(payload) => {
                    let payload = payload.clone();
                    let (code_hash_b, abi_hash_b) = extract_hashes(&payload)?;
                    let key = iroha_crypto::Hash::prehashed(code_hash_b);

                    let manifest_inserted = upsert_manifest(
                        state_transaction,
                        key,
                        abi_hash_b,
                        payload.manifest_provenance.as_ref(),
                    )?;
                    #[cfg(not(feature = "telemetry"))]
                    let _ = manifest_inserted;

                    let instance_bound_new = bind_contract_instance(
                        &proposal.proposer,
                        state_transaction,
                        &payload,
                        key,
                    )?;
                    #[cfg(not(feature = "telemetry"))]
                    let _ = instance_bound_new;

                    #[cfg(feature = "telemetry")]
                    record_enactment_telemetry(
                        state_transaction,
                        &payload,
                        code_hash_b,
                        abi_hash_b,
                        manifest_inserted,
                        instance_bound_new,
                    );
                }
                ProposalKind::RuntimeUpgrade(payload) => {
                    enact_runtime_upgrade_proposal(state_transaction, payload, &proposal.proposer)?;
                }
                ProposalKind::SccpRouteGovernance(payload) => {
                    apply_sccp_route_governance_action(
                        payload.action.as_ref().clone(),
                        state_transaction,
                    )?;
                }
                ProposalKind::ValidationFeePolicy(payload) => {
                    if !enact_validation_fee_policy(pid, &proposal, payload, state_transaction)? {
                        close_referendum_if_open(state_transaction, &pid_hex);
                        return Ok(());
                    }
                }
                ProposalKind::ValidationFeePayoutLifecycle(payload) => {
                    if let Some(reason) = payload.payout_binding.invariant_error() {
                        return Err(InstructionExecutionError::InvariantViolation(
                            format!("invalid enacted validation-fee payout lifecycle: {reason}")
                                .into(),
                        ));
                    }
                    let derived_lifecycle_seal =
                        payload.payout_binding.lifecycle_seal().map_err(|_| {
                            InstructionExecutionError::InvariantViolation(
                                "failed to derive enacted validation-fee payout lifecycle seal"
                                    .into(),
                            )
                        })?;
                    if derived_lifecycle_seal == [0; 32] {
                        return Err(InstructionExecutionError::InvariantViolation(
                            "enacted validation-fee payout lifecycle derives an invalid zero seal"
                                .into(),
                        ));
                    }
                    validate_validation_fee_payout_lifecycle_runtime_before_effect_install(
                        &payload.payout_binding,
                        state_transaction,
                    )?;
                    let enactment_height = state_transaction._curr_block.height().get();
                    let _ = validation_fee_parliament_authorization(
                        pid,
                        &proposal,
                        enactment_height,
                        state_transaction,
                    )?;
                    install_derived_validation_fee_runtime_permissions(
                        &payload.payout_binding,
                        state_transaction,
                    )?;
                }
            }

            mark_proposal_enacted(state_transaction, pid);

            close_referendum_if_open(state_transaction, &pid_hex);

            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::ProposalEnacted(
                    iroha_data_model::events::data::governance::GovernanceProposalEnacted {
                        id: pid,
                    },
                ),
            ));
            Ok(())
        }
    }

    impl Execute for scode::ActivateContractInstance {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_contract_binding_governance(
                authority,
                self.contract_address(),
                state_transaction,
            )?;
            let key = *self.code_hash();
            let contract_address = self.contract_address().clone();
            let Some(manifest) = state_transaction
                .world
                .contract_manifests
                .get(&key)
                .cloned()
            else {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract("manifest for code_hash not found".into()),
                ));
            };
            let code_bytes = verify_registered_contract_artifact_for_manifest(
                &state_transaction.world,
                &key,
                &manifest,
            )?;
            let contract_subject =
                ensure_contract_subject_binding(state_transaction, &contract_address)?;
            let existing = state_transaction
                .world
                .contract_instances
                .get(&contract_address)
                .copied();
            if existing == Some(key) {
                // idempotent when same
                return Ok(());
            }
            if existing.is_some()
                && crate::validation_fee::is_enacted_validation_fee_payout_contract(
                    state_transaction,
                    &contract_address,
                )
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "an enacted validation-fee payout lifecycle pins this contract code".into(),
                ));
            }

            if existing.is_some()
                && !has_permission(&state_transaction.world, authority, "CanEnactGovernance")
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanEnactGovernance is required for in-place contract kaizen/改善"
                        .into(),
                ));
            }

            if existing.is_some()
                && crate::smartcontracts::code::pending_contract_lifecycle(
                    &state_transaction.world,
                    &contract_address,
                )
                .map_err(|error| {
                    InstructionExecutionError::InvariantViolation(error.to_string().into())
                })?
                .is_some()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "contract instance cannot perform kaizen/改善 while hajimari/始まり or kaizen/改善 is pending"
                        .into(),
                ));
            }

            let pending_lifecycle_kind = match existing {
                None if manifest.entrypoints.as_ref().is_some_and(|entrypoints| {
                    entrypoints.iter().any(|entrypoint| {
                        entrypoint.kind
                            == iroha_data_model::smart_contract::manifest::EntryPointKind::Hajimari
                    })
                }) => Some((
                    iroha_data_model::smart_contract::manifest::EntryPointKind::Hajimari,
                    None,
                )),
                Some(previous_code_hash)
                    if manifest.entrypoints.as_ref().is_some_and(|entrypoints| {
                        entrypoints.iter().any(|entrypoint| {
                            entrypoint.kind
                                == iroha_data_model::smart_contract::manifest::EntryPointKind::Kaizen
                        })
                    }) => Some((
                        iroha_data_model::smart_contract::manifest::EntryPointKind::Kaizen,
                        Some(previous_code_hash),
                    )),
                None | Some(_) => None,
            };
            let pending_lifecycle = pending_lifecycle_kind
                .map(|(kind, previous_code_hash)| {
                    crate::smartcontracts::code::new_pending_contract_lifecycle(
                        state_transaction,
                        &contract_address,
                        previous_code_hash,
                        key,
                        kind,
                    )
                })
                .transpose()
                .map_err(|error| {
                    InstructionExecutionError::InvariantViolation(error.to_owned().into())
                })?;

            if let Some(previous_code_hash) = existing {
                let previous_trigger_ids: Vec<TriggerId> = state_transaction
                    .world
                    .contract_manifests
                    .get(&previous_code_hash)
                    .and_then(|previous_manifest| previous_manifest.entrypoints.as_ref())
                    .map(|entrypoints| {
                        entrypoints
                            .iter()
                            .flat_map(|entrypoint| {
                                entrypoint
                                    .triggers
                                    .iter()
                                    .map(|descriptor| descriptor.id.clone())
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                for trigger_id in previous_trigger_ids {
                    if state_transaction.world.triggers.remove(&trigger_id) {
                        crate::smartcontracts::isi::triggers::isi::remove_trigger_associated_permissions(
                            state_transaction,
                            &trigger_id,
                        );
                        state_transaction
                            .world
                            .emit_events(Some(TriggerEvent::Deleted(trigger_id)));
                    }
                }
            }
            let needs_trigger_registration =
                manifest.entrypoints.as_ref().is_some_and(|entrypoints| {
                    entrypoints
                        .iter()
                        .any(|entrypoint| !entrypoint.triggers.is_empty())
                });
            if needs_trigger_registration {
                register_manifest_triggers(
                    authority,
                    state_transaction,
                    self.contract_address(),
                    &contract_subject,
                    &code_bytes,
                    &manifest,
                )?;
            }
            state_transaction
                .world
                .contract_instances
                .insert(contract_address.clone(), key);
            crate::smartcontracts::code::set_pending_contract_lifecycle(
                state_transaction,
                &contract_address,
                pending_lifecycle,
            );
            state_transaction
                .world
                .emit_events(Some(SmartContractEvent::InstanceActivated(
                    ContractInstanceActivated {
                        contract_address,
                        code_hash: *self.code_hash(),
                        activated_by: authority.clone(),
                    },
                )));
            Ok(())
        }
    }

    impl Execute for scode::CommitContractDeployment {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let scode::CommitContractDeployment {
                expected_deploy_nonce,
                contract_address,
                code_hash,
                contract_alias,
                lease_expiry_ms,
                expected_previous_contract_address,
            } = self;

            // Deployment never creates or repairs its authority implicitly.
            state_transaction
                .world
                .account(authority)
                .map_err(Error::from)?;
            ensure_contract_binding_governance(authority, &contract_address, state_transaction)?;

            let nonce_key = Name::from_str(
                iroha_data_model::smart_contract::CONTRACT_DEPLOY_NONCE_METADATA_KEY,
            )
            .expect("contract deployment nonce metadata key must remain valid");
            let current_nonce = state_transaction
                .world
                .account(authority)
                .map_err(Error::from)?
                .metadata()
                .get(&nonce_key)
                .map_or(Ok(0_u64), |value| {
                    value.clone().try_into_any_norito::<u64>().map_err(|_| {
                        InstructionExecutionError::InvariantViolation(
                            format!(
                                "account metadata key `{nonce_key}` contains an invalid native contract deployment nonce"
                            )
                            .into(),
                        )
                    })
                })?;
            if current_nonce != expected_deploy_nonce {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        format!(
                            "stale contract deployment nonce: expected {expected_deploy_nonce}, current {current_nonce}"
                        )
                        .into(),
                    ),
                ));
            }
            let next_nonce = current_nonce.checked_add(1).ok_or_else(|| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    "contract deployment nonce overflow".into(),
                ))
            })?;

            let (_, _, alias_dataspace_id) =
                crate::smartcontracts::isi::domain::isi::resolve_contract_alias_components(
                    state_transaction,
                    &contract_alias,
                )?;
            let address_dataspace_id = contract_address.dataspace_id().map_err(|err| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    err.to_string().into(),
                ))
            })?;
            if address_dataspace_id != alias_dataspace_id {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "contract alias dataspace must match contract address dataspace".into(),
                    ),
                ));
            }
            let derived_address = iroha_data_model::smart_contract::ContractAddress::derive(
                iroha_data_model::account::address::chain_discriminant(),
                authority,
                current_nonce,
                alias_dataspace_id,
            )
            .map_err(|err| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    err.to_string().into(),
                ))
            })?;
            if contract_address != derived_address {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        format!(
                            "contract address does not match authority, nonce, chain, and alias dataspace; expected {derived_address}"
                        )
                        .into(),
                    ),
                ));
            }
            if state_transaction
                .world
                .contract_instances
                .get(&contract_address)
                .is_some()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!("new contract address `{contract_address}` is already active").into(),
                ));
            }

            let now_ms = state_transaction.block_unix_timestamp_ms();
            if lease_expiry_ms.is_some_and(|expiry| expiry <= now_ms) {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "lease_expiry_ms must be greater than the current block timestamp".into(),
                    ),
                ));
            }

            let raw_previous_contract_address = state_transaction
                .world
                .contract_aliases
                .get(&contract_alias)
                .cloned();
            let current_previous_contract_address = raw_previous_contract_address
                .as_ref()
                .map(|previous| {
                    let binding = state_transaction
                        .world
                        .contract_alias_bindings
                        .get(previous)
                        .ok_or_else(|| {
                            InstructionExecutionError::InvariantViolation(
                                format!(
                                    "contract alias `{contract_alias}` has no canonical binding record"
                                )
                                .into(),
                            )
                        })?;
                    if binding.alias != contract_alias {
                        return Err(InstructionExecutionError::InvariantViolation(
                            format!(
                                "contract alias `{contract_alias}` has an inconsistent canonical binding record"
                            )
                            .into(),
                        ));
                    }
                    Ok((!binding.is_grace_expired_at(now_ms)).then_some(previous.clone()))
                })
                .transpose()?
                .flatten();
            if current_previous_contract_address != expected_previous_contract_address {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        format!(
                            "stale contract alias target for `{contract_alias}`: expected {:?}, current {:?}",
                            expected_previous_contract_address,
                            current_previous_contract_address
                        )
                        .into(),
                    ),
                ));
            }
            if current_previous_contract_address.as_ref() == Some(&contract_address) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "contract deployment cannot rotate an alias to the same address".into(),
                ));
            }
            if let Some(previous) = current_previous_contract_address.as_ref() {
                let previous_dataspace_id = previous.dataspace_id().map_err(|err| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(err.to_string().into()),
                    )
                })?;
                if previous_dataspace_id != alias_dataspace_id {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "current contract alias target `{previous}` belongs to the wrong dataspace"
                        )
                        .into(),
                    ));
                }
                if state_transaction
                    .world
                    .contract_instances
                    .get(previous)
                    .is_none()
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "current contract alias target `{previous}` is not an active contract"
                        )
                        .into(),
                    ));
                }
                ensure_contract_binding_governance(authority, previous, state_transaction)?;
            }

            crate::smartcontracts::isi::domain::isi::ensure_authority_can_manage_contract_alias(
                state_transaction,
                authority,
                &contract_alias,
            )?;
            crate::smartcontracts::isi::domain::isi::ensure_account_alias_namespace_available_for_contract_alias(
                state_transaction,
                &contract_alias,
            )?;

            let manifest = state_transaction
                .world
                .contract_manifests
                .get(&code_hash)
                .cloned()
                .ok_or_else(|| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "manifest for code_hash not found".into(),
                        ),
                    )
                })?;
            verify_registered_contract_artifact_for_manifest(
                &state_transaction.world,
                &code_hash,
                &manifest,
            )?;

            // Clear a canonical but expired raw binding before rebinding. It is not a live prior
            // target for CAS purposes and therefore is not deactivated here.
            if let Some(raw_previous) = raw_previous_contract_address.as_ref() {
                iroha_data_model::isi::contract_alias::SetContractAlias::clear(
                    raw_previous.clone(),
                )
                .execute(authority, state_transaction)?;
            }
            if let Some(previous) = current_previous_contract_address {
                scode::DeactivateContractInstance {
                    contract_address: previous,
                    reason: Some("atomic contract deployment rotation".to_owned()),
                }
                .execute(authority, state_transaction)?;
            }
            scode::ActivateContractInstance {
                contract_address: contract_address.clone(),
                code_hash,
            }
            .execute(authority, state_transaction)?;
            iroha_data_model::isi::contract_alias::SetContractAlias::bind(
                contract_address,
                contract_alias,
                lease_expiry_ms,
            )
            .execute(authority, state_transaction)?;

            let nonce_value = Json::new(next_nonce);
            state_transaction
                .world
                .account_mut(authority)
                .map_err(Error::from)?
                .insert(nonce_key.clone(), nonce_value.clone());
            state_transaction
                .world
                .emit_events(Some(AccountEvent::MetadataInserted(MetadataChanged {
                    target: authority.clone(),
                    key: nonce_key,
                    value: nonce_value,
                })));
            Ok(())
        }
    }

    impl Execute for scode::DeactivateContractInstance {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if crate::validation_fee::is_enacted_validation_fee_payout_contract(
                state_transaction,
                self.contract_address(),
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "an enacted validation-fee payout lifecycle pins this contract instance".into(),
                ));
            }
            ensure_contract_binding_governance(
                authority,
                self.contract_address(),
                state_transaction,
            )?;
            let key = self.contract_address().clone();
            let Some(prev_hash) = state_transaction
                .world
                .contract_instances
                .remove(key.clone())
            else {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract("contract instance is not active".into()),
                ));
            };
            crate::smartcontracts::code::set_pending_contract_lifecycle(
                state_transaction,
                &key,
                None,
            );
            let reason = self.reason().clone().and_then(|r| {
                let trimmed = r.trim();
                if trimmed.is_empty() {
                    None
                } else {
                    Some(trimmed.to_owned())
                }
            });
            let trigger_ids: Vec<TriggerId> = state_transaction
                .world
                .contract_manifests
                .get(&prev_hash)
                .and_then(|manifest| manifest.entrypoints.as_ref())
                .map(|entrypoints| {
                    entrypoints
                        .iter()
                        .flat_map(|entrypoint| {
                            entrypoint
                                .triggers
                                .iter()
                                .map(|descriptor| descriptor.id.clone())
                        })
                        .collect()
                })
                .unwrap_or_default();
            for trigger_id in trigger_ids {
                if state_transaction.world.triggers.remove(&trigger_id) {
                    crate::smartcontracts::isi::triggers::isi::remove_trigger_associated_permissions(
                        state_transaction,
                        &trigger_id,
                    );
                    state_transaction
                        .world
                        .emit_events(Some(TriggerEvent::Deleted(trigger_id)));
                }
            }
            state_transaction
                .world
                .emit_events(Some(SmartContractEvent::InstanceDeactivated(
                    ContractInstanceDeactivated {
                        contract_address: key,
                        previous_code_hash: prev_hash,
                        deactivated_by: authority.clone(),
                        reason,
                    },
                )));
            Ok(())
        }
    }

    const DEFAULT_MAX_CONTRACT_CODE_BYTES: u64 = 16 * 1024 * 1024;
    // Keep every accepted descriptor representable as a `Vec` length on supported
    // 32-bit and 64-bit peers before any host-width conversion occurs.
    const MAX_PORTABLE_CONTRACT_CODE_BYTES: u64 = 2_147_483_647;
    const MAX_PENDING_CONTRACT_CODE_UPLOADS_PER_AUTHORITY: usize = 4;

    fn contract_code_cap_bytes(state_transaction: &StateTransaction<'_, '_>) -> u64 {
        let Ok(name) = core::str::FromStr::from_str("max_contract_code_bytes") else {
            return DEFAULT_MAX_CONTRACT_CODE_BYTES;
        };
        let id = iroha_data_model::parameter::CustomParameterId(name);
        state_transaction
            .world
            .parameters
            .get()
            .custom()
            .get(&id)
            .and_then(|custom| custom.payload().try_into_any_norito::<u64>().ok())
            .unwrap_or(DEFAULT_MAX_CONTRACT_CODE_BYTES)
    }

    fn validate_pending_contract_uploads_against_cap(
        cap_bytes: u64,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let mut totals = BTreeMap::<AccountId, u64>::new();
        for (key, descriptor) in state_transaction.world.contract_code_uploads.iter() {
            let total = totals.entry(key.authority.clone()).or_default();
            *total = total.checked_add(descriptor.total_size).ok_or_else(|| {
                invalid_smart_contract_parameter(
                    "pending contract upload declared-byte total overflow",
                )
            })?;
            if *total > cap_bytes {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "max_contract_code_bytes {cap_bytes} is below pending declared bytes {} for authority {}",
                        *total, key.authority
                    )
                    .into(),
                ));
            }
        }
        Ok(())
    }

    fn validate_contract_upload_descriptor(
        total_size: u64,
        chunk_count: u32,
        cap_bytes: u64,
    ) -> Result<usize, Error> {
        if total_size == 0 {
            return Err(invalid_smart_contract_parameter(
                "contract upload total_size must be non-zero",
            ));
        }
        if total_size > MAX_PORTABLE_CONTRACT_CODE_BYTES {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "contract upload total_size exceeds the portable consensus limit: {total_size} > {MAX_PORTABLE_CONTRACT_CODE_BYTES}"
                )
                .into(),
            ));
        }
        if total_size > cap_bytes {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("code bytes exceed cap: {total_size} > {cap_bytes}").into(),
            ));
        }
        let chunk_bytes = u64::try_from(scode::SMART_CONTRACT_CODE_CHUNK_BYTES).map_err(|_| {
            invalid_smart_contract_parameter("contract chunk size exceeds u64 representation")
        })?;
        let expected_chunk_count = total_size
            .checked_sub(1)
            .and_then(|value| value.checked_div(chunk_bytes))
            .and_then(|value| value.checked_add(1))
            .ok_or_else(|| {
                invalid_smart_contract_parameter("contract upload chunk count overflow")
            })?;
        let expected_chunk_count = u32::try_from(expected_chunk_count).map_err(|_| {
            invalid_smart_contract_parameter("contract upload requires more than u32::MAX chunks")
        })?;
        if chunk_count != expected_chunk_count {
            return Err(invalid_smart_contract_parameter(format!(
                "contract upload chunk_count mismatch: expected {expected_chunk_count}, got {chunk_count}"
            )));
        }
        usize::try_from(total_size).map_err(|_| {
            invalid_smart_contract_parameter(
                "contract upload total_size exceeds host pointer-width representation",
            )
        })
    }

    fn validate_contract_upload_chunk(
        total_size: u64,
        chunk_index: u32,
        chunk_count: u32,
        chunk: &[u8],
    ) -> Result<(), Error> {
        if chunk_index >= chunk_count {
            return Err(invalid_smart_contract_parameter(format!(
                "contract upload chunk_index {chunk_index} is outside chunk_count {chunk_count}"
            )));
        }
        let chunk_bytes = u64::try_from(scode::SMART_CONTRACT_CODE_CHUNK_BYTES).map_err(|_| {
            invalid_smart_contract_parameter("contract chunk size exceeds u64 representation")
        })?;
        let offset = u64::from(chunk_index)
            .checked_mul(chunk_bytes)
            .ok_or_else(|| invalid_smart_contract_parameter("contract chunk offset overflow"))?;
        let remaining = total_size.checked_sub(offset).ok_or_else(|| {
            invalid_smart_contract_parameter("contract chunk offset exceeds total_size")
        })?;
        let expected_len = remaining.min(chunk_bytes);
        let expected_len = usize::try_from(expected_len).map_err(|_| {
            invalid_smart_contract_parameter(
                "contract chunk length exceeds host pointer-width representation",
            )
        })?;
        if chunk.len() != expected_len {
            return Err(invalid_smart_contract_parameter(format!(
                "contract upload chunk {chunk_index} length mismatch: expected {expected_len}, got {}",
                chunk.len()
            )));
        }
        Ok(())
    }

    fn ensure_contract_upload_quota(
        authority: &AccountId,
        candidate: &SmartContractCodeUploadKey,
        candidate_descriptor: SmartContractCodeUploadDescriptor,
        cap_bytes: u64,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let mut pending_count = 0usize;
        let mut declared_bytes = 0u64;
        let mut candidate_exists = false;
        for (key, descriptor) in state_transaction
            .world
            .contract_code_uploads
            .range(SmartContractCodeUploadKey::authority_range(authority))
        {
            pending_count = pending_count.checked_add(1).ok_or_else(|| {
                invalid_smart_contract_parameter("pending contract upload count overflow")
            })?;
            declared_bytes = declared_bytes
                .checked_add(descriptor.total_size)
                .ok_or_else(|| {
                    invalid_smart_contract_parameter(
                        "pending contract upload declared-byte total overflow",
                    )
                })?;
            candidate_exists |= key == candidate;
        }
        if !candidate_exists {
            pending_count = pending_count.checked_add(1).ok_or_else(|| {
                invalid_smart_contract_parameter("pending contract upload count overflow")
            })?;
            declared_bytes = declared_bytes
                .checked_add(candidate_descriptor.total_size)
                .ok_or_else(|| {
                    invalid_smart_contract_parameter(
                        "pending contract upload declared-byte total overflow",
                    )
                })?;
        }
        if pending_count > MAX_PENDING_CONTRACT_CODE_UPLOADS_PER_AUTHORITY {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "at most {MAX_PENDING_CONTRACT_CODE_UPLOADS_PER_AUTHORITY} pending contract uploads are allowed per authority"
                )
                .into(),
            ));
        }
        if declared_bytes > cap_bytes {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "pending contract upload declared bytes exceed authority cap: {declared_bytes} > {cap_bytes}"
                )
                .into(),
            ));
        }
        Ok(())
    }

    fn register_verified_contract_code_bytes(
        authority: &AccountId,
        code_hash: Hash,
        code: Vec<u8>,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let code_len = u64::try_from(code.len()).map_err(|_| {
            invalid_smart_contract_parameter("contract artifact length exceeds u64 representation")
        })?;
        if code_len > MAX_PORTABLE_CONTRACT_CODE_BYTES {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "contract artifact exceeds the portable consensus limit: {code_len} > {MAX_PORTABLE_CONTRACT_CODE_BYTES}"
                )
                .into(),
            ));
        }
        let cap_bytes = contract_code_cap_bytes(state_transaction);
        if code_len > cap_bytes {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("code bytes exceed cap: {code_len} > {cap_bytes}").into(),
            ));
        }
        let verified = ivm::verify_contract_artifact(&code).map_err(|err| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                err.to_string().into(),
            ))
        })?;
        crate::smartcontracts::ivm::validate_cycle_ceiling(
            &verified.metadata,
            state_transaction.pipeline.ivm_max_cycles_upper_bound,
        )
        .map_err(|error| invalid_smart_contract_parameter(error.to_string()))?;
        if verified.code_hash != code_hash {
            return Err(InstructionExecutionError::InvariantViolation(
                "code_hash does not match embedded contract artifact".into(),
            ));
        }
        if let Some(existing) = state_transaction.world.contract_code.get(&code_hash) {
            if existing.as_slice() != code.as_slice() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "different code bytes already stored for this code_hash".into(),
                ));
            }
            return Ok(());
        }
        if state_transaction
            .world
            .contract_instances
            .iter()
            .any(|(_, existing_hash)| *existing_hash == code_hash)
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "contract bytecode cannot be registered after an instance is bound; register and verify bytes first"
                    .into(),
            ));
        }
        state_transaction
            .world
            .contract_code
            .insert(code_hash, code);
        state_transaction
            .world
            .emit_events(Some(SmartContractEvent::CodeRegistered(
                ContractCodeRegistered {
                    code_hash,
                    registrar: authority.clone(),
                },
            )));
        Ok(())
    }

    impl Execute for scode::RegisterSmartContractBytes {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_contract_lifecycle_authority(authority, state_transaction)?;
            register_verified_contract_code_bytes(
                authority,
                *self.code_hash(),
                self.code().clone(),
                state_transaction,
            )
        }
    }

    impl Execute for scode::UploadSmartContractCodeChunk {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_contract_lifecycle_authority(authority, state_transaction)?;
            let cap_bytes = contract_code_cap_bytes(state_transaction);
            let total_size = *self.total_size();
            let chunk_count = *self.chunk_count();
            let chunk_index = *self.chunk_index();
            let chunk = self.chunk().clone();
            let total_size_usize =
                validate_contract_upload_descriptor(total_size, chunk_count, cap_bytes)?;
            validate_contract_upload_chunk(total_size, chunk_index, chunk_count, &chunk)?;

            let upload_key = SmartContractCodeUploadKey::new(authority.clone(), *self.code_hash());
            let descriptor = SmartContractCodeUploadDescriptor {
                total_size,
                chunk_count,
            };
            let descriptor_exists = match state_transaction
                .world
                .contract_code_uploads
                .get(&upload_key)
            {
                Some(existing) if *existing != descriptor => {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "contract upload descriptor cannot change after staging begins".into(),
                    ));
                }
                Some(_) => true,
                None => false,
            };
            let chunk_key = SmartContractCodeUploadChunkKey::new(upload_key.clone(), chunk_index);
            let chunk_exists = match state_transaction
                .world
                .contract_code_upload_chunks
                .get(&chunk_key)
            {
                Some(existing) if existing.as_slice() != chunk.as_slice() => {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "conflicting duplicate contract upload chunk".into(),
                    ));
                }
                Some(_) => true,
                None => false,
            };

            if let Some(existing) = state_transaction.world.contract_code.get(self.code_hash()) {
                if existing.len() != total_size_usize {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "registered code length conflicts with upload descriptor".into(),
                    ));
                }
                let offset = usize::try_from(chunk_index)
                    .ok()
                    .and_then(|index| index.checked_mul(scode::SMART_CONTRACT_CODE_CHUNK_BYTES))
                    .ok_or_else(|| {
                        invalid_smart_contract_parameter("contract chunk offset overflow")
                    })?;
                let end = offset.checked_add(chunk.len()).ok_or_else(|| {
                    invalid_smart_contract_parameter("contract chunk end offset overflow")
                })?;
                if existing.get(offset..end) != Some(chunk.as_slice()) {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "uploaded chunk conflicts with already registered code".into(),
                    ));
                }
                if descriptor_exists && !chunk_exists {
                    state_transaction
                        .world
                        .contract_code_upload_chunks
                        .insert(chunk_key, chunk);
                }
                return Ok(());
            }

            ensure_contract_upload_quota(
                authority,
                &upload_key,
                descriptor,
                cap_bytes,
                state_transaction,
            )?;
            if chunk_exists {
                if !descriptor_exists {
                    state_transaction
                        .world
                        .contract_code_uploads
                        .insert(upload_key, descriptor);
                }
                return Ok(());
            }

            if !descriptor_exists {
                state_transaction
                    .world
                    .contract_code_uploads
                    .insert(upload_key, descriptor);
            }
            state_transaction
                .world
                .contract_code_upload_chunks
                .insert(chunk_key, chunk);
            Ok(())
        }
    }

    fn clear_contract_code_upload(
        upload_key: &SmartContractCodeUploadKey,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) {
        state_transaction
            .world
            .contract_code_uploads
            .remove(upload_key.clone());
        let chunk_keys = state_transaction
            .world
            .contract_code_upload_chunks
            .range(SmartContractCodeUploadChunkKey::upload_range(upload_key))
            .map(|(key, _)| key.clone())
            .collect::<Vec<_>>();
        for chunk_key in chunk_keys {
            state_transaction
                .world
                .contract_code_upload_chunks
                .remove(chunk_key);
        }
    }

    impl Execute for scode::FinalizeSmartContractCodeUpload {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_contract_lifecycle_authority(authority, state_transaction)?;
            let cap_bytes = contract_code_cap_bytes(state_transaction);
            let total_size = *self.total_size();
            let chunk_count = *self.chunk_count();
            let total_size_usize =
                validate_contract_upload_descriptor(total_size, chunk_count, cap_bytes)?;
            let upload_key = SmartContractCodeUploadKey::new(authority.clone(), *self.code_hash());
            let descriptor = SmartContractCodeUploadDescriptor {
                total_size,
                chunk_count,
            };

            let staged_descriptor = state_transaction
                .world
                .contract_code_uploads
                .get(&upload_key)
                .copied();
            if let Some(staged_descriptor) = staged_descriptor {
                if staged_descriptor != descriptor {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "contract upload finalization descriptor does not match staged descriptor"
                            .into(),
                    ));
                }
            }
            if staged_descriptor.is_none() {
                if let Some(existing) = state_transaction
                    .world
                    .contract_code
                    .get(self.code_hash())
                    .cloned()
                {
                    if existing.len() != total_size_usize {
                        return Err(InstructionExecutionError::InvariantViolation(
                            "registered code length conflicts with finalization descriptor".into(),
                        ));
                    }
                    register_verified_contract_code_bytes(
                        authority,
                        *self.code_hash(),
                        existing,
                        state_transaction,
                    )?;
                    return Ok(());
                }
                return Err(invalid_smart_contract_parameter(
                    "pending contract upload descriptor not found",
                ));
            }

            let mut code = Vec::new();
            code.try_reserve_exact(total_size_usize).map_err(|error| {
                invalid_smart_contract_parameter(format!(
                    "unable to reserve contract artifact buffer: {error}"
                ))
            })?;
            for chunk_index in 0..chunk_count {
                let chunk_key =
                    SmartContractCodeUploadChunkKey::new(upload_key.clone(), chunk_index);
                let chunk = state_transaction
                    .world
                    .contract_code_upload_chunks
                    .get(&chunk_key)
                    .ok_or_else(|| {
                        invalid_smart_contract_parameter(format!(
                            "contract upload is missing chunk {chunk_index} of {chunk_count}"
                        ))
                    })?;
                validate_contract_upload_chunk(total_size, chunk_index, chunk_count, chunk)?;
                code.extend_from_slice(chunk);
            }
            if code.len() != total_size_usize {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "reassembled contract size mismatch: expected {total_size_usize}, got {}",
                        code.len()
                    )
                    .into(),
                ));
            }

            register_verified_contract_code_bytes(
                authority,
                *self.code_hash(),
                code,
                state_transaction,
            )?;
            clear_contract_code_upload(&upload_key, state_transaction);
            Ok(())
        }
    }

    impl Execute for scode::CancelSmartContractCodeUpload {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let upload_key = SmartContractCodeUploadKey::new(authority.clone(), *self.code_hash());
            clear_contract_code_upload(&upload_key, state_transaction);
            Ok(())
        }
    }

    impl Execute for scode::RemoveSmartContractBytes {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_contract_lifecycle_authority(authority, state_transaction)?;
            if state_transaction
                .world
                .contract_manifests
                .get(self.code_hash())
                .is_some()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "contract manifest referencing code_hash still exists".into(),
                ));
            }
            let code_in_use = state_transaction
                .world
                .contract_instances
                .iter()
                .any(|(_, hash)| hash == self.code_hash());
            if code_in_use {
                return Err(InstructionExecutionError::InvariantViolation(
                    "active contract instance references this code_hash".into(),
                ));
            }
            let removed = state_transaction
                .world
                .contract_code
                .remove(*self.code_hash());
            if removed.is_none() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "contract code for code_hash not found".into(),
                    ),
                ));
            }
            let reason = self.reason().clone().and_then(|r| {
                let trimmed = r.trim();
                if trimmed.is_empty() {
                    None
                } else {
                    Some(trimmed.to_owned())
                }
            });
            state_transaction
                .world
                .emit_events(Some(SmartContractEvent::CodeRemoved(ContractCodeRemoved {
                    code_hash: *self.code_hash(),
                    removed_by: authority.clone(),
                    reason,
                })));
            Ok(())
        }
    }

    impl Execute for gov::FinalizeReferendum {
        #[allow(clippy::too_many_lines)]
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::events::data::governance as gev;

            let expected_referendum_id = hex::encode(self.proposal_id);
            if self.referendum_id != expected_referendum_id {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "referendum_id does not match proposal_id".into(),
                    ),
                ));
            }
            let proposal = state_transaction
                .world
                .governance_proposals
                .get(&self.proposal_id)
                .cloned()
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "governance proposal not found".into(),
                    )
                })?;
            if proposal.finalization_evidence.is_some() {
                close_referendum_if_open(state_transaction, &self.referendum_id);
                return Ok(());
            }
            if matches!(
                proposal.status,
                crate::state::GovernanceProposalStatus::Rejected
                    | crate::state::GovernanceProposalStatus::Enacted
                    | crate::state::GovernanceProposalStatus::Superseded
            ) {
                close_referendum_if_open(state_transaction, &self.referendum_id);
                return Ok(());
            }

            let referendum = state_transaction
                .world
                .governance_referenda
                .get(&self.referendum_id)
                .copied()
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "referendum not found for governance proposal".into(),
                    )
                })?;
            if referendum.status == crate::state::GovernanceReferendumStatus::Proposed {
                return Err(InstructionExecutionError::InvariantViolation(
                    "all required parliament bodies must approve before finalization".into(),
                ));
            }
            let validation_fee_rules =
                validation_fee_plain_electorate_rules(&proposal.kind).cloned();
            let mut validation_fee_electorate_snapshot = None;
            if let Some(rules) = validation_fee_rules.as_ref() {
                if let Some(reason) = rules.invariant_error() {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "validation-fee proposal retained invalid PLAIN electorate rules: {reason}"
                        )
                        .into(),
                    ));
                }
                if referendum.mode != crate::state::GovernanceReferendumMode::Plain {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "validation-fee governance supports plain referendum voting only".into(),
                    ));
                }
                let snapshot = proposal.parliament_snapshot.as_ref().ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "validation-fee proposal is missing its parliament snapshot".into(),
                    )
                })?;
                if compute_parliament_roster_root(&snapshot.bodies)? != snapshot.roster_root {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "validation-fee parliament snapshot commitment mismatch".into(),
                    ));
                }
                let approvals = state_transaction
                    .world
                    .governance_stage_approvals
                    .get(&self.referendum_id)
                    .cloned()
                    .unwrap_or_default();
                if !parliament_approval_gate_met(
                    &proposal.kind,
                    &approvals,
                    snapshot.selection_epoch,
                ) || required_parliament_bodies(&proposal.kind)
                    .iter()
                    .copied()
                    .any(|body| approvals.rejection_quorum_met(body, snapshot.selection_epoch))
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "all seven parliament bodies must reach quorum before validation-fee finalization"
                            .into(),
                    ));
                }
                if approvals.approval_gate_height.is_none() {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "validation-fee proposal has no retained Parliament approval gate height"
                            .into(),
                    ));
                }
                validation_fee_electorate_snapshot = Some(
                    retained_validation_fee_plain_electorate_snapshot(
                        self.proposal_id,
                        &proposal,
                        referendum,
                        &approvals,
                        rules,
                    )?
                    .clone(),
                );
            }

            let now_h = state_transaction._curr_block.height().get();
            if referendum.mode == crate::state::GovernanceReferendumMode::Plain
                && now_h <= referendum.h_end
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "proposal-backed plain referendum cannot be finalized before its inclusive voting window ends"
                        .into(),
                ));
            }
            if validation_fee_rules.is_some()
                && now_h
                    != referendum
                        .h_end
                        .checked_add(1)
                        .ok_or_else(|| Error::from(MathError::Overflow))?
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "validation-fee PLAIN referendum must finalize exactly one block after its inclusive window"
                        .into(),
                ));
            }
            if referendum.mode == crate::state::GovernanceReferendumMode::Zk
                && (now_h < referendum.h_start || now_h > referendum.h_end)
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "referendum finalization is outside the exact stored window".into(),
                ));
            }
            let tally_height = match referendum.mode {
                crate::state::GovernanceReferendumMode::Plain => referendum.h_end,
                crate::state::GovernanceReferendumMode::Zk => now_h,
            };
            let mut approve: u128 = 0;
            let mut reject: u128 = 0;
            let mut abstain: u128 = 0;
            match referendum.mode {
                crate::state::GovernanceReferendumMode::Plain => {
                    if let Some(locks) = state_transaction
                        .world
                        .governance_locks
                        .get(&self.referendum_id)
                    {
                        let (step, max_c) = validation_fee_rules.as_ref().map_or(
                            (
                                state_transaction.gov.conviction_step_blocks.max(1),
                                state_transaction.gov.max_conviction,
                            ),
                            |rules| (rules.conviction_step_blocks, rules.max_conviction),
                        );
                        for (owner, rec) in &locks.locks {
                            if validation_fee_rules.is_some()
                                && !validation_fee_electorate_snapshot
                                    .as_ref()
                                    .is_some_and(|snapshot| snapshot.contains(owner))
                            {
                                return Err(InstructionExecutionError::InvariantViolation(
                                    "validation-fee citizen lock owner is outside the frozen PLAIN electorate"
                                        .into(),
                                ));
                            }
                            if let Some(rules) = validation_fee_rules.as_ref()
                                && (&rec.owner != owner
                                    || rec.amount != rules.ballot_amount
                                    || !rec.slashed.is_zero()
                                    || rec.duration_blocks != rules.ballot_duration_blocks
                                    || rec.custody.as_ref()
                                        != Some(&validation_fee_lock_custody(rules))
                                    || rec.direction > 2)
                            {
                                return Err(InstructionExecutionError::InvariantViolation(
                                    "validation-fee citizen lock differs from retained PLAIN electorate rules"
                                        .into(),
                                ));
                            }
                            if rec.expiry_height < tally_height {
                                if validation_fee_rules.is_some() {
                                    return Err(
                                        InstructionExecutionError::InvariantViolation(
                                            "validation-fee citizen lock expires before the retained referendum end"
                                                .into(),
                                        ),
                                    );
                                }
                                continue;
                            }
                            let weight =
                                plain_ballot_weight(&rec.amount, rec.duration_blocks, step, max_c)?;
                            let tally = match rec.direction {
                                0 => &mut approve,
                                1 => &mut reject,
                                2 => &mut abstain,
                                _ => continue,
                            };
                            *tally = tally
                                .checked_add(weight)
                                .ok_or_else(|| Error::from(MathError::Overflow))?;
                        }
                    }
                }
                crate::state::GovernanceReferendumMode::Zk => {
                    let election = state_transaction
                        .world
                        .elections
                        .get(&self.referendum_id)
                        .ok_or_else(|| {
                            InstructionExecutionError::InvariantViolation(
                                "ZK election not found for referendum".into(),
                            )
                        })?;
                    if !election.finalized {
                        return Err(InstructionExecutionError::InvariantViolation(
                            "election tally not finalized".into(),
                        ));
                    }
                    if election.tally.len() < 2 {
                        return Err(InstructionExecutionError::InvariantViolation(
                            "election tally missing options".into(),
                        ));
                    }
                    approve = u128::from(election.tally[0]);
                    reject = u128::from(election.tally[1]);
                    abstain = election.tally.get(2).copied().map_or(0, u128::from);
                }
            }

            let turnout = approve
                .checked_add(reject)
                .and_then(|value| value.checked_add(abstain))
                .ok_or_else(|| Error::from(MathError::Overflow))?;
            let (min_turnout, num, den) = validation_fee_rules.as_ref().map_or(
                (
                    state_transaction.gov.min_turnout,
                    state_transaction.gov.approval_threshold_q_num,
                    state_transaction.gov.approval_threshold_q_den.max(1),
                ),
                |rules| {
                    (
                        rules.min_turnout,
                        rules.approval_threshold_numerator,
                        rules.approval_threshold_denominator,
                    )
                },
            );
            let decision_approve = if turnout >= min_turnout {
                let lhs = approve
                    .checked_mul(u128::from(den))
                    .ok_or_else(|| Error::from(MathError::Overflow))?;
                let rhs = turnout
                    .checked_mul(u128::from(num))
                    .ok_or_else(|| Error::from(MathError::Overflow))?;
                lhs >= rhs
            } else {
                false
            };
            let evidence = GovernanceFinalizationEvidence {
                proposal_id: self.proposal_id,
                referendum_id: self.proposal_id,
                finalized_at_height: tally_height,
                mode: match referendum.mode {
                    crate::state::GovernanceReferendumMode::Zk => gov::VotingMode::Zk,
                    crate::state::GovernanceReferendumMode::Plain => gov::VotingMode::Plain,
                },
                approve,
                reject,
                abstain,
                min_turnout,
                approval_threshold_numerator: num,
                approval_threshold_denominator: den,
                approved: decision_approve,
            };
            if decision_approve {
                state_transaction
                    .world
                    .emit_events(Some(gev::GovernanceEvent::ProposalApproved(
                        gev::GovernanceProposalApproved {
                            id: self.proposal_id,
                        },
                    )));
                if let Some(rec) = state_transaction
                    .world
                    .governance_proposals
                    .get_mut(&self.proposal_id)
                {
                    rec.status = crate::state::GovernanceProposalStatus::Approved;
                    rec.finalization_evidence = Some(evidence);
                }
            } else {
                state_transaction
                    .world
                    .emit_events(Some(gev::GovernanceEvent::ProposalRejected(
                        gev::GovernanceProposalRejected {
                            id: self.proposal_id,
                        },
                    )));
                if let Some(rec) = state_transaction
                    .world
                    .governance_proposals
                    .get_mut(&self.proposal_id)
                {
                    rec.status = crate::state::GovernanceProposalStatus::Rejected;
                    rec.finalization_evidence = Some(evidence);
                }
            }
            close_referendum_if_open(state_transaction, &self.referendum_id);
            Ok(())
        }
    }

    impl Execute for gov::ApproveGovernanceProposal {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            record_parliament_stage_decision(
                self.body,
                self.proposal_id,
                gov::ParliamentDecision::Approve,
                authority,
                state_transaction,
            )
        }
    }

    impl Execute for gov::CastParliamentBallot {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            record_parliament_stage_decision(
                self.body,
                self.proposal_id,
                self.decision,
                authority,
                state_transaction,
            )
        }
    }

    struct ApprovalContext {
        proposal_id: [u8; 32],
        rid: String,
        referendum: crate::state::GovernanceReferendumRecord,
        proposal_kind: ProposalKind,
        bodies: iroha_data_model::governance::types::ParliamentBodies,
        roster: iroha_data_model::governance::types::ParliamentRoster,
        epoch: u64,
        persist_epoch_bodies: bool,
        now_h: u64,
        quorum_bps: u16,
    }

    fn record_parliament_stage_decision(
        body: ParliamentBody,
        proposal_id: [u8; 32],
        decision: gov::ParliamentDecision,
        authority: &AccountId,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let ctx = load_approval_context(body, proposal_id, state_transaction)?;
        ensure_parliament_member(authority, &ctx.roster)?;
        if ctx.persist_epoch_bodies {
            persist_parliament_bodies_if_missing(&ctx, state_transaction);
        }

        let Some(record) =
            record_parliament_decision(body, decision, authority, &ctx, state_transaction)
        else {
            return Ok(());
        };

        state_transaction
            .world
            .emit_events(Some(GovernanceEvent::ParliamentBallotRecorded(
                GovernanceParliamentBallotRecorded {
                    proposal_id,
                    epoch: ctx.epoch,
                    body,
                    decision,
                    approvals: record.approvals,
                    rejections: record.rejections,
                    abstentions: record.abstentions,
                    required: record.required,
                },
            )));
        if matches!(decision, gov::ParliamentDecision::Approve) {
            state_transaction
                .world
                .emit_events(Some(GovernanceEvent::ParliamentApprovalRecorded(
                    GovernanceParliamentApprovalRecorded {
                        proposal_id,
                        epoch: ctx.epoch,
                        body,
                        approvals: record.approvals,
                        required: record.required,
                    },
                )));
        }
        maybe_apply_parliament_decision(body, &ctx, &record.approvals_snapshot, state_transaction);
        Ok(())
    }

    fn load_approval_context(
        body: ParliamentBody,
        proposal_id: [u8; 32],
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<ApprovalContext, Error> {
        let proposal = state_transaction
            .world
            .governance_proposals
            .get(&proposal_id)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "governance proposal not found".into(),
                )
            })?;
        if matches!(
            proposal.status,
            crate::state::GovernanceProposalStatus::Approved
                | crate::state::GovernanceProposalStatus::Rejected
                | crate::state::GovernanceProposalStatus::Enacted
                | crate::state::GovernanceProposalStatus::Superseded
        ) {
            return Err(InstructionExecutionError::InvariantViolation(
                "governance proposal is no longer open for parliament ballots".into(),
            ));
        }
        let rid = hex::encode(proposal_id);
        let referendum = state_transaction
            .world
            .governance_referenda
            .get(&rid)
            .copied()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "referendum not found for governance proposal".into(),
                )
            })?;
        if referendum.status == crate::state::GovernanceReferendumStatus::Closed {
            return Err(InstructionExecutionError::InvariantViolation(
                "referendum already closed".into(),
            ));
        }
        if referendum.status != crate::state::GovernanceReferendumStatus::Proposed {
            return Err(InstructionExecutionError::InvariantViolation(
                "referendum already left parliament stage".into(),
            ));
        }
        let now_h = state_transaction._curr_block.height().get();
        if now_h > referendum.h_end {
            return Err(InstructionExecutionError::InvariantViolation(
                "referendum window elapsed for parliament ballots".into(),
            ));
        }
        if !required_parliament_bodies(&proposal.kind).contains(&body) {
            return Err(InstructionExecutionError::InvariantViolation(
                "parliament body is not required for this proposal".into(),
            ));
        }
        let (bodies, epoch, persist_epoch_bodies) =
            if resolve_governance_approval_mode(state_transaction)
                == GovernanceApprovalMode::ParliamentSortitionJit
            {
                if let Some(snapshot) = proposal.parliament_snapshot.as_ref() {
                    if snapshot.bodies.selection_epoch != snapshot.selection_epoch {
                        return Err(InstructionExecutionError::InvariantViolation(
                            "proposal parliament snapshot epoch mismatch".into(),
                        ));
                    }
                    let roster_root = compute_parliament_roster_root(&snapshot.bodies)?;
                    if roster_root != snapshot.roster_root {
                        return Err(InstructionExecutionError::InvariantViolation(
                            "proposal parliament snapshot commitment mismatch".into(),
                        ));
                    }
                    (snapshot.bodies.clone(), snapshot.selection_epoch, false)
                } else {
                    let term_blocks = state_transaction.gov.parliament_term_blocks.max(1);
                    let fallback_epoch = now_h.saturating_sub(1).saturating_div(term_blocks);
                    let council = state_transaction
                        .world
                        .council
                        .get(&fallback_epoch)
                        .cloned()
                        .ok_or_else(|| {
                            InstructionExecutionError::InvariantViolation(
                            "proposal parliament snapshot missing and council roster unavailable"
                                .into(),
                        )
                        })?;
                    let beacon = derive_epoch_parliament_beacon(fallback_epoch, state_transaction);
                    let bodies = state_transaction
                        .world
                        .parliament_bodies
                        .get(&fallback_epoch)
                        .cloned()
                        .unwrap_or_else(|| {
                            derive_parliament_bodies(
                                &state_transaction.gov,
                                &state_transaction.chain_id,
                                fallback_epoch,
                                &beacon,
                                &council,
                            )
                        });
                    (bodies, fallback_epoch, true)
                }
            } else {
                let term_blocks = state_transaction.gov.parliament_term_blocks.max(1);
                let epoch = now_h.saturating_sub(1).saturating_div(term_blocks);
                let council = state_transaction
                    .world
                    .council
                    .get(&epoch)
                    .cloned()
                    .ok_or_else(|| {
                        InstructionExecutionError::InvariantViolation(
                            "council roster missing for current epoch".into(),
                        )
                    })?;
                let beacon = derive_epoch_parliament_beacon(epoch, state_transaction);
                let bodies = state_transaction
                    .world
                    .parliament_bodies
                    .get(&epoch)
                    .cloned()
                    .unwrap_or_else(|| {
                        derive_parliament_bodies(
                            &state_transaction.gov,
                            &state_transaction.chain_id,
                            epoch,
                            &beacon,
                            &council,
                        )
                    });
                (bodies, epoch, true)
            };
        if bodies.selection_epoch != epoch {
            return Err(InstructionExecutionError::InvariantViolation(
                "parliament roster epoch mismatch".into(),
            ));
        }
        let Some(roster) = bodies.rosters.get(&body).cloned() else {
            return Err(InstructionExecutionError::InvariantViolation(
                "parliament roster missing for requested body".into(),
            ));
        };
        if roster.body != body {
            return Err(InstructionExecutionError::InvariantViolation(
                "parliament roster body mismatch".into(),
            ));
        }
        if roster.epoch != epoch {
            return Err(InstructionExecutionError::InvariantViolation(
                "parliament body roster epoch mismatch".into(),
            ));
        }
        if roster.members.is_empty() {
            return Err(InstructionExecutionError::InvariantViolation(
                "parliament roster empty for requested body".into(),
            ));
        }

        Ok(ApprovalContext {
            proposal_id,
            rid,
            referendum,
            proposal_kind: proposal.kind,
            bodies,
            roster,
            epoch,
            persist_epoch_bodies,
            now_h,
            quorum_bps: state_transaction.gov.parliament_quorum_bps,
        })
    }

    fn ensure_parliament_member(
        authority: &AccountId,
        roster: &iroha_data_model::governance::types::ParliamentRoster,
    ) -> Result<(), Error> {
        let eligible = roster.members.iter().any(|member| member == authority);
        if eligible {
            Ok(())
        } else {
            Err(InstructionExecutionError::InvariantViolation(
                "only seated parliament members may vote for this body".into(),
            ))
        }
    }

    fn persist_parliament_bodies_if_missing(
        ctx: &ApprovalContext,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) {
        if state_transaction
            .world
            .parliament_bodies
            .get(&ctx.epoch)
            .is_none()
        {
            state_transaction
                .world
                .parliament_bodies
                .insert(ctx.epoch, ctx.bodies.clone());
        }
    }

    struct ParliamentDecisionRecord {
        approvals: u32,
        rejections: u32,
        abstentions: u32,
        required: u32,
        approvals_snapshot: crate::state::GovernanceStageApprovals,
    }

    fn record_parliament_decision(
        body: ParliamentBody,
        decision: gov::ParliamentDecision,
        authority: &AccountId,
        ctx: &ApprovalContext,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Option<ParliamentDecisionRecord> {
        let committee_size = ctx.roster.members.len();
        let required = crate::state::council_quorum_threshold(committee_size, ctx.quorum_bps);
        let mut approvals = state_transaction
            .world
            .governance_stage_approvals
            .get(&ctx.rid)
            .cloned()
            .unwrap_or_default();
        let (inserted, approvals_count, rejections_count, abstentions_count, required) = {
            let stage_record = approvals.ensure_stage(body, ctx.epoch, required, ctx.quorum_bps);
            let inserted = stage_record.record_decision(authority.clone(), decision);
            let approvals_count = u32::try_from(stage_record.approvers.len()).unwrap_or(u32::MAX);
            let rejections_count = u32::try_from(stage_record.rejections.len()).unwrap_or(u32::MAX);
            let abstentions_count =
                u32::try_from(stage_record.abstentions.len()).unwrap_or(u32::MAX);
            let required = stage_record.required;
            (
                inserted,
                approvals_count,
                rejections_count,
                abstentions_count,
                required,
            )
        };
        if !inserted {
            return None;
        }
        if approvals.approval_gate_height.is_none()
            && parliament_approval_gate_met(&ctx.proposal_kind, &approvals, ctx.epoch)
        {
            approvals.approval_gate_height = Some(ctx.now_h);
        }
        let approvals_snapshot = approvals.clone();
        state_transaction
            .world
            .governance_stage_approvals
            .insert(ctx.rid.clone(), approvals_snapshot);
        Some(ParliamentDecisionRecord {
            approvals: approvals_count,
            rejections: rejections_count,
            abstentions: abstentions_count,
            required,
            approvals_snapshot: approvals,
        })
    }

    fn required_parliament_bodies(proposal_kind: &ProposalKind) -> &'static [ParliamentBody] {
        match proposal_kind {
            ProposalKind::DeployContract(_) => &[
                ParliamentBody::RulesCommittee,
                ParliamentBody::AgendaCouncil,
                ParliamentBody::InterestPanel,
                ParliamentBody::ReviewPanel,
                ParliamentBody::PolicyJury,
                ParliamentBody::OversightCommittee,
            ],
            ProposalKind::RuntimeUpgrade(_)
            | ProposalKind::SccpRouteGovernance(_)
            | ProposalKind::ValidationFeePolicy(_)
            | ProposalKind::ValidationFeePayoutLifecycle(_) => &[
                ParliamentBody::RulesCommittee,
                ParliamentBody::AgendaCouncil,
                ParliamentBody::InterestPanel,
                ParliamentBody::ReviewPanel,
                ParliamentBody::PolicyJury,
                ParliamentBody::OversightCommittee,
                ParliamentBody::FmaCommittee,
            ],
        }
    }

    fn parliament_approval_gate_met(
        proposal_kind: &ProposalKind,
        approvals: &crate::state::GovernanceStageApprovals,
        epoch: u64,
    ) -> bool {
        required_parliament_bodies(proposal_kind)
            .iter()
            .copied()
            .all(|body| approvals.quorum_met(body, epoch))
    }

    fn reject_proposal_by_parliament(
        ctx: &ApprovalContext,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) {
        if let Some(mut proposal) = state_transaction
            .world
            .governance_proposals
            .get(&ctx.proposal_id)
            .cloned()
        {
            if !matches!(
                proposal.status,
                crate::state::GovernanceProposalStatus::Rejected
                    | crate::state::GovernanceProposalStatus::Enacted
                    | crate::state::GovernanceProposalStatus::Superseded
            ) {
                proposal.status = crate::state::GovernanceProposalStatus::Rejected;
                state_transaction
                    .world
                    .governance_proposals
                    .insert(ctx.proposal_id, proposal);
                state_transaction
                    .world
                    .emit_events(Some(GovernanceEvent::ProposalRejected(
                        iroha_data_model::events::data::governance::GovernanceProposalRejected {
                            id: ctx.proposal_id,
                        },
                    )));
            }
        }
        if let Some(mut rec) = state_transaction
            .world
            .governance_referenda
            .get(&ctx.rid)
            .copied()
        {
            if rec.status != crate::state::GovernanceReferendumStatus::Closed {
                rec.status = crate::state::GovernanceReferendumStatus::Closed;
                state_transaction
                    .world
                    .governance_referenda
                    .insert(ctx.rid.clone(), rec);
                state_transaction
                    .world
                    .emit_events(Some(GovernanceEvent::ReferendumClosed(
                        GovernanceReferendumClosed {
                            id: ctx.rid.clone(),
                            at_height: ctx.now_h,
                        },
                    )));
            }
        }
    }

    fn approve_proposal_by_parliament(
        ctx: &ApprovalContext,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) {
        if ctx.referendum.status == crate::state::GovernanceReferendumStatus::Proposed
            && ctx.now_h >= ctx.referendum.h_start
            && ctx.now_h <= ctx.referendum.h_end
        {
            let mut rec = ctx.referendum;
            rec.status = crate::state::GovernanceReferendumStatus::Open;
            state_transaction
                .world
                .governance_referenda
                .insert(ctx.rid.clone(), rec);
            state_transaction
                .world
                .emit_events(Some(GovernanceEvent::ReferendumOpened(
                    iroha_data_model::events::data::governance::GovernanceReferendumOpened {
                        id: ctx.rid.clone(),
                        h_start: rec.h_start,
                        h_end: rec.h_end,
                    },
                )));
        }
    }

    fn maybe_apply_parliament_decision(
        body: ParliamentBody,
        ctx: &ApprovalContext,
        approvals: &crate::state::GovernanceStageApprovals,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) {
        if approvals.rejection_quorum_met(body, ctx.epoch) {
            reject_proposal_by_parliament(ctx, state_transaction);
        } else if parliament_approval_gate_met(&ctx.proposal_kind, approvals, ctx.epoch) {
            approve_proposal_by_parliament(ctx, state_transaction);
        }
    }

    // Persist council membership for an epoch.
    impl Execute for gov::PersistCouncilForEpoch {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if !has_permission(&state_transaction.world, authority, "CanManageParliament") {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanManageParliament".into(),
                ));
            }
            let required_bond =
                required_citizenship_bond_for_role(&state_transaction.gov, "council");
            let mut updated_citizens: BTreeMap<AccountId, crate::state::CitizenshipRecord> =
                BTreeMap::new();
            let citizen_cfg = &state_transaction.gov.citizen_service;
            let current_height = state_transaction._curr_block.height().get();

            ensure_unique_council_roster(&self.members, &self.alternates)?;
            if !state_transaction.gov.citizenship_bond_amount.is_zero() {
                process_council_members(
                    &self.members,
                    self.epoch,
                    &required_bond,
                    citizen_cfg,
                    current_height,
                    &mut state_transaction.world,
                    &mut updated_citizens,
                )?;
                process_council_alternates(
                    &self.alternates,
                    self.epoch,
                    &required_bond,
                    current_height,
                    &mut state_transaction.world,
                    &mut updated_citizens,
                )?;
            }
            for (account, record) in updated_citizens {
                state_transaction.world.citizens.insert(account, record);
            }
            let candidate_count =
                u32::try_from(self.members.len().saturating_add(self.alternates.len()))
                    .unwrap_or(u32::MAX);
            // This instruction is the privileged manual-roster path. Derivation metadata is
            // ledger-owned so callers cannot assert that unverified cryptographic work occurred.
            let mut rec = crate::state::CouncilState {
                epoch: self.epoch,
                members: self.members.clone(),
                alternates: self.alternates.clone(),
                candidate_count,
                derived_by: iroha_data_model::isi::governance::CouncilDerivationKind::Manual,
            };
            if let Some(existing) = state_transaction.world.council.get(&self.epoch) {
                let same_members = existing.members == self.members;
                let same_alternates = existing.alternates == self.alternates;
                if same_members && same_alternates {
                    rec = existing.clone();
                    let already_recorded = state_transaction
                        .world
                        .parliament_bodies
                        .get(&self.epoch)
                        .is_some();
                    if already_recorded {
                        return Ok(());
                    }
                } else {
                    rec.epoch = existing.epoch; // ensure consistent
                }
            }
            state_transaction
                .world
                .council
                .insert(self.epoch, rec.clone());
            // Emit event for auditability
            let members_count = u32::try_from(self.members.len()).unwrap_or(u32::MAX);
            let alternates_count = u32::try_from(self.alternates.len()).unwrap_or(u32::MAX);
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::CouncilPersisted(
                    iroha_data_model::events::data::governance::GovernanceCouncilPersisted {
                        epoch: self.epoch,
                        members_count,
                        alternates_count,
                        candidates_count: candidate_count,
                        derived_by:
                            iroha_data_model::isi::governance::CouncilDerivationKind::Manual,
                    },
                ),
            ));
            let beacon = derive_epoch_parliament_beacon(rec.epoch, state_transaction);
            let bodies = derive_parliament_bodies(
                &state_transaction.gov,
                &state_transaction.chain_id,
                rec.epoch,
                &beacon,
                &rec,
            );
            state_transaction
                .world
                .parliament_bodies
                .insert(rec.epoch, bodies.clone());
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::ParliamentSelected(
                    iroha_data_model::events::data::governance::GovernanceParliamentSelected {
                        selection_epoch: rec.epoch,
                        bodies,
                    },
                ),
            ));
            Ok(())
        }
    }

    impl Execute for gov::RegisterCitizen {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if self.owner != *authority {
                return Err(InstructionExecutionError::InvariantViolation(
                    "owner must equal authority".into(),
                ));
            }
            if self.amount < state_transaction.gov.citizenship_bond_amount {
                return Err(InstructionExecutionError::InvariantViolation(
                    "citizenship bond below minimum".into(),
                ));
            }
            let existing = state_transaction.world.citizens.get(&self.owner).cloned();
            if let Some(ref rec) = existing {
                if self.amount < rec.amount {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "citizenship bond cannot decrease".into(),
                    ));
                }
            }
            let previous_amount = existing
                .as_ref()
                .map_or_else(Quantity::zero, |rec| rec.amount.clone());
            let delta = self
                .amount
                .try_sub(&previous_amount)
                .map_err(|_| Error::from(MathError::Overflow))?;
            if !delta.is_zero() {
                let (owner_asset_id, escrow_asset_id) =
                    citizenship_asset_ids(&state_transaction.gov, &self.owner);
                let spec = state_transaction.numeric_spec_for(owner_asset_id.definition())?;
                crate::smartcontracts::isi::asset::isi::assert_numeric_spec_with(
                    delta.as_numeric(),
                    spec,
                )?;
                state_transaction
                    .world
                    .withdraw_numeric_asset(&owner_asset_id, &delta)?;
                state_transaction
                    .world
                    .deposit_numeric_asset(&escrow_asset_id, &delta)?;
            }
            let record = if let Some(mut record) = existing {
                // A top-up (including a same-amount no-op) continues the
                // original citizenship interval and must not erase service,
                // cooldown, or discipline state.
                record.amount = self.amount.clone();
                record
            } else {
                crate::state::CitizenshipRecord::new(
                    self.owner.clone(),
                    self.amount.clone(),
                    state_transaction._curr_block.height().get(),
                )
            };
            state_transaction
                .world
                .citizens
                .insert(self.owner.clone(), record.clone());
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::CitizenRegistered(
                    iroha_data_model::events::data::governance::GovernanceCitizenRegistered {
                        owner: record.owner,
                        amount: record.amount.clone(),
                    },
                ),
            ));
            #[cfg(feature = "telemetry")]
            {
                let citizens_total = u64::try_from(state_transaction.world.citizens.iter().count())
                    .unwrap_or(u64::MAX);
                state_transaction
                    .telemetry
                    .record_citizens_total(citizens_total);
            }
            Ok(())
        }
    }

    impl Execute for gov::UnregisterCitizen {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if self.owner != *authority {
                return Err(InstructionExecutionError::InvariantViolation(
                    "owner must equal authority".into(),
                ));
            }
            let Some(record) = state_transaction.world.citizens.get(&self.owner).cloned() else {
                return Err(InstructionExecutionError::InvariantViolation(
                    "citizen not found".into(),
                ));
            };
            let (owner_asset_id, escrow_asset_id) =
                citizenship_asset_ids(&state_transaction.gov, &self.owner);
            let spec = state_transaction.numeric_spec_for(owner_asset_id.definition())?;
            crate::smartcontracts::isi::asset::isi::assert_numeric_spec_with(
                record.amount.as_numeric(),
                spec,
            )?;
            state_transaction
                .world
                .withdraw_numeric_asset(&escrow_asset_id, &record.amount)?;
            state_transaction
                .world
                .deposit_numeric_asset(&owner_asset_id, &record.amount)?;
            state_transaction.world.citizens.remove(self.owner.clone());
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::CitizenRevoked(
                    iroha_data_model::events::data::governance::GovernanceCitizenRevoked {
                        owner: record.owner,
                        amount: record.amount,
                    },
                ),
            ));
            #[cfg(feature = "telemetry")]
            {
                let citizens_total = u64::try_from(state_transaction.world.citizens.iter().count())
                    .unwrap_or(u64::MAX);
                state_transaction
                    .telemetry
                    .record_citizens_total(citizens_total);
            }
            Ok(())
        }
    }

    impl Execute for gov::RecordCitizenServiceOutcome {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if self.role.trim().is_empty() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract("role must not be blank".into()),
                ));
            }
            if !has_permission(
                &state_transaction.world,
                authority,
                "CanRecordCitizenService",
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanRecordCitizenService".into(),
                ));
            }
            let Some(mut record) = state_transaction.world.citizens.get(&self.owner).cloned()
            else {
                return Err(InstructionExecutionError::InvariantViolation(
                    "citizen not found for service record".into(),
                ));
            };
            let required_bond =
                required_citizenship_bond_for_role(&state_transaction.gov, &self.role);
            if record.amount < required_bond {
                return Err(InstructionExecutionError::InvariantViolation(
                    "citizenship bond below role requirement".into(),
                ));
            }
            let citizen_cfg = state_transaction.gov.citizen_service.clone();
            let current_height = state_transaction._curr_block.height().get();
            reset_citizen_epoch(&mut record, self.epoch);
            let slashed = match self.event {
                gov::CitizenServiceEvent::Decline => {
                    let penalty = if record.declines_used >= citizen_cfg.free_declines_per_epoch {
                        slash_citizenship_bond(
                            &mut record,
                            citizen_cfg.decline_slash_bps,
                            state_transaction,
                        )?
                    } else {
                        Quantity::zero()
                    };
                    record.declines_used = record.declines_used.saturating_add(1);
                    let cooldown = current_height.saturating_add(citizen_cfg.seat_cooldown_blocks);
                    record.cooldown_until = record.cooldown_until.max(cooldown);
                    penalty
                }
                gov::CitizenServiceEvent::NoShow => {
                    record.no_show_strikes = record.no_show_strikes.saturating_add(1);
                    let cooldown = current_height.saturating_add(citizen_cfg.seat_cooldown_blocks);
                    record.cooldown_until = record.cooldown_until.max(cooldown);
                    slash_citizenship_bond(
                        &mut record,
                        citizen_cfg.no_show_slash_bps,
                        state_transaction,
                    )?
                }
                gov::CitizenServiceEvent::Misconduct => {
                    record.misconduct_strikes = record.misconduct_strikes.saturating_add(1);
                    let cooldown = current_height.saturating_add(citizen_cfg.seat_cooldown_blocks);
                    record.cooldown_until = record.cooldown_until.max(cooldown);
                    slash_citizenship_bond(
                        &mut record,
                        citizen_cfg.misconduct_slash_bps,
                        state_transaction,
                    )?
                }
            };
            state_transaction
                .world
                .citizens
                .insert(self.owner.clone(), record.clone());
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::governance::GovernanceEvent::CitizenServiceRecorded(
                    iroha_data_model::events::data::governance::GovernanceCitizenServiceRecorded {
                        owner: self.owner.clone(),
                        epoch: self.epoch,
                        role: self.role.clone(),
                        event: self.event,
                        slashed: slashed.clone(),
                        cooldown_until: record.cooldown_until,
                    },
                ),
            ));
            #[cfg(feature = "telemetry")]
            state_transaction
                .telemetry
                .record_citizen_service_event(self.event, &slashed);
            Ok(())
        }
    }

    /// Convert a plain-governance bond to the fixed integer domain used by
    /// quadratic tallying.
    ///
    /// # Errors
    ///
    /// Rejects fractional quantities and values wider than the consensus
    /// tally's `u128` domain.
    pub(crate) fn quantity_to_voting_units(amount: &Quantity) -> Result<u128, Error> {
        if amount.scale() != 0 {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "plain governance ballot amount must be an exact integer".into(),
                ),
            ));
        }
        amount.as_numeric().try_mantissa_u128().ok_or_else(|| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                "plain governance ballot amount exceeds the quadratic tally domain".into(),
            ))
            .into()
        })
    }

    /// Compute the exact quadratic-vote weight in the consensus tally domain.
    ///
    /// The conviction factor is evaluated in `u128` before it is capped so a
    /// `u64::MAX` duration cannot wrap at `1 + duration / step`.
    fn plain_ballot_weight(
        amount: &Quantity,
        duration_blocks: u64,
        conviction_step_blocks: u64,
        max_conviction: u64,
    ) -> Result<u128, Error> {
        let base = integer_sqrt_u128(quantity_to_voting_units(amount)?);
        let step = conviction_step_blocks.max(1);
        let factor = (u128::from(duration_blocks / step) + 1).min(u128::from(max_conviction));
        base.checked_mul(factor)
            .ok_or_else(|| Error::from(MathError::Overflow))
    }

    fn integer_sqrt_u128(n: u128) -> u128 {
        if n == 0 {
            return 0;
        }
        // Newton's method
        let mut x0 = n;
        let mut x1 = u128::midpoint(x0, n / x0);
        while x1 < x0 {
            x0 = x1;
            x1 = u128::midpoint(x0, n / x0);
        }
        x0
    }

    fn require_runtime_upgrade_permission(
        authority: &AccountId,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        if !has_permission(
            &state_transaction.world,
            authority,
            "CanManageRuntimeUpgrades",
        ) {
            return Err(InstructionExecutionError::InvariantViolation(
                "not permitted: CanManageRuntimeUpgrades".into(),
            ));
        }
        Ok(())
    }

    fn decode_runtime_upgrade_manifest(
        bytes: &[u8],
    ) -> Result<(iroha_data_model::runtime::RuntimeUpgradeManifest, Vec<u8>), Error> {
        let manifest: iroha_data_model::runtime::RuntimeUpgradeManifest =
            norito::decode_canonical(bytes).map_err(|e| {
                if matches!(&e, norito::Error::NonCanonicalEncoding) {
                    InstructionExecutionError::InvariantViolation(
                        "manifest bytes must use canonical Norito framing".into(),
                    )
                } else {
                    InstructionExecutionError::InvariantViolation(
                        format!("invalid manifest: {e}").into(),
                    )
                }
            })?;
        // `decode_canonical` proves these exact admission bytes are the unique V1 frame.
        // Retain them directly so ambient encode flags cannot alter the upgrade identity.
        let canonical_bytes = bytes.to_vec();
        if manifest.end_height <= manifest.start_height {
            return Err(InstructionExecutionError::InvariantViolation(
                "invalid window: end_height must be > start_height".into(),
            ));
        }
        Ok((manifest, canonical_bytes))
    }

    fn runtime_upgrade_provenance_error(
        reason: iroha_data_model::runtime::RuntimeUpgradeProvenanceError,
        _state_transaction: &StateTransaction<'_, '_>,
    ) -> Error {
        #[cfg(feature = "telemetry")]
        _state_transaction
            .telemetry
            .record_runtime_upgrade_provenance_rejection(reason);
        InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(format!(
            "runtime_upgrade_provenance:{}",
            reason.as_label()
        )))
    }

    fn verify_signature_for_signer(
        signature: &Signature,
        signer: &PublicKey,
        payload: &[u8],
    ) -> Result<(), iroha_crypto::Error> {
        match signer.try_algorithm() {
            Ok(Algorithm::Ed25519) => {
                iroha_crypto::ed25519_parse_signature(signature.payload())?;
            }
            Ok(Algorithm::MlDsa) => {
                iroha_crypto::mldsa65_parse_signature(signature.payload())?;
            }
            _ => {}
        }
        signature.verify(signer, payload)
    }

    fn validate_runtime_upgrade_provenance(
        manifest: &iroha_data_model::runtime::RuntimeUpgradeManifest,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        use iroha_data_model::runtime::RuntimeUpgradeProvenanceError;

        let policy = &state_transaction.gov.runtime_upgrade_provenance;
        let has_provenance = !(manifest.sbom_digests.is_empty()
            && manifest.slsa_attestation.is_empty()
            && manifest.provenance.is_empty());
        if policy.mode.is_required() && !has_provenance {
            return Err(runtime_upgrade_provenance_error(
                RuntimeUpgradeProvenanceError::MissingProvenance,
                state_transaction,
            ));
        }
        if !has_provenance {
            return Ok(());
        }

        if policy.require_sbom && manifest.sbom_digests.is_empty() {
            return Err(runtime_upgrade_provenance_error(
                RuntimeUpgradeProvenanceError::MissingSbom,
                state_transaction,
            ));
        }
        for entry in &manifest.sbom_digests {
            if entry.algorithm.trim().is_empty() || entry.digest.is_empty() {
                return Err(runtime_upgrade_provenance_error(
                    RuntimeUpgradeProvenanceError::InvalidSbomDigest,
                    state_transaction,
                ));
            }
        }
        if policy.require_slsa && manifest.slsa_attestation.is_empty() {
            return Err(runtime_upgrade_provenance_error(
                RuntimeUpgradeProvenanceError::MissingSlsaAttestation,
                state_transaction,
            ));
        }

        if policy.signature_threshold > 0 && manifest.provenance.is_empty() {
            return Err(runtime_upgrade_provenance_error(
                RuntimeUpgradeProvenanceError::MissingSignatures,
                state_transaction,
            ));
        }
        if !manifest.provenance.is_empty() {
            let payload = manifest.signature_payload_bytes();
            let mut trusted_signers = BTreeSet::new();
            for provenance in &manifest.provenance {
                verify_signature_for_signer(&provenance.signature, &provenance.signer, &payload)
                    .map_err(|_| {
                        runtime_upgrade_provenance_error(
                            RuntimeUpgradeProvenanceError::InvalidSignature,
                            state_transaction,
                        )
                    })?;
                if !policy.trusted_signers.is_empty()
                    && !policy.trusted_signers.contains(&provenance.signer)
                {
                    return Err(runtime_upgrade_provenance_error(
                        RuntimeUpgradeProvenanceError::UntrustedSigner,
                        state_transaction,
                    ));
                }
                if policy.trusted_signers.contains(&provenance.signer) {
                    trusted_signers.insert(provenance.signer.clone());
                }
            }
            if policy.signature_threshold > 0 && trusted_signers.len() < policy.signature_threshold
            {
                return Err(runtime_upgrade_provenance_error(
                    RuntimeUpgradeProvenanceError::SignatureThresholdNotMet,
                    state_transaction,
                ));
            }
        }

        Ok(())
    }

    fn policy_for_abi_version(
        abi_version: u16,
    ) -> Result<(ivm::SyscallPolicy, u8), InstructionExecutionError> {
        if abi_version != 1 {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("unsupported abi_version {abi_version}; expected 1").into(),
            ));
        }
        Ok((ivm::SyscallPolicy::AbiV1, 1))
    }

    fn allowed_syscalls_for_policy(policy: ivm::SyscallPolicy) -> BTreeSet<u32> {
        ivm::syscalls::syscalls_for_policy(policy)
            .iter()
            .copied()
            .collect()
    }

    fn allowed_pointer_types_for_policy(policy: ivm::SyscallPolicy) -> BTreeSet<ivm::PointerType> {
        ivm::pointer_abi::policy_pointer_types(policy)
            .iter()
            .copied()
            .collect()
    }

    fn latest_active_abi_version(state_transaction: &StateTransaction<'_, '_>) -> u16 {
        state_transaction
            .world
            .runtime_upgrades
            .iter()
            .filter_map(|(_, rec)| match rec.status {
                iroha_data_model::runtime::RuntimeUpgradeStatus::ActivatedAt(_) => {
                    Some(rec.manifest.abi_version)
                }
                _ => None,
            })
            .max()
            .unwrap_or(1)
    }

    fn validate_runtime_upgrade_surface(
        manifest: &iroha_data_model::runtime::RuntimeUpgradeManifest,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let (policy, _) = policy_for_abi_version(manifest.abi_version)?;
        let computed = ivm::syscalls::compute_abi_hash(policy);
        if manifest.abi_hash != computed {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("abi_hash mismatch for abi_version {}", manifest.abi_version).into(),
            ));
        }

        let previous = latest_active_abi_version(state_transaction);
        let (prev_policy, _) = policy_for_abi_version(previous)?;
        let prev_syscalls = allowed_syscalls_for_policy(prev_policy);
        let new_syscalls = allowed_syscalls_for_policy(policy);
        if !new_syscalls.is_superset(&prev_syscalls) {
            return Err(InstructionExecutionError::InvariantViolation(
                "syscall surface must be additive".into(),
            ));
        }
        let expected_syscall_delta: BTreeSet<u32> =
            new_syscalls.difference(&prev_syscalls).copied().collect();
        let manifest_syscalls: BTreeSet<u32> = manifest
            .added_syscalls
            .iter()
            .copied()
            .map(u32::from)
            .collect();
        if expected_syscall_delta != manifest_syscalls {
            return Err(InstructionExecutionError::InvariantViolation(
                "added_syscalls must list exactly the new syscall numbers".into(),
            ));
        }

        let prev_ptrs = allowed_pointer_types_for_policy(prev_policy);
        let new_ptrs = allowed_pointer_types_for_policy(policy);
        if !new_ptrs.is_superset(&prev_ptrs) {
            return Err(InstructionExecutionError::InvariantViolation(
                "pointer-type surface must be additive".into(),
            ));
        }
        let expected_ptr_delta: BTreeSet<u16> = new_ptrs
            .difference(&prev_ptrs)
            .map(|ty| *ty as u16)
            .collect();
        let manifest_ptrs: BTreeSet<u16> = manifest.added_pointer_types.iter().copied().collect();
        if expected_ptr_delta != manifest_ptrs {
            return Err(InstructionExecutionError::InvariantViolation(
                "added_pointer_types must list exactly the new pointer-type identifiers".into(),
            ));
        }

        Ok(())
    }

    fn ensure_runtime_upgrade_abi_version(
        manifest: &iroha_data_model::runtime::RuntimeUpgradeManifest,
        _state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        // Runtime upgrades in the first release keep ABI v1 fixed; no version bumping is allowed.
        policy_for_abi_version(manifest.abi_version)?;
        Ok(())
    }

    fn ensure_runtime_upgrade_no_overlap(
        manifest: &iroha_data_model::runtime::RuntimeUpgradeManifest,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let new_start = manifest.start_height;
        let new_end = manifest.end_height;
        for (_id, rec) in state_transaction.world.runtime_upgrades.iter() {
            if matches!(
                rec.status,
                iroha_data_model::runtime::RuntimeUpgradeStatus::Proposed
                    | iroha_data_model::runtime::RuntimeUpgradeStatus::ActivatedAt(_)
            ) {
                let s = rec.manifest.start_height;
                let e = rec.manifest.end_height;
                if new_start < e && s < new_end {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "runtime upgrade window overlaps existing proposal/activation".into(),
                    ));
                }
            }
        }
        Ok(())
    }

    fn handle_existing_runtime_upgrade(
        id: iroha_data_model::runtime::RuntimeUpgradeId,
        manifest: &iroha_data_model::runtime::RuntimeUpgradeManifest,
        authority: &AccountId,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<bool, Error> {
        if let Some(existing) = state_transaction.world.runtime_upgrades.get(&id) {
            if existing.manifest == *manifest
                && matches!(
                    existing.status,
                    iroha_data_model::runtime::RuntimeUpgradeStatus::Proposed
                )
                && existing.proposer == *authority
            {
                return Ok(true);
            }
            return Err(InstructionExecutionError::InvariantViolation(
                "runtime upgrade already proposed".into(),
            ));
        }
        Ok(false)
    }

    fn validate_verifying_key_update(
        id: &VerifyingKeyId,
        new: &VerifyingKeyRecord,
        old: &VerifyingKeyRecord,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        if matches!(old.status, ConfidentialStatus::Withdrawn) {
            return Err(InstructionExecutionError::InvariantViolation(
                "cannot update withdrawn verifying key".into(),
            ));
        }
        if new.version <= old.version {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key version must increase".into(),
            ));
        }
        if new.backend != old.backend {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key backend cannot change".into(),
            ));
        }
        if new.circuit_id != old.circuit_id {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key circuit_id cannot change; register a distinct key id for a new circuit"
                    .into(),
            ));
        }
        let id_backend = id.backend.as_str();
        ensure_open_verify_circuit_id_is_admitted_v1(id_backend, &new.circuit_id)?;
        match new.backend {
            BackendTag::Halo2IpaPasta => {
                if new.curve != "pallas" {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "verifying key curve must be \"pallas\"".into(),
                        ),
                    ));
                }
                ensure_production_verifying_key_backend_id(id_backend)?;
                if !is_no_trusted_setup_halo2_backend_id(id_backend) {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "verifying key id backend must target no-trusted-setup Halo2 IPA"
                                .into(),
                        ),
                    ));
                }
            }
            BackendTag::Stark => {
                if new.curve != "goldilocks" {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "verifying key curve must be \"goldilocks\"".into(),
                        ),
                    ));
                }
                ensure_production_verifying_key_backend_id(id_backend)?;
                if !crate::zk::is_stark_fri_v1_backend(id_backend) {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "verifying key id backend must target stark/fri".into(),
                        ),
                    ));
                }
            }
        }
        if let Some(vk) = &new.key {
            if new.commitment != hash_vk(vk) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "verifying key commitment mismatch".into(),
                ));
            }
            if vk.backend != id.backend {
                return Err(InstructionExecutionError::InvariantViolation(
                    "vk backend does not match id backend".into(),
                ));
            }
            if u32::try_from(vk.bytes.len()).ok() != Some(new.vk_len) {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verifying key vk_len must match inline key bytes length".into(),
                    ),
                ));
            }
            if new.backend == BackendTag::Stark {
                #[cfg(not(feature = "zk-stark"))]
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "verifying key backend Stark is not enabled".into(),
                        ),
                    ));
                }

                #[cfg(feature = "zk-stark")]
                {
                    use crate::zk_stark::{
                        STARK_HASH_POSEIDON2_V1, STARK_HASH_SHA256_V1, StarkFriVerifyingKeyV1,
                    };
                    let expected_hash_fn = if id_backend == crate::zk::ZK_BACKEND_STARK_FRI_V1 {
                        None
                    } else if id_backend.contains("/sha256-") {
                        Some(STARK_HASH_SHA256_V1)
                    } else if id_backend.contains("/poseidon2-") {
                        Some(STARK_HASH_POSEIDON2_V1)
                    } else {
                        return Err(InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "unsupported stark/fri backend variant".into(),
                            ),
                        ));
                    };
                    let payload: StarkFriVerifyingKeyV1 = norito::decode_canonical(&vk.bytes)
                        .map_err(|_| {
                            InstructionExecutionError::InvalidParameter(
                                InvalidParameterError::SmartContract(
                                    "invalid STARK verifying key payload".into(),
                                ),
                            )
                        })?;
                    if payload.version != 1 {
                        return Err(InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "unsupported STARK verifying key payload version".into(),
                            ),
                        ));
                    }
                    if payload.hash_fn != STARK_HASH_SHA256_V1
                        && payload.hash_fn != STARK_HASH_POSEIDON2_V1
                    {
                        return Err(InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "unsupported STARK verifying key hash_fn".into(),
                            ),
                        ));
                    }
                    if let Some(expected_hash_fn) = expected_hash_fn {
                        if payload.hash_fn != expected_hash_fn {
                            return Err(InstructionExecutionError::InvalidParameter(
                                InvalidParameterError::SmartContract(
                                    "STARK verifying key hash_fn mismatch".into(),
                                ),
                            ));
                        }
                    }
                    let payload_circuit_id =
                        normalize_stark_fri_circuit_id(id_backend, &payload.circuit_id)
                            .ok_or_else(|| {
                                InstructionExecutionError::InvalidParameter(
                                    InvalidParameterError::SmartContract(
                                        "invalid STARK verifying key circuit_id".into(),
                                    ),
                                )
                            })?;
                    let record_circuit_id =
                        normalize_stark_fri_circuit_id(id_backend, &new.circuit_id).ok_or_else(
                            || {
                                InstructionExecutionError::InvalidParameter(
                                    InvalidParameterError::SmartContract(
                                        "invalid verifying key record circuit_id".into(),
                                    ),
                                )
                            },
                        )?;
                    if payload_circuit_id != record_circuit_id {
                        return Err(InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "STARK verifying key circuit_id does not match record".into(),
                            ),
                        ));
                    }
                }
            }
        }
        let new_key = (new.circuit_id.clone(), new.version);
        if let Some(existing) = state_transaction
            .world
            .verifying_keys_by_circuit
            .get(&new_key)
        {
            if existing != id {
                return Err(InstructionExecutionError::InvariantViolation(
                    "verifying key circuit/version already registered".into(),
                ));
            }
        }
        if new.circuit_id.trim().is_empty() {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "verifying key circuit_id must not be empty".into(),
                ),
            ));
        }
        if new.public_inputs_schema_hash == [0u8; 32] {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "verifying key public_inputs_schema_hash must be set".into(),
                ),
            ));
        }
        if new.gas_schedule_id.is_none() {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "verifying key gas_schedule_id must be set".into(),
                ),
            ));
        }
        validate_soracloud_fhe_stark_verifying_key_records(id, new)?;
        Ok(())
    }

    // Runtime Upgrade Governance — minimal implementation (see specs/runtime_upgrades.md)
    impl Execute for runtime_upgrade::ProposeRuntimeUpgrade {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            require_runtime_upgrade_permission(authority, state_transaction)?;
            let (manifest, canonical_bytes) =
                decode_runtime_upgrade_manifest(self.manifest_bytes())?;
            let id =
                iroha_data_model::runtime::RuntimeUpgradeId::from_manifest_bytes(&canonical_bytes);
            if handle_existing_runtime_upgrade(id, &manifest, authority, state_transaction)? {
                return Ok(());
            }
            validate_runtime_upgrade_provenance(&manifest, state_transaction)?;
            ensure_runtime_upgrade_abi_version(&manifest, state_transaction)?;
            validate_runtime_upgrade_surface(&manifest, state_transaction)?;
            ensure_runtime_upgrade_no_overlap(&manifest, state_transaction)?;
            let created_height = state_transaction._curr_block.height().get();
            let record = iroha_data_model::runtime::RuntimeUpgradeRecord {
                manifest: manifest.clone(),
                status: iroha_data_model::runtime::RuntimeUpgradeStatus::Proposed,
                proposer: authority.clone(),
                created_height,
            };
            state_transaction.world.runtime_upgrades.insert(id, record);
            // Emit Proposed event
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeEvent::Proposed(
                    iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeProposed {
                        id,
                        abi_version: manifest.abi_version,
                        start_height: manifest.start_height,
                        end_height: manifest.end_height,
                    },
                ),
            ));
            #[cfg(feature = "telemetry")]
            {
                state_transaction
                    .telemetry
                    .inc_runtime_upgrade_event("proposed");
            }
            Ok(())
        }
    }

    impl Execute for runtime_upgrade::ActivateRuntimeUpgrade {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if !has_permission(
                &state_transaction.world,
                authority,
                "CanManageRuntimeUpgrades",
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanManageRuntimeUpgrades".into(),
                ));
            }
            let id = *self.id();
            let Some(rec) = state_transaction.world.runtime_upgrades.get(&id).cloned() else {
                return Err(FindError::Permission(Box::new(Permission::new(
                    "RuntimeUpgradeNotFound".into(),
                    iroha_primitives::json::Json::from("id"),
                )))
                .into());
            };
            validate_runtime_upgrade_provenance(&rec.manifest, state_transaction)?;
            validate_runtime_upgrade_surface(&rec.manifest, state_transaction)?;
            let h = state_transaction._curr_block.height().get();
            match rec.status {
                iroha_data_model::runtime::RuntimeUpgradeStatus::Proposed => {
                    if h != rec.manifest.start_height || h >= rec.manifest.end_height {
                        return Err(InstructionExecutionError::InvariantViolation(
                            "activation height is outside of the scheduled window".into(),
                        ));
                    }
                    // Flip to ActivatedAt(h)
                    let mut new_rec = rec.clone();
                    new_rec.status =
                        iroha_data_model::runtime::RuntimeUpgradeStatus::ActivatedAt(h);
                    state_transaction.world.runtime_upgrades.insert(id, new_rec);
                    // Emit Activated event
                    state_transaction.world.emit_events(Some(
                        iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeEvent::Activated(
                            iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeActivated {
                                id,
                                abi_version: rec.manifest.abi_version,
                                at_height: h,
                            },
                        ),
                    ));
                    #[cfg(feature = "telemetry")]
                    {
                        state_transaction
                            .telemetry
                            .inc_runtime_upgrade_event("activated");
                    }
                    Ok(())
                }
                iroha_data_model::runtime::RuntimeUpgradeStatus::ActivatedAt(prev) if prev == h => {
                    // Idempotent replay: already activated at this height.
                    Ok(())
                }
                iroha_data_model::runtime::RuntimeUpgradeStatus::ActivatedAt(prev) => {
                    Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot activate: already activated at height {prev}, current block {h}"
                        )
                        .into(),
                    ))
                }
                _ => Err(InstructionExecutionError::InvariantViolation(
                    "cannot activate: status is not Proposed".into(),
                )),
            }
        }
    }

    impl Execute for runtime_upgrade::CancelRuntimeUpgrade {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if !has_permission(
                &state_transaction.world,
                authority,
                "CanManageRuntimeUpgrades",
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanManageRuntimeUpgrades".into(),
                ));
            }
            let id = *self.id();
            let Some(rec) = state_transaction.world.runtime_upgrades.get(&id).cloned() else {
                return Err(FindError::Permission(Box::new(Permission::new(
                    "RuntimeUpgradeNotFound".into(),
                    iroha_primitives::json::Json::from("id"),
                )))
                .into());
            };
            if !matches!(
                rec.status,
                iroha_data_model::runtime::RuntimeUpgradeStatus::Proposed
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "cannot cancel: status is not Proposed".into(),
                ));
            }
            let h = state_transaction._curr_block.height().get();
            if h >= rec.manifest.start_height {
                return Err(InstructionExecutionError::InvariantViolation(
                    "cannot cancel at/after start_height".into(),
                ));
            }
            // Flip to Canceled
            let mut new_rec = rec.clone();
            new_rec.status = iroha_data_model::runtime::RuntimeUpgradeStatus::Canceled;
            state_transaction.world.runtime_upgrades.insert(id, new_rec);
            // Emit Canceled event
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeEvent::Canceled(
                    iroha_data_model::events::data::runtime_upgrade::RuntimeUpgradeCanceled { id },
                ),
            ));
            #[cfg(feature = "telemetry")]
            {
                state_transaction
                    .telemetry
                    .inc_runtime_upgrade_event("canceled");
            }
            Ok(())
        }
    }

    impl Execute for verifying_keys::UpdateVerifyingKey {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if !can_manage_verifying_keys(&state_transaction.world, authority) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanManageVerifyingKeys".into(),
                ));
            }
            let id = self.id().clone();
            let new = self.record().clone();
            let Some(old) = state_transaction.world.verifying_keys.get(&id).cloned() else {
                return Err(FindError::Permission(Box::new(Permission::new(
                    "VerifyingKeyMissing".into(),
                    iroha_primitives::json::Json::from(
                        format!("{}::{}", id.backend, id.name).as_str(),
                    ),
                )))
                .into());
            };
            validate_verifying_key_update(&id, &new, &old, state_transaction)?;
            let new_key = (new.circuit_id.clone(), new.version);
            let old_key = (old.circuit_id.clone(), old.version);
            state_transaction.world.verifying_keys.remove(id.clone());
            state_transaction
                .world
                .verifying_keys
                .insert(id.clone(), new.clone());
            state_transaction
                .world
                .verifying_keys_by_circuit
                .remove(old_key);
            state_transaction
                .world
                .verifying_keys_by_circuit
                .insert(new_key, id.clone());
            // Emit verifying key updated event
            state_transaction.world.emit_events(Some(
                iroha_data_model::events::data::verifying_keys::VerifyingKeyEvent::Updated(
                    iroha_data_model::events::data::verifying_keys::VerifyingKeyUpdated {
                        id: id.clone(),
                        record: new.clone(),
                    },
                ),
            ));
            Ok(())
        }
    }

    impl Execute for consensus_keys::RegisterConsensusKey {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_can_manage_consensus_keys(authority, state_transaction)?;

            let id = self.id().clone();
            let params = state_transaction.world.parameters.get();
            let block_height = state_transaction.block_height();
            let record = prepare_consensus_key_registration(
                &id,
                self.record().clone(),
                block_height,
                state_transaction,
            )?;
            validate_consensus_key_record(
                &record,
                &params.sumeragi,
                None,
                block_height,
                state_transaction._curr_block.is_genesis(),
            )?;
            commit_consensus_key_registration(state_transaction, &id, record);
            Ok(())
        }
    }

    fn ensure_can_manage_consensus_keys(
        authority: &AccountId,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        if has_permission(
            &state_transaction.world,
            authority,
            "CanManageConsensusKeys",
        ) {
            Ok(())
        } else {
            Err(InstructionExecutionError::InvariantViolation(
                "not permitted: CanManageConsensusKeys".into(),
            ))
        }
    }

    fn prepare_consensus_key_registration(
        id: &ConsensusKeyId,
        mut record: ConsensusKeyRecord,
        block_height: u64,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<ConsensusKeyRecord, Error> {
        if &record.id != id {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "consensus key id mismatch between instruction and record".into(),
                ),
            ));
        }
        if state_transaction.world.consensus_keys.get(id).is_some() {
            return Err(RepetitionError {
                instruction: InstructionType::Register,
                id: IdBox::Permission(Permission::new(
                    "ConsensusKey".into(),
                    iroha_primitives::json::Json::from(id.to_string().as_str()),
                )),
            }
            .into());
        }
        record.status = if record.activation_height > block_height {
            ConsensusKeyStatus::Pending
        } else {
            ConsensusKeyStatus::Active
        };
        Ok(record)
    }

    fn commit_consensus_key_registration(
        state_transaction: &mut StateTransaction<'_, '_>,
        id: &ConsensusKeyId,
        record: ConsensusKeyRecord,
    ) {
        let lifecycle_record = record.clone();
        let log_id = id.clone();
        let log_record = lifecycle_record.clone();
        upsert_consensus_key(&mut state_transaction.world, id, record);
        crate::sumeragi::status::record_consensus_key(lifecycle_record);
        iroha_logger::info!(
            key = %log_id,
            activation = log_record.activation_height,
            expiry = ?log_record.expiry_height,
            "registered consensus key"
        );
    }

    fn load_prev_record_for_rotation(
        new_record: &ConsensusKeyRecord,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(ConsensusKeyId, ConsensusKeyRecord), Error> {
        let Some(prev_id) = new_record.replaces.clone() else {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "rotation must reference the key being replaced".into(),
                ),
            ));
        };
        let Some(prev_record) = state_transaction
            .world
            .consensus_keys
            .get(&prev_id)
            .cloned()
        else {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "referenced key not found for rotation".into(),
                ),
            ));
        };
        Ok((prev_id, prev_record))
    }

    fn validate_rotation_pair(
        new_record: &ConsensusKeyRecord,
        prev_record: &ConsensusKeyRecord,
    ) -> Result<(), Error> {
        if new_record.id.role != prev_record.id.role {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "replacement consensus key must preserve the role".into(),
                ),
            ));
        }
        if matches!(prev_record.status, ConsensusKeyStatus::Disabled) {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract("cannot rotate from a disabled key".into()),
            ));
        }
        Ok(())
    }

    fn enforce_rotation_overlap(
        prev_record: &mut ConsensusKeyRecord,
        new_record: &ConsensusKeyRecord,
        overlap: u64,
    ) -> Result<(), Error> {
        if let Some(expiry) = prev_record.expiry_height {
            if new_record.activation_height > expiry.saturating_add(overlap) {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "replacement consensus key activation exceeds overlap window".into(),
                    ),
                ));
            }
        } else {
            let retire_at = new_record.activation_height.saturating_add(overlap);
            prev_record.expiry_height = Some(retire_at);
        }
        Ok(())
    }

    fn ensure_rotation_target_unique(
        state_transaction: &StateTransaction<'_, '_>,
        new_id: &ConsensusKeyId,
    ) -> Result<(), Error> {
        if state_transaction.world.consensus_keys.get(new_id).is_some() {
            return Err(RepetitionError {
                instruction: InstructionType::Register,
                id: IdBox::Permission(Permission::new(
                    "ConsensusKey".into(),
                    iroha_primitives::json::Json::from(new_id.to_string().as_str()),
                )),
            }
            .into());
        }
        Ok(())
    }

    fn apply_consensus_key_rotation(
        state_transaction: &mut StateTransaction<'_, '_>,
        new_id: &ConsensusKeyId,
        mut new_record: ConsensusKeyRecord,
        prev_id: ConsensusKeyId,
        mut prev_record: ConsensusKeyRecord,
        block_height: u64,
    ) {
        prev_record.status = ConsensusKeyStatus::Retiring;
        let log_prev = prev_id.clone();
        crate::sumeragi::status::record_consensus_key(prev_record.clone());
        state_transaction
            .world
            .consensus_keys
            .insert(prev_id, prev_record);

        new_record.status = if new_record.activation_height > block_height {
            ConsensusKeyStatus::Pending
        } else {
            ConsensusKeyStatus::Active
        };
        let lifecycle_record = new_record.clone();
        let log_new = new_id.clone();
        let log_record = lifecycle_record.clone();
        upsert_consensus_key(&mut state_transaction.world, new_id, new_record);
        crate::sumeragi::status::record_consensus_key(lifecycle_record);
        iroha_logger::info!(
            replaced = %log_prev,
            key = %log_new,
            activation = log_record.activation_height,
            expiry = ?log_record.expiry_height,
            "rotated consensus key"
        );
    }

    impl Execute for consensus_keys::RotateConsensusKey {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_can_manage_consensus_keys(authority, state_transaction)?;
            let new_id = self.id().clone();
            let new_record = self.record().clone();
            let params = state_transaction.world.parameters.get();
            let block_height = state_transaction.block_height();
            if new_record.id != new_id {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "consensus key id mismatch between instruction and record".into(),
                    ),
                ));
            }
            let (prev_id, mut prev_record) =
                load_prev_record_for_rotation(&new_record, state_transaction)?;

            validate_consensus_key_record(
                &new_record,
                &params.sumeragi,
                Some(&prev_id),
                block_height,
                false,
            )?;
            validate_rotation_pair(&new_record, &prev_record)?;
            enforce_rotation_overlap(
                &mut prev_record,
                &new_record,
                params.sumeragi.key_overlap_grace_blocks,
            )?;
            ensure_rotation_target_unique(state_transaction, &new_id)?;
            apply_consensus_key_rotation(
                state_transaction,
                &new_id,
                new_record,
                prev_id,
                prev_record,
                block_height,
            );
            Ok(())
        }
    }

    impl Execute for consensus_keys::DisableConsensusKey {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if !has_permission(
                &state_transaction.world,
                authority,
                "CanManageConsensusKeys",
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanManageConsensusKeys".into(),
                ));
            }

            let id = self.id().clone();
            let Some(mut record) = state_transaction.world.consensus_keys.get(&id).cloned() else {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract("consensus key not found".into()),
                ));
            };

            record.status = ConsensusKeyStatus::Disabled;
            record
                .expiry_height
                .get_or_insert_with(|| state_transaction.block_height());
            let pk = record.public_key.to_string();
            state_transaction
                .world
                .consensus_keys
                .insert(id.clone(), record);
            if let Some(updated) = state_transaction.world.consensus_keys.get(&id).cloned() {
                crate::sumeragi::status::record_consensus_key(updated);
            }
            let mut by_pk = state_transaction
                .world
                .consensus_keys_by_pk
                .get(&pk)
                .cloned()
                .unwrap_or_default();
            if !by_pk.contains(&id) {
                by_pk.push(id.clone());
                state_transaction
                    .world
                    .consensus_keys_by_pk
                    .insert(pk, by_pk);
            }
            iroha_logger::info!(
                key = %id,
                expiry = ?state_transaction
                    .world
                    .consensus_keys
                    .get(&id)
                    .and_then(|rec| rec.expiry_height),
                "disabled consensus key"
            );
            Ok(())
        }
    }

    impl Execute for confidential::PublishPedersenParams {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if !has_permission(
                &state_transaction.world,
                authority,
                "CanManageConfidentialParams",
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanManageConfidentialParams".into(),
                ));
            }

            let params = self.params().clone();
            let id = params.params_id;
            if state_transaction.world.pedersen_params.get(&id).is_some() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "pedersen parameter set already exists".into(),
                ));
            }
            if matches!(params.status, ConfidentialStatus::Withdrawn) {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "cannot publish pedersen params with Withdrawn status".into(),
                    ),
                ));
            }
            state_transaction.world.pedersen_params.insert(id, params);
            Ok(())
        }
    }

    impl Execute for confidential::SetPedersenParamsLifecycle {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if !has_permission(
                &state_transaction.world,
                authority,
                "CanManageConfidentialParams",
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanManageConfidentialParams".into(),
                ));
            }

            let id = self.params_id();
            let Some(mut current) = state_transaction.world.pedersen_params.get(id).cloned() else {
                return Err(FindError::Permission(Box::new(Permission::new(
                    "PedersenParamsMissing".into(),
                    iroha_primitives::json::Json::from(format!("{id}").as_str()),
                )))
                .into());
            };
            if matches!(current.status, ConfidentialStatus::Withdrawn) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "cannot update withdrawn pedersen params".into(),
                ));
            }
            current.status = *self.status();
            current.activation_height = *self.activation_height();
            current.withdraw_height = *self.withdraw_height();

            state_transaction.world.pedersen_params.remove(*id);
            state_transaction.world.pedersen_params.insert(*id, current);
            Ok(())
        }
    }

