        #[test]
        fn decode_open_verify_envelope_accepts_stark_backend() {
            let envelope = OpenVerifyEnvelope::new(
                BackendTag::Stark,
                "stark/fri/sha256-goldilocks:dummy-circuit",
                [0u8; 32],
                vec![1, 2, 3],
                vec![4, 5, 6],
            );
            let bytes = norito::to_bytes(&envelope).expect("encode OpenVerifyEnvelope");
            let proof_box = ProofBox::new("stark/fri/sha256-goldilocks".into(), bytes.clone());
            let decoded = decode_open_verify_envelope(&proof_box).expect("decode");
            assert_eq!(decoded.backend, BackendTag::Stark);
            assert_eq!(decoded.circuit_id, envelope.circuit_id);
            assert_eq!(decoded.public_inputs, envelope.public_inputs);
            assert_eq!(decoded.proof_bytes, envelope.proof_bytes);
        }

        #[test]
        fn decode_open_verify_envelope_skips_non_production_backend_labels() {
            let envelope = OpenVerifyEnvelope::new(
                BackendTag::Halo2IpaPasta,
                "halo2/ipa:tiny-add",
                [0u8; 32],
                vec![1, 2, 3],
                vec![4, 5, 6],
            );
            let bytes = norito::to_bytes(&envelope).expect("encode OpenVerifyEnvelope");
            for backend in [
                " halo2/ipa",
                "halo2/ipa ",
                "halo2/ipa\n",
                "halo2/ipa\0",
                "../halo2/ipa",
                "halo2/ipa/../tiny-add",
                "halo2/ipa/orchard",
                "halo2/unknown-native-v1",
                "halo2/ipa: KZG",
                "halo2/ipa:Mock-Proof",
                " stark/fri/sha256-goldilocks",
                "stark/fri/sha256-goldilocks ",
                "stark/fri/sha256-goldilocks\0",
                "../stark/fri",
                "stark/fri/miden",
            ] {
                let proof_box = ProofBox::new(backend.into(), bytes.clone());
                assert!(
                    decode_open_verify_envelope(&proof_box).is_none(),
                    "non-registry backend {backend} must not be decoded before validation"
                );
            }
        }

        #[test]
        fn open_verify_backend_tag_matches_rejects_cross_family_tags() {
            assert!(open_verify_backend_tag_matches(
                "halo2/ipa",
                BackendTag::Halo2IpaPasta
            ));
            assert!(backend_requires_open_verify_envelope("halo2/ipa"));
            assert!(!open_verify_backend_tag_matches(
                "halo2/bn254",
                BackendTag::Halo2IpaPasta
            ));
            assert!(!open_verify_backend_tag_matches(
                "halo2/kzg",
                BackendTag::Halo2IpaPasta
            ));
            assert!(open_verify_backend_tag_matches(
                "stark/fri/sha256-goldilocks",
                BackendTag::Stark
            ));
            assert!(backend_requires_open_verify_envelope(
                "stark/fri/sha256-goldilocks"
            ));
            assert!(backend_requires_open_verify_envelope(
                "stark/fri/poseidon2-goldilocks"
            ));
            assert!(backend_requires_open_verify_envelope(
                "stark/fri/sha256_goldilocks.v1"
            ));
            assert!(!open_verify_backend_tag_matches(
                "stark/fri/sha256-goldilocks",
                BackendTag::Halo2IpaPasta
            ));
            assert!(!open_verify_backend_tag_matches(
                "halo2/unknown-native-v1",
                BackendTag::Halo2IpaPasta
            ));
            assert!(!open_verify_backend_tag_matches(
                "unknown/privacy/backend",
                BackendTag::Halo2IpaPasta
            ));
            for rejected_backend in [
                "halo2/bn254",
                "halo2/kzg",
                "halo2/debug",
                "halo2/mock",
                "halo2/unknown-native-v1",
                "halo2/ipa:production-ready",
                "stark/fri/random-profile",
                "stark/fri/security-review-passed",
                "unknown/privacy/backend",
            ] {
                assert!(
                    !backend_requires_open_verify_envelope(rejected_backend),
                    "{rejected_backend} must not be treated as an admitted enveloped backend"
                );
            }
            for protocol_name in [
                "halo2-ipa-orchard",
                "groth16-bls12-377",
                "fcmp-plus-plus-curve-tree",
                "lattice-pcs-sis",
                "miden-stark",
                "aztec-plonkish-private-kernel",
                "pq-masp-stark-fri",
                "anonymous-pgc",
                "verange",
                "zkat",
                "zk-ams",
                "vega-existing-credential-zk",
                "silent-threshold-anoncred",
                "zk-x509",
                "sis-hints-anoncred-pq-v0",
                "sis-with-hints",
            ] {
                assert!(
                    !open_verify_backend_tag_matches(protocol_name, BackendTag::Halo2IpaPasta),
                    "{protocol_name} must stay fail-closed against Halo2 envelopes"
                );
                assert!(
                    !open_verify_backend_tag_matches(protocol_name, BackendTag::Stark),
                    "{protocol_name} must stay fail-closed against STARK envelopes"
                );
            }
        }

        #[test]
        fn validate_proof_attachment_rejects_mismatched_attachment_triples() {
            let envelope = OpenVerifyEnvelope::new(
                BackendTag::Halo2IpaPasta,
                "halo2/ipa:tiny-add",
                [0u8; 32],
                Vec::new(),
                vec![1, 2, 3],
            );
            let proof = ProofBox::new(
                "halo2/ipa".into(),
                norito::to_bytes(&envelope).expect("encode envelope"),
            );
            let valid = ProofAttachment::new_ref(
                "halo2/ipa".into(),
                proof.clone(),
                VerifyingKeyId::new("halo2/ipa", "vk"),
            );
            assert!(
                validate_proof_attachment(&valid, &proof, true, Some(&envelope)).is_ok(),
                "well-formed attachment triple should pass validation"
            );

            let wrong_outer_backend = ProofAttachment::new_ref(
                "stark/fri".into(),
                proof.clone(),
                VerifyingKeyId::new("stark/fri", "vk"),
            );
            let err =
                validate_proof_attachment(&wrong_outer_backend, &proof, true, Some(&envelope))
                    .expect_err("outer attachment backend must match proof backend");
            assert!(
                smart_contract_instruction_error_message(err).contains("proof backend mismatch")
            );

            let wrong_vk_backend = ProofAttachment::new_ref(
                "halo2/ipa".into(),
                proof.clone(),
                VerifyingKeyId::new("stark/fri", "vk"),
            );
            let err = validate_proof_attachment(&wrong_vk_backend, &proof, true, Some(&envelope))
                .expect_err("vk_ref backend must match attachment backend");
            assert!(
                smart_contract_instruction_error_message(err)
                    .contains("verifying key backend mismatch")
            );

            let err = validate_proof_attachment(&valid, &proof, true, None)
                .expect_err("enveloped backends must carry an OpenVerifyEnvelope");
            let msg = smart_contract_instruction_error_message(err);
            assert!(
                msg.contains("OpenVerifyEnvelope"),
                "unexpected error: {msg}"
            );

            let trusted_setup_proof = ProofBox::new(
                "halo2/kzg".into(),
                norito::to_bytes(&envelope).expect("encode envelope"),
            );
            let trusted_setup_attachment = ProofAttachment::new_ref(
                "halo2/kzg".into(),
                trusted_setup_proof.clone(),
                VerifyingKeyId::new("halo2/kzg", "vk"),
            );
            let err = validate_proof_attachment(
                &trusted_setup_attachment,
                &trusted_setup_proof,
                true,
                Some(&envelope),
            )
            .expect_err("trusted-setup attachment backend must fail before envelope use");
            let msg = smart_contract_instruction_error_message(err);
            assert!(msg.contains("trusted-setup"), "unexpected error: {msg}");

            let developer_only_proof = ProofBox::new(
                "halo2/mock".into(),
                norito::to_bytes(&envelope).expect("encode envelope"),
            );
            let developer_only_attachment = ProofAttachment::new_ref(
                "halo2/mock".into(),
                developer_only_proof.clone(),
                VerifyingKeyId::new("halo2/mock", "vk"),
            );
            let err = validate_proof_attachment(
                &developer_only_attachment,
                &developer_only_proof,
                true,
                Some(&envelope),
            )
            .expect_err("developer-only attachment backend must fail before envelope use");
            let msg = smart_contract_instruction_error_message(err);
            assert!(msg.contains("developer-only"), "unexpected error: {msg}");
            let unsupported_proof = ProofBox::new(
                "halo2/unknown-native-v1".into(),
                norito::to_bytes(&envelope).expect("encode envelope"),
            );
            let unsupported_attachment = ProofAttachment::new_ref(
                "halo2/unknown-native-v1".into(),
                unsupported_proof.clone(),
                VerifyingKeyId::new("halo2/unknown-native-v1", "vk"),
            );
            let err = validate_proof_attachment(
                &unsupported_attachment,
                &unsupported_proof,
                true,
                Some(&envelope),
            )
            .expect_err("unsupported attachment backend must fail before envelope use");
            let msg = smart_contract_instruction_error_message(err);
            assert!(
                msg.contains("unsupported proof backends"),
                "unexpected error: {msg}"
            );
            assert!(!open_verify_backend_tag_matches(
                "halo2/debug",
                BackendTag::Halo2IpaPasta
            ));
            assert!(!open_verify_backend_tag_matches(
                "halo2/mock",
                BackendTag::Halo2IpaPasta
            ));
            assert!(!open_verify_backend_tag_matches(
                "stark/fri/mock",
                BackendTag::Stark
            ));
        }

        #[test]
        fn resolve_vk_commitment_accepts_normalized_circuit_id() {
            let kura = Kura::blank_kura_for_testing();
            let query_handle = LiveQueryStore::start_test();
            let state = State::new(World::default(), kura, query_handle);

            let block = new_dummy_block();
            let mut state_block = state.block(block.as_ref().header());
            let mut stx = state_block.transaction();

            let vk_id = VerifyingKeyId::new("halo2/ipa", "vk_test");
            let vk_box = VerifyingKeyBox::new("halo2/ipa".into(), vec![1, 2, 3, 4]);
            let commitment = hash_vk(&vk_box);
            let mut rec = VerifyingKeyRecord::new_with_owner(
                1,
                TEST_HALO2_CIRCUIT_FULL_ID,
                None,
                "test",
                BackendTag::Halo2IpaPasta,
                "pallas",
                [0u8; 32],
                commitment,
            );
            rec.status = ConfidentialStatus::Active;
            rec.gas_schedule_id = Some("halo2_default".to_string());
            rec.key = Some(vk_box);
            stx.world.verifying_keys.insert(vk_id.clone(), rec.clone());
            stx.world
                .verifying_keys_by_circuit
                .insert((rec.circuit_id.clone(), rec.version), vk_id.clone());

            let proof = ProofBox::new("halo2/ipa".into(), Vec::new());
            let attachment = ProofAttachment::new_ref("halo2/ipa".into(), proof, vk_id);
            let envelope = OpenVerifyEnvelope::new(
                BackendTag::Halo2IpaPasta,
                TEST_HALO2_CIRCUIT_ALIAS,
                commitment,
                vec![1, 2],
                vec![3, 4],
            );
            let resolved = resolve_vk_commitment(&attachment, Some(&envelope), &stx)
                .expect("resolve vk commitment");
            assert_eq!(resolved, Some(commitment));

            let zero_commitment_envelope = OpenVerifyEnvelope::new(
                BackendTag::Halo2IpaPasta,
                TEST_HALO2_CIRCUIT_ALIAS,
                [0u8; 32],
                vec![1, 2],
                vec![3, 4],
            );
            assert!(
                resolve_vk_commitment(&attachment, Some(&zero_commitment_envelope), &stx).is_err(),
                "OpenVerifyEnvelope vk_hash must bind the registered verifying-key commitment"
            );

            let mut aux_envelope = envelope;
            aux_envelope.aux = b"ignored-hint".to_vec();
            assert!(
                resolve_vk_commitment(&attachment, Some(&aux_envelope), &stx).is_err(),
                "OpenVerifyEnvelope aux bytes are not admitted into chain proof records"
            );
        }

