        fn store_exact_sccp_finality_for_test(
            kura: &Kura,
            fixture: &iroha_sccp::SccpExactOutboundTestFixtureV1,
        ) -> (
            iroha_sccp::SccpExactOutboundTestFixtureV1,
            iroha_sccp::TairaBridgeFinalityProofV1,
        ) {
            let provisional_finality =
                iroha_sccp::decode_taira_bridge_finality_proof(&fixture.bundle.finality_proof)
                    .expect("exact provisional SCCP finality fixture decodes");
            let instruction = crate::bridge::test_record_sccp_message(
                canonical_test_sccp_payload_bytes(&fixture.bundle.payload),
            );
            assert_eq!(
                instruction.context, fixture.bundle.commitment.context,
                "exact settlement block instruction must preserve the bundle context"
            );
            let executable = Executable::IvmProved(IvmProved {
                bytecode: IvmBytecode::from_compiled(vec![0x01, 0x02, 0x03]),
                overlay: vec![InstructionBox::from(instruction)].into(),
                events_commitment: Hash::new(b"SCCP retention lifecycle events"),
                gas_policy_commitment: Hash::new(b"SCCP retention lifecycle gas"),
            });
            let transaction = TransactionBuilder::new(
                iroha_data_model::ChainId::from(iroha_sccp::SCCP_TAIRA_FINALITY_CHAIN_ID_V1),
                ALICE_ID.clone(),
                iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
            )
            .with_executable(executable)
            .sign(ALICE_KEYPAIR.private_key());
            let entry_hash = transaction.hash_as_entrypoint();
            let template_header = provisional_finality.block_header;
            let mut provisional_header = BlockHeader::new(
                template_header.height(),
                template_header.prev_block_hash(),
                None,
                None,
                u64::try_from(template_header.creation_time().as_millis())
                    .expect("fixture creation time fits u64"),
                template_header.view_change_index(),
            );
            provisional_header.set_sccp_commitment_root(template_header.sccp_commitment_root());
            let signature = BlockSignature::new(
                0,
                SignatureOf::try_from_hash(ALICE_KEYPAIR.private_key(), provisional_header.hash())
                    .expect("sign provisional SCCP retained header fixture"),
            );
            let mut block =
                SignedBlock::presigned(signature, provisional_header, vec![transaction]);
            block
                .set_transaction_results(
                    Vec::new(),
                    &[entry_hash],
                    vec![TransactionResultInner::Ok(DataTriggerSequence::default())],
                )
                .expect("attach successful exact SCCP transaction result");
            assert!(
                provisional_finality
                    .finality_artifact
                    .validate_for_header(&block.header())
                    .is_err(),
                "pre-finalization artifact must reject the completed settlement block"
            );
            let signature = BlockSignature::new(
                0,
                SignatureOf::try_from_hash(ALICE_KEYPAIR.private_key(), block.hash())
                    .expect("sign completed SCCP retained header fixture"),
            );
            block
                .replace_signatures([signature].into_iter().collect())
                .expect("replace provisional SCCP retained signature");
            block
                .signatures()
                .next()
                .expect("completed SCCP retained signature")
                .signature()
                .verify_hash(ALICE_KEYPAIR.public_key(), block.hash())
                .expect("completed SCCP retained signature verifies");
            crate::bridge::validate_sccp_commitment_root_for_signed_block(&block)
                .expect("completed settlement block authenticates its exact SCCP message");

            let fixture = fixture.with_finalized_block(&block, None);
            let finality =
                iroha_sccp::decode_taira_bridge_finality_proof(&fixture.bundle.finality_proof)
                    .expect("exact completed SCCP finality fixture decodes");
            assert_eq!(block.header(), finality.block_header);
            assert_eq!(block.hash(), finality.finality_artifact.block_hash);
            assert_eq!(
                fixture.request.public_inputs.finality_block_hash,
                <[u8; 32]>::from(Hash::from(block.hash()))
            );
            finality
                .finality_artifact
                .validate_for_header(&block.header())
                .expect("completed settlement artifact binds the exact block header");
            finality
                .finality_artifact
                .verify()
                .expect("completed settlement artifact is cryptographically valid");
            kura.persist_block_with_retained_archive_for_tests(&Arc::new(block))
                .expect("store exact SCCP finalized block and retained archive fixture");
            let _receipt = kura
                .store_v2_finality_artifact(&finality.finality_artifact)
                .expect("store exact SCCP retained finality fixture");
            (fixture, finality)
        }

        fn configure_native_sccp_settlement_for_test(
            stx: &mut StateTransaction<'_, '_>,
            registry: Arc<crate::state::ValidatedSccpRegistryV1>,
            asset_spec: NumericSpec,
            custody_amount: Quantity,
        ) -> (AssetDefinitionId, AccountId) {
            *stx.world.sccp_registry.get_mut() = registry.to_wire();
            stx.sccp_registry = registry;
            stx.chain_id =
                iroha_data_model::ChainId::from(iroha_sccp::SCCP_TAIRA_FINALITY_CHAIN_ID_V1);
            stx.zk.max_proof_size_bytes = 32 * 1024 * 1024;
            let (asset, custody) = sccp_test_settlement_ids(stx);
            for account in [ALICE_ID.clone(), custody.clone()] {
                if stx.world.account(&account).is_err() {
                    Register::account(Account::new(account))
                        .execute(&ALICE_ID, stx)
                        .expect("register SCCP settlement account fixture");
                }
            }
            if stx.world.asset_definition(&asset).is_err() {
                Register::asset_definition(
                    AssetDefinition::new(asset.clone(), asset_spec).with_name("xor".to_owned()),
                )
                .execute(&ALICE_ID, stx)
                .expect("register SCCP settlement asset fixture");
            }
            if !custody_amount.is_zero() {
                Mint::asset_quantity(custody_amount, AssetId::new(asset.clone(), custody.clone()))
                    .execute(&ALICE_ID, stx)
                    .expect("fund SCCP custody fixture");
            }
            (asset, custody)
        }

        fn restricted_shield_fixture(
            account_uaid: Option<UniversalAccountId>,
            bindings: &[(UniversalAccountId, DataSpaceId)],
            balances: &[(AssetBalanceScope, u64)],
        ) -> (State, AssetDefinitionId, Vec<AssetId>) {
            let domain_id: DomainId =
                DomainId::try_new("wonderland", "universal").expect("domain id parses");
            let domain = Domain::new(domain_id.clone()).build(&ALICE_ID);
            let account = new_account_in_domain(&ALICE_ID)
                .with_uaid(account_uaid)
                .build(&ALICE_ID);
            let asset_def_id =
                AssetDefinitionId::new(domain_id.clone(), "ticket".parse().expect("asset name"));
            let mut asset_definition = AssetDefinition::numeric(asset_def_id.clone())
                .with_name(asset_def_id.name().to_string())
                .with_balance_scope_policy(AssetBalancePolicy::DataspaceRestricted)
                .confidential_policy(AssetConfidentialPolicy::convertible())
                .build(&ALICE_ID);
            asset_definition.total_quantity =
                balances
                    .iter()
                    .fold(Quantity::zero(), |total, (_, amount)| {
                        total
                            .checked_add(&Quantity::from(*amount))
                            .expect("restricted shield fixture total must not overflow")
                    });
            let asset_ids: Vec<_> = balances
                .iter()
                .map(|(scope, _)| {
                    AssetId::with_scope(asset_def_id.clone(), ALICE_ID.clone(), *scope)
                })
                .collect();
            let assets: Vec<_> = asset_ids
                .iter()
                .zip(balances.iter())
                .map(|(asset_id, (_, amount))| {
                    Asset::new(asset_id.clone(), Quantity::from(*amount))
                })
                .collect();
            let mut world = World::with_assets([domain], [account], [asset_definition], assets, []);
            world.zk_assets.insert(asset_def_id.clone(), {
                let mut state = crate::state::ZkAssetState::default();
                state.mode = iroha_data_model::isi::zk::ZkAssetMode::Hybrid;
                state.allow_shield = true;
                state
            });

            let kura = Kura::blank_kura_for_testing();
            let query_handle = LiveQueryStore::start_test();
            let mut state = State::new(world, kura, query_handle);
            let mut grouped: BTreeMap<
                UniversalAccountId,
                crate::nexus::space_directory::UaidDataspaceBindings,
            > = BTreeMap::new();
            for (uaid, dataspace) in bindings {
                grouped
                    .entry(*uaid)
                    .or_default()
                    .bind_account(*dataspace, ALICE_ID.clone());
            }
            for (uaid, bindings) in grouped {
                state.world.uaid_accounts.insert(uaid, ALICE_ID.clone());
                state.world.uaid_dataspaces.insert(uaid, bindings);
            }
            (state, asset_def_id, asset_ids)
        }

        fn shield_amount(
            stx: &mut StateTransaction<'_, '_>,
            asset_def_id: &AssetDefinitionId,
            amount: u128,
        ) -> Result<(), InstructionExecutionError> {
            shield_amount_with_payload(
                stx,
                asset_def_id,
                amount,
                valid_confidential_encrypted_payload_for_tests(),
            )
        }

        fn shield_amount_with_payload(
            stx: &mut StateTransaction<'_, '_>,
            asset_def_id: &AssetDefinitionId,
            amount: u128,
            enc_payload: iroha_data_model::confidential::ConfidentialEncryptedPayload,
        ) -> Result<(), InstructionExecutionError> {
            iroha_data_model::isi::zk::Shield::new(
                asset_def_id.clone(),
                ALICE_ID.clone(),
                amount,
                [3; 32],
                enc_payload,
            )
            .execute(&ALICE_ID, stx)
        }

        fn valid_confidential_encrypted_payload_for_tests()
        -> iroha_data_model::confidential::ConfidentialEncryptedPayload {
            iroha_data_model::confidential::ConfidentialEncryptedPayload::new(
                [0x07; 32],
                [0x08; 24],
                vec![0x09, 0x0A],
            )
        }

        fn quantity_balance(stx: &StateTransaction<'_, '_>, asset_id: &AssetId) -> Quantity {
            stx.world
                .assets
                .get(asset_id)
                .expect("asset balance exists")
                .as_ref()
                .clone()
        }

        fn commitment_count(
            stx: &StateTransaction<'_, '_>,
            asset_def_id: &AssetDefinitionId,
        ) -> usize {
            stx.world
                .zk_assets
                .get(asset_def_id)
                .map_or(0, |state| state.commitments.len())
        }

        #[test]
        fn shield_rejects_invalid_confidential_payload_before_state_change() {
            let dataspace = DataSpaceId::new(7);
            let (state, asset_def_id, asset_ids) = restricted_shield_fixture(
                None,
                &[],
                &[(AssetBalanceScope::Dataspace(dataspace), 10)],
            );
            let block = new_dummy_block();
            let mut state_block = state.block(block.as_ref().header());
            let mut stx = state_block.transaction();
            stx.current_dataspace_id = Some(dataspace);
            stx.world.current_dataspace_id = Some(dataspace);

            for (payload, expected) in [
                (
                    iroha_data_model::confidential::ConfidentialEncryptedPayload::new(
                        [0u8; 32],
                        [0x08; 24],
                        vec![0x09],
                    ),
                    "low-order",
                ),
                (
                    iroha_data_model::confidential::ConfidentialEncryptedPayload::new(
                        [0x07; 32],
                        [0x08; 24],
                        Vec::new(),
                    ),
                    "ciphertext must not be empty",
                ),
            ] {
                let err = shield_amount_with_payload(&mut stx, &asset_def_id, 3, payload)
                    .expect_err("invalid confidential payload must fail closed");
                let msg = smart_contract_instruction_error_message(err);
                assert!(msg.contains(expected), "expected `{expected}` in `{msg}`");
                assert_eq!(
                    quantity_balance(&stx, &asset_ids[0]),
                    Quantity::from(10_u32)
                );
                assert_eq!(commitment_count(&stx, &asset_def_id), 0);
            }
        }

        #[test]
        fn shield_restricted_asset_uses_unique_account_dataspace_on_universal_route() {
            let dataspace = DataSpaceId::new(7);
            let uaid = UniversalAccountId::from_hash(Hash::new(b"uaid::shield-source"));
            let (state, asset_def_id, asset_ids) = restricted_shield_fixture(
                Some(uaid),
                &[(uaid, dataspace)],
                &[(AssetBalanceScope::Dataspace(dataspace), 10)],
            );
            let scoped_asset_id = asset_ids[0].clone();
            let block = new_dummy_block();
            let mut state_block = state.block(block.as_ref().header());
            let mut stx = state_block.transaction();
            stx.current_dataspace_id = Some(DataSpaceId::UNIVERSAL);
            stx.world.current_dataspace_id = Some(DataSpaceId::UNIVERSAL);
            assert!(
                stx.world
                    .uaid_dataspaces
                    .iter()
                    .any(|(_, bindings)| bindings.is_bound_to(dataspace, &ALICE_ID)),
                "fixture must expose the account dataspace binding"
            );
            assert_eq!(
                crate::smartcontracts::isi::asset::isi::unique_account_dataspace_hint(
                    &stx, &ALICE_ID
                )
                .expect("dataspace hint resolves"),
                Some(dataspace)
            );

            shield_amount(&mut stx, &asset_def_id, 3)
                .expect("shield must debit the account's scoped transparent balance");

            assert_eq!(
                quantity_balance(&stx, &scoped_asset_id),
                Quantity::from(7_u32)
            );
            let universal_asset_id = AssetId::with_scope(
                asset_def_id.clone(),
                ALICE_ID.clone(),
                AssetBalanceScope::Dataspace(DataSpaceId::UNIVERSAL),
            );
            assert!(
                stx.world.assets.get(&universal_asset_id).is_none(),
                "universal route must not debit a universal bucket when the account has one private dataspace binding"
            );
            assert_eq!(commitment_count(&stx, &asset_def_id), 1);
        }

