            state_block.replay_compatibility = true;
            let mut stx = state_block.transaction();
            let (proof, _native, registry) = native_ethereum_bridge_proof_for_payload_for_test(
                sccp_native_inbound_transfer_payload_for_test(79, 7),
            );
