        #[test]
        fn record_bridge_receipt_rejects_sccp_transfer_receipt_payload_mismatches() {
            #[derive(Clone, Copy)]
            enum ReceiptMismatch {
                Direction,
                SourceTx,
                DestTx,
                Amount,
                AssetId,
                Recipient,
            }

            for (index, mismatch) in [
                ReceiptMismatch::Direction,
                ReceiptMismatch::SourceTx,
                ReceiptMismatch::DestTx,
                ReceiptMismatch::Amount,
                ReceiptMismatch::AssetId,
                ReceiptMismatch::Recipient,
            ]
            .into_iter()
            .enumerate()
            {
                let kura = Kura::blank_kura_for_testing();
                let query_handle = LiveQueryStore::start_test();
                let state = State::new(World::default(), kura, query_handle);

                let block = new_dummy_block();
                let mut state_block = state.block(block.as_ref().header());
                let mut stx = state_block.transaction();

                let artifact = sccp_message_artifact_for_receipt_test(
                    sccp_transfer_payload_for_receipt_test(60 + index as u64),
                    10 + index as u8,
                );
                let proof = sccp_bridge_proof_for_receipt_test(&artifact);
                let proof_hash = insert_bridge_proof_record_for_receipt_test(&mut stx, proof);
                set_current_lane_for_test(&mut stx, LaneId::SINGLE);
                let mut receipt = sccp_bridge_receipt_for_receipt_test(proof_hash, &artifact);
                let baseline = receipt.clone();
                match mismatch {
                    ReceiptMismatch::Direction => {
                        receipt.direction = if receipt.direction == b"release" {
                            b"mint".to_vec()
                        } else {
                            b"release".to_vec()
                        };
                    }
                    ReceiptMismatch::SourceTx => {
                        receipt.source_tx[0] ^= 0xFF;
                    }
                    ReceiptMismatch::DestTx => {
                        receipt.dest_tx = Some([0xD5; 32]);
                    }
                    ReceiptMismatch::Amount => {
                        receipt.amount = receipt
                            .amount
                            .checked_add(&Quantity::from(1_u64))
                            .expect("fixture receipt amount increment must fit");
                    }
                    ReceiptMismatch::AssetId => {
                        receipt.asset_id.push(b'!');
                    }
                    ReceiptMismatch::Recipient => {
                        receipt.recipient.push(b'!');
                    }
                }
                assert_ne!(
                    receipt, baseline,
                    "mismatch case {index} must change the signed receipt projection"
                );

                let err = RecordBridgeReceipt::new(receipt)
                    .execute(&ALICE_ID, &mut stx)
                    .expect_err("forged SCCP receipt field must reject");
                assert!(
                    format!("{err:?}").contains("complete proof-derived projection"),
                    "unexpected error for mismatch {index}: {err:?}"
                );
                assert!(
                    stx.bridge_receipt_proofs_available_in_tx
                        .contains(&proof_hash),
                    "failed SCCP receipt validation must not consume proof marker"
                );
                assert!(stx.world.internal_event_buf.iter().all(|event| {
                    !matches!(event.as_ref(), DataEvent::Bridge(BridgeEvent::Emitted(_)))
                }));

                RecordBridgeReceipt::new(baseline.clone())
                    .execute(&ALICE_ID, &mut stx)
                    .expect("the exact destination proof projection must remain retryable");
                assert!(
                    !stx.bridge_receipt_proofs_available_in_tx
                        .contains(&proof_hash),
                    "the corrected destination receipt must consume its marker exactly once"
                );
                let emitted: Vec<_> = stx
                    .world
                    .internal_event_buf
                    .iter()
                    .filter_map(|event| match event.as_ref() {
                        DataEvent::Bridge(BridgeEvent::Emitted(emitted)) => Some(emitted),
                        _ => None,
                    })
                    .collect();
                assert_eq!(emitted, vec![&baseline]);
            }
        }

        #[test]
        fn record_bridge_receipt_allows_corrected_sccp_receipt_after_failed_validation() {
            let kura = Kura::blank_kura_for_testing();
            let query_handle = LiveQueryStore::start_test();
            let state = State::new(World::default(), kura, query_handle);

            let block = new_dummy_block();
            let mut state_block = state.block(block.as_ref().header());
            let mut stx = state_block.transaction();

            let artifact = sccp_message_artifact_for_receipt_test(
                sccp_transfer_payload_for_receipt_test(68),
                18,
            );
            let proof = sccp_bridge_proof_for_receipt_test(&artifact);
            let proof_hash = insert_bridge_proof_record_for_receipt_test(&mut stx, proof);
            set_current_lane_for_test(&mut stx, LaneId::SINGLE);
            let receipt = sccp_bridge_receipt_for_receipt_test(proof_hash, &artifact);
            let mut forged_receipt = receipt.clone();
            forged_receipt.amount = forged_receipt
                .amount
                .checked_add(&Quantity::from(1_u64))
                .expect("fixture receipt amount increment must fit");

            let err = RecordBridgeReceipt::new(forged_receipt)
                .execute(&ALICE_ID, &mut stx)
                .expect_err("forged SCCP receipt must reject");
            assert!(
                format!("{err:?}").contains("complete proof-derived projection"),
                "unexpected error: {err:?}"
            );
            assert!(
                stx.bridge_receipt_proofs_available_in_tx
                    .contains(&proof_hash),
                "failed validation must leave the fresh proof available"
            );
            assert!(stx.world.internal_event_buf.iter().all(|event| {
                !matches!(event.as_ref(), DataEvent::Bridge(BridgeEvent::Emitted(_)))
            }));

            RecordBridgeReceipt::new(receipt.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("corrected SCCP receipt should consume the proof");
            assert!(
                !stx.bridge_receipt_proofs_available_in_tx
                    .contains(&proof_hash),
                "corrected receipt must consume the fresh proof exactly once"
            );

            let emitted: Vec<_> = stx
                .world
                .internal_event_buf
                .iter()
                .filter_map(|event| match event.as_ref() {
                    DataEvent::Bridge(BridgeEvent::Emitted(emitted)) => Some(emitted),
                    _ => None,
                })
                .collect();
            assert_eq!(emitted, vec![&receipt]);
        }

        #[test]
        fn native_bridge_receipt_binds_every_field_and_allows_exact_correction() {
            #[derive(Clone, Copy)]
            enum ReceiptMismatch {
                Direction,
                SourceTx,
                DestTx,
                Amount,
                AssetId,
                Recipient,
            }

            let (proof, _, _) = native_ethereum_bridge_proof_for_payload_for_test(
                sccp_native_inbound_transfer_payload_for_test(160, 20),
            );
            for (index, mismatch) in [
                ReceiptMismatch::Direction,
                ReceiptMismatch::SourceTx,
                ReceiptMismatch::DestTx,
                ReceiptMismatch::Amount,
                ReceiptMismatch::AssetId,
                ReceiptMismatch::Recipient,
            ]
            .into_iter()
            .enumerate()
            {
                let state = State::new(
                    World::default(),
                    Kura::blank_kura_for_testing(),
                    LiveQueryStore::start_test(),
                );
                let block = new_dummy_block();
                let mut state_block = state.block(block.as_ref().header());
                let mut stx = state_block.transaction();
                let proof_hash =
                    insert_bridge_proof_record_for_receipt_test(&mut stx, proof.clone());
                set_current_lane_for_test(&mut stx, LaneId::SINGLE);
                stx.world.internal_event_buf.clear();
                let receipt = sccp_bridge_receipt_for_proof_test(proof_hash, &proof);
                assert!(
                    receipt.dest_tx.is_none(),
                    "SCCP V1 authenticates no dest_tx"
                );
                let mut forged = receipt.clone();
                match mismatch {
                    ReceiptMismatch::Direction => forged.direction.push(b'!'),
                    ReceiptMismatch::SourceTx => forged.source_tx[0] ^= 0xFF,
                    ReceiptMismatch::DestTx => forged.dest_tx = Some([0xD6; 32]),
                    ReceiptMismatch::Amount => {
                        forged.amount = forged
                            .amount
                            .checked_add(&Quantity::from(1_u64))
                            .expect("fixture receipt amount increment must fit");
                    }
                    ReceiptMismatch::AssetId => forged.asset_id.push(b'!'),
                    ReceiptMismatch::Recipient => forged.recipient.push(b'!'),
                }
                assert_ne!(forged, receipt, "mismatch case {index} must alter receipt");

                let error = RecordBridgeReceipt::new(forged)
                    .execute(&ALICE_ID, &mut stx)
                    .expect_err("a forged native SCCP receipt field must fail closed");
                assert!(
                    format!("{error:?}").contains("complete proof-derived projection"),
                    "unexpected native mismatch {index} error: {error:?}"
                );
                assert!(
                    stx.bridge_receipt_proofs_available_in_tx
                        .contains(&proof_hash),
                    "failed native receipt validation must preserve the proof marker"
                );
                assert!(stx.world.internal_event_buf.is_empty());

                RecordBridgeReceipt::new(receipt.clone())
                    .execute(&ALICE_ID, &mut stx)
                    .expect("the exact native proof projection must remain retryable");
                assert!(
                    !stx.bridge_receipt_proofs_available_in_tx
                        .contains(&proof_hash),
                    "the corrected receipt must consume the proof marker exactly once"
                );
                let emitted: Vec<_> = stx
                    .world
                    .internal_event_buf
                    .iter()
                    .filter_map(|event| match event.as_ref() {
                        DataEvent::Bridge(BridgeEvent::Emitted(emitted)) => Some(emitted),
                        _ => None,
                    })
                    .collect();
                assert_eq!(emitted, vec![&receipt]);
            }
        }

        #[test]
        fn sccp_outbound_proof_replay_index_detects_distinct_artifact_same_message() {
            let kura = Kura::blank_kura_for_testing();
            let query_handle = LiveQueryStore::start_test();
            let state = State::new(World::default(), kura, query_handle);

            let block = new_dummy_block();
            let mut state_block = state.block(block.as_ref().header());
            let mut stx = state_block.transaction();

            let original_artifact = sccp_message_artifact_for_receipt_test(
                sccp_transfer_payload_for_receipt_test(91),
                41,
            );
            let original_key = sccp_outbound_proof_key_for_test(&original_artifact);
            let original_hash = [0xD1; 32];
            let original_record =
                sccp_outbound_proof_record_for_test(&original_artifact, original_hash);
            stx.world
                .sccp_outbound_proofs
                .insert(original_key, original_record);

            // A malformed historical proof payload must be irrelevant to the
            // fixed replay lookup. This record would be undecodable as a
            // destination artifact if the removed historical scan touched it.
            let poisoned_proof = BridgeProof {
                range: BridgeProofRange {
                    start_height: 1,
                    end_height: 1,
                },
                payload: BridgeProofPayload::SccpDestination(
                    iroha_data_model::bridge::BridgeSccpDestinationProofV1 {
                        backend: iroha_data_model::bridge::BridgeSccpDestinationProofBackendV1::EvmGroth16Bn254,
                        route_configuration_hash: [0xE1; 32],
                        encoded_artifact: vec![0xFF; 257],
                    },
                ),
            };
            insert_bridge_proof_record_for_receipt_test(&mut stx, poisoned_proof);

            let replay_artifact = sccp_message_artifact_for_receipt_test(
                sccp_transfer_payload_for_receipt_test(91),
                42,
            );
            let replay_key = sccp_outbound_proof_key_for_test(&replay_artifact);
            assert_eq!(
                original_key, replay_key,
                "fixture must preserve the replayed SCCP message identity"
            );
            assert_eq!(
                stx.world.sccp_outbound_proofs.get(&replay_key),
                Some(&original_record),
                "one logarithmic map lookup must detect the replay without decoding proof history"
            );

            let distinct_artifact = sccp_message_artifact_for_receipt_test(
                sccp_transfer_payload_for_receipt_test(92),
                43,
            );
            assert!(
                stx.world
                    .sccp_outbound_proofs
                    .get(&sccp_outbound_proof_key_for_test(&distinct_artifact))
                    .is_none(),
                "distinct SCCP message ids must not conflict"
            );
        }

        #[test]
        fn sccp_outbound_proof_record_binds_payload_destination_and_route() {
            let artifact = sccp_message_artifact_for_receipt_test(
                sccp_transfer_payload_for_receipt_test(95),
                45,
            );
            let record = sccp_outbound_proof_record_for_test(&artifact, [0xD2; 32]);
            assert_eq!(record.payload_hash, artifact.bundle.commitment.payload_hash);
            assert_eq!(
                record.destination_binding_hash,
                artifact.destination_binding_hash
            );
            assert_eq!(
                record.route_configuration_hash,
                artifact.route_configuration_hash
            );
            for drifted in [
                iroha_data_model::bridge::SccpOutboundProofRecordV1 {
                    payload_hash: [0xA1; 32],
                    ..record
                },
                iroha_data_model::bridge::SccpOutboundProofRecordV1 {
                    destination_binding_hash: [0xA2; 32],
                    ..record
                },
                iroha_data_model::bridge::SccpOutboundProofRecordV1 {
                    route_configuration_hash: [0xA3; 32],
                    ..record
                },
            ] {
                assert_ne!(drifted, record);
            }
        }

        #[test]
        fn sccp_outbound_proof_index_allows_distinct_messages_at_same_finality_height() {
            let kura = Kura::blank_kura_for_testing();
            let query_handle = LiveQueryStore::start_test();
            let state = State::new(World::default(), kura, query_handle);

            let block = new_dummy_block();
            let mut state_block = state.block(block.as_ref().header());
            let mut stx = state_block.transaction();

            let first_artifact = sccp_message_artifact_for_receipt_test(
                sccp_transfer_payload_for_receipt_test(101),
                50,
            );
            let first_proof = sccp_bridge_proof_for_receipt_test(&first_artifact);
            insert_bridge_proof_record_for_receipt_test(&mut stx, first_proof);
            let first_key = sccp_outbound_proof_key_for_test(&first_artifact);
            let first_record = sccp_outbound_proof_record_for_test(&first_artifact, [0xD3; 32]);
            stx.world
                .sccp_outbound_proofs
                .insert(first_key, first_record);

            let second_artifact = sccp_message_artifact_for_receipt_test(
                sccp_transfer_payload_for_receipt_test(102),
                50,
            );
            let second_proof = sccp_bridge_proof_for_receipt_test(&second_artifact);
            let second_key = sccp_outbound_proof_key_for_test(&second_artifact);
            let second_record = sccp_outbound_proof_record_for_test(&second_artifact, [0xD4; 32]);
            assert_ne!(first_key, second_key);
            assert_eq!(first_record.finality_height, second_record.finality_height);
            stx.world
                .sccp_outbound_proofs
                .insert(second_key, second_record);
            assert_eq!(stx.world.sccp_outbound_proofs.len(), 2);
            assert!(
                find_overlapping_bridge_range(
                    &stx,
                    &second_proof.backend_label(),
                    &second_proof.range,
                )
                .is_some(),
                "fixture must share the same backend and finality range"
            );
            assert!(
                find_bridge_range_overlap_conflict(
                    &stx,
                    &second_proof.backend_label(),
                    &second_proof.range,
                    true,
                )
                .is_none(),
                "SCCP message proofs use message-id replay indexing, not range exclusion"
            );
            assert!(
                find_bridge_range_overlap_conflict(
                    &stx,
                    &second_proof.backend_label(),
                    &second_proof.range,
                    false,
                )
                .is_some(),
                "generic bridge proofs must still reject overlapping backend ranges"
            );
        }

        #[test]
